WITH payload AS (SELECT $archive_payload$[{"id":"8cfe92cb-b9f4-5ad8-bfe2-a338828f7ef1","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة مطعم -سرقة مبالغ مالية وأسطوانات غاز من املطعم -إقرار حتقيق ا -رجوع عن إقرار -طلب إقامة حد السرقة- درء حد السرقة -التعزير بالسجن واجللد.","document_number":"33410091","case_number":"33427209","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باجلبيل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/09/12","year":"1434","subject":"سرقة -سرقة مطعم -سرقة مبالغ مالية وأسطوانات غاز من املطعم -إقرار حتقيق ا -رجوع عن إقرار -طلب إقامة حد السرقة- درء حد السرقة -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 33410091:‬تاريخه ‪1433/09/12:‬هـ‬\n                          ‫رقم الدعوى ‪33427209:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n           ‫االستئناف‪ 34177772:‬تاريخه‪1434/4/2 :‬ه‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة مطعــم ‪ -‬ســرقة مبالــغ ماليــة وأســطوانات غــاز مــن‬\n      ‫املطعــم ‪ -‬إقــرار حتقيقـ ًا ‪ -‬رجــوع عــن إقــرار ‪ -‬طلــب إقامــة حــد الســرقة‪-‬‬\n                                 ‫درء حــد الســرقة‪ -‬التعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه صلــى اهلل عليــه وســلم (فــإن دماءكــم وأموالكــم وأعراضكــم‬\n      ‫بينكــم حــرام كحرمــة يومكــم هــذا يف شــهركم هــذا يف بلدكــم هــذا)‬\n                                                                    ‫متفــق عليــه‪.‬‬\n      ‫‪ -2‬قولــه صلــى اهلل عليــه وســلم (كل املســلم علــى املســلم حــرام دمــه‬\n                                                   ‫ومالــه وعرضــه) رواه مســلم‪.‬‬\n\n\n\n\n      ‫دعــوى املدعــي العــام ضــد املدعــى عليهمــا بكســر قفــل البــاب‬\n      ‫الرئيســي ألحــد املطاعــم وســرقة صنــدوق احملاســبة منــه وســرقة مبلــغ‬\n      ‫مالــي وكســر قفــل صندوقــه وســرقة أســطوانات منــه‪ ،‬مــع حتريــز‬\n      ‫األســطوانات مبــا جــرت العــادة بــه ‪ .‬طلــب املدعــى العــام إقامــة حــد‬\n      ‫الســرقة‪،‬مت القبــض علــى املدعــى عليهمــا بعــد بــاغ يفيــد بتعــرض أحــد‬\n      ‫املطاعــم للســرقة وبعــد البحــث والتحــري مت االشــتباه باملدعــى عليهمــا‬\n      ‫وقبــض عليهمــا وباســتجوابهما أقــرا مبــا نســب إليهمــا حتقيقـاً‪ ،‬اعتــرف‬\n\n‫‪363‬‬\n\f‫املدعــى عليهمــا بالدعــوى دون كســر قفــل بــاب املطعــم‪ ،‬وجــد إقراريــن‬\n‫للمدعــى عليهمــا حتقيقـ ًا بكســر قفــل بــاب املطعــم‪ ،‬رجعــا عــن اإلقــرار‬\n‫حتقيق ـاً‪ ،‬مت درء حــد الســرقة عــن املدعــى عليهمــا‪ ،‬وتعزيــر املدعــى‬\n‫عليهمــا بالســجن واجللــد‪ ،‬مت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬فلدينـ ّا‬\n‫نحــن ‪ ......‬و ‪ ......‬و ‪ ......‬القضــاة باحملكمــة العامــة باجلبيــل وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة برقــم ‪33427209‬‬\n‫وتاريــخ ‪1433/06/25‬ه ـ واملقيــدة برقــم ‪ 331200046‬وتأريــخ‬\n‫‪1433/06/25‬ه ـ ويف يــوم االثنــن ‪1433/07/21‬ه ـ الســاعة العاشــرة‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي العــام بهيئــة التحقيــق واإلدعــاء‬\n‫العــام مبحافظــة اجلبيــل ‪ .......‬واملدعــى عليــه األول ‪ ........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )......‬واملدعــى عليــه الثانــي ‪ .........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬وبســؤال املدعــي العــام عــن‬\n            ‫دعــواه قــدم الئحــة دعــوى عامــة وطلــب ضبطهــا وهــذا نصهــا‪:‬‬\n‫بصفتــي مدعيـ ًا عامـ ًا بدائــرة التحقيــق واإلدعــاء العــام مبحافظــة اجلبيــل‬\n                                              ‫أدعــي علــى كل مــن املواطنــن ‪-:‬‬\n‫‪ ، ......... -1‬مبوجــب الســجل املدنــي رقــم (‪ ).......‬البالــغ مــن العمــر (‪)19‬‬\n‫عامـ ًا ‪ ،‬موقــوف لــدى ســجن محافظــة اجلبيــل مبوجــب مذكــرة التوقيف‬\n                      ‫رقــم (‪ /638/10/21/21‬م ف) وتاريــخ ‪1433/4/5‬هـ‪.‬‬\n‫‪ ،........... -2‬مبوجــب الســجل املدنــي رقــم (‪ ).......‬البالــغ مــن العمــر‬\n\n                                                                                       ‫‪364‬‬\n\f      ‫(‪ )19‬عام ـ ًا ‪ ،‬موقــوف لــدى ســجن محافظــة اجلبيــل مبوجــب مذكــرة‬\n      ‫التوقيــف رقــم (‪ /637/21/21‬م ف) وتاريــخ ‪1433/4/5‬هــ‪ .‬حيــث‬\n      ‫أنــه بتاريــخ ‪1433/3/26‬ه ـ ورد بــاغ مــن املقيــم‪« ..........‬مصــري‬\n      ‫اجلنســية» للدوريــات األمنيــة يفيــد فيــه عــن تعــرض مطعــم ‪ ........‬الــذي‬\n      ‫يعمــل بــه والواقــع ‪ ........‬لكســر قفــل البــاب الرئيســي وســرقة عــدد‬\n      ‫(‪ )9‬تســع (اســطوانات) غــاز وصنــدوق (الكاشــير) والــذي يحتــوي‬\n      ‫علــى مبلــغ مالــي قــدره (‪ )1200‬ألــف ومائتــن ريــا ًال وذلــك بعــد إغــاق‬\n      ‫احملــل نهايــة فتــرة عملهــم باملطعــم ‪ ،‬وبالبحــث والتحــري عــن املدعــى‬\n      ‫عليهمــا توفــرت معلومــات للبحــث اجلنائــي أن املدعــى عليــه األول قــام‬\n      ‫بتحميــل عــدد مــن (األســطوانات) رفــق شــخص آخــر والذا بالهــرب‪.‬‬\n      ‫وبتاريــخ ‪1433/3/27‬ه ـ توفــرت معلومــات للبحــث اجلنائــي عــن قيــام‬\n      ‫املدعــى عليهمــا بتحميــل عــدد (‪ )9‬تســع أســطوانات مــن ســيارة نــوع‬\n      ‫‪ .......‬إلــى ســيارة مــن نــوع ‪ ........‬وعنــد متابعتهمــا الذا بالفــرار ويشــتبه أن‬\n      ‫تكــون هــي نفــس اســطوانات الغــاز املســروقة مــن املطعــم‪ .‬وباالنتقــال‬\n      ‫ومعاينــة موقــع املطعــم املذكــور اتضــح أنــه يقــع علــى الواجهــة البحريــة‬\n      ‫لكورنيــش ‪ .............‬وبتاريــخ ‪1433/3/27‬ه ـ مت القبــض علــى املدعــى‬\n      ‫عليــه الثانــي (‪ )......‬وحضــر املدعــى عليــه األول (‪ ).....‬وســلم نفســه بعــد‬\n      ‫أن علــم بحضــور أفــراد التحــري والبحــث اجلنائــي لطلبــه ‪ ،‬وبالتحقــق‬\n      ‫مــن الســيارة مــن نــوع (فــورد) حتمــل اللوحــة رقــم (‪ ).... ...‬تبــن أنهــا تعــود‬\n      ‫للمواطــن ‪ ، ....... /‬وأنــه ليــس لــه عالقــة بالقضيــة فجــرى تســليمها لــه‪.‬‬\n      ‫وباســتجواب املدعــى عليــه األول (‪ )....‬أفــاد أنــه يف مســاء يــوم اجلمعــة‬\n      ‫املوافــق ‪1433/3/25‬ه ـ اتفــق مــع زميلــه املدعــى عليــه الثانــي (‪ )......‬على‬\n      ‫ســرقة بوفيــة (‪ )............‬بالواجهــة البحريــة وتوجهــا ملوقــع (البوفيــة) عنــد‬\n\n\n‫‪365‬‬\n\f‫الســاعة (‪ )2:00‬الثانيــة بعــد منتصــف الليــل وتوقفــا بســيارته مــن نــوع‬\n‫(فــورد) أمــام البوفيــة وترجــا مــن الســيارة وقــام املدعــى عليــه الثانــي‬\n‫(‪ ).....‬بأخــذ مفتــاح العجــل ثــم توجهــا إلــى الصنــدوق احلديــدي الــذي‬\n‫يحتــوي علــى (اســطوانات) الغــاز وحــاول كســر قفلــه ولــم يســتطع ثــم‬\n‫قــام بخلــع بــاب (البوفيــة) مبفتــاح العجــل ودخــا لداخــل البوفيــة وقامــا‬\n‫بســرقة صنــدوق (الكاشــير) وخرجــا مــن (البوفيــه) وركبــا ســيارته‬\n‫ثــم توجهــا إلــى الكورنيــش وجلســا مقابــل ‪ .......‬وقامــا بفتــح الصنــدوق‬\n‫وعثــرا بداخلــه علــى مبلــغ مالــي وقــدره (‪ )1300‬ألــف وثالثمائــة ريــا ًال‬\n‫تقريبـ ًا ومجموعــة مــن املفاتيــح وصــور عمــال ثــم رجعــا مــرة أخــرى إلــى‬\n‫(البوفيــة) وقامــا بفتــح قفــل صنــدوق (االســطوانات) باملفتــاح الــذي‬\n‫عثــرا عليــه داخــل الصنــدوق وســرقا عــدد (‪ )9‬تســع اســطوانات (غــاز)‬\n‫ووضعهــا بداخــل ســيارته ثــم توجهــا إلــى ‪ ......‬ويف الطريــق قامــا برمــي‬\n‫صنــدوق (الكاشــير) بالقــرب مــن (كبــري) ‪ .....‬ثــم ذهبــا إلــى املنــزل‬\n‫وتوقــف بالســيارة أمــا املنــزل و(االســطوانات) بداخلهــا ‪ ،‬وقــد تصــرف‬\n     ‫بجــزء مــن املبلــغ بينمــا أخــذ املدعــى عليــه الثانــي (‪ )......‬بقيــة املبلــغ‪.‬‬\n‫وباســتجواب املدعــى عليــه الثانــي (‪ )......‬أفــاد أنــه يف مســاء يــوم اخلميــس‬\n‫املوافــق ‪1433/3/24‬ه ـ وأثنــاء مــروره بالقــرب مــن (بوفيــة ‪ )............‬على‬\n‫الواجهــة البحريــة لفــت انتباهــه وجــود عــدد مــن (اســطوانات) الغــاز‬\n‫داخــل صنــدوق حديــدي (شــبك) بالقــرب مــن بــاب البوفيــة فقرر ســرقتها‬\n‫ويف اليــوم التالــي وعنــد الســاعة (‪ )2:00‬الثانيــة ظهــر ًا اتصــل باملدعــى‬\n‫عليــه األول (‪ )......‬وأخبــره عــن (االســطوانات) وعــن نيتــه بســرقتها‬\n‫وعــرض عليــه القيــام بالســرقة معــه فوافــق مباشــرة وتواعــدا بالليــل‬\n‫لســرقة (االســطوانات) وعنــد الســاعة (‪ )2:00‬الثانيــة مــن فجــر يــوم‬\n\n\n                                                                                             ‫‪366‬‬\n\f      ‫الســبت املوافــق ‪1433/3/26‬ه ـ توجهــا ســوي ًا إلــى (البوفيــة) علــى ســيارة‬\n      ‫املدعــى عليــه األول (‪ ).....‬مــن نوع‪........‬وقامــا بالتوقــف بجــوار (البوفيــه)‬\n      ‫وقــام بأخــذ مفتــاح العجــل مــن الســيارة وكســر قفــل (الشــبك) الــذي‬\n      ‫بداخلــه (االســطوانات) وقامــا بســرقة عــدد (‪ )9‬تســع (أســطوانات)‬\n      ‫غــاز مــن داخــل الصنــدوق ثــم قامــا بخلــع بــاب (البوفيــة) بواســطة مفتــاح‬\n      ‫العجــل وقامــا بســرقة صنــدوق حديــدي صغيــر مــن داخلهــا ثــم توجهــا‬\n      ‫إلــى (الكورنيــش) مقابــل دوار الســفينة وقامــا بكســر الصنــدوق‬\n      ‫وعثــرا بداخلــه علــى مبلــغ مالــي قــدره (‪ )1300‬ألــف وثالثمائــة ريــال‬\n      ‫وصــور عمــال ومفاتيــح وتقاســما املبلــغ ورميــا املفاتيــح والصــور علــى‬\n      ‫(الكورنيــش) ثــم ركبــا الســيارة وســلكا طريــق (‪ )4‬وقامــا برمــي‬\n      ‫الصنــدوق بجــوار (كبــري) الفيحــاء ثــم توجهــا إلــى منــزل املدعــى‬\n      ‫عليــه األول (‪ .)....‬وباالنتقــال للموقــع احملــدد مت العثــور علــى الصنــدوق‬\n      ‫املســروق ملقــى علــى األرض علــى بعــد عشــرة أمتــار تقريبـ ًا مــن الســياج‬\n      ‫احلديــدي بالقــرب مــن كبــري ‪.......‬الفيحــاء املتقاطــع مــع طريــق (‪)4‬‬\n      ‫وهــو عبــارة عــن درع كاشــير مكــون مــن ثــاث قطــع منفصلــة عــن‬\n      ‫بعضهــا البعــض ومتجــاورة علــى األرض قطعتــن مــن احلديــد لونهــا‬\n      ‫رمــادي وقطعــة مــن البالســتيك لونهــا أســود ومت تصويرهــا باملوقــع‬\n      ‫ثــم أخذهــا والتحفــظ عليهــا وكانــت متعرضــة للغبــار ولــم يتــم العثــور‬\n      ‫علــى بصمــات عليهــا ومت إعــادة عــدد (‪ )9‬تســع اســطوانات للمطعــم‪.‬‬\n      ‫وانتهــى التحقيــق إلــى توجيــه االتهــام لهمــا بكســر قفــل البــاب الرئيســي‬\n      ‫ألحــد املطاعــم وســرقة صنــدوق احملاســبة منــه وبــه مبلــغ مالــي قــدره‬\n      ‫ألــف وثالثمائــة ريــال واالســتيالء عليــه وكســر قفــل صنــدوق حتريــز‬\n      ‫اســطوانات الغــاز لذلــك املطعــم وســرقة عــدد (‪ )9‬تســع اســطوانات غــاز‬\n\n\n‫‪367‬‬\n\f        ‫صغيــرة واالســتيالء عليهــا ‪ ،‬وذلــك لألدلــة و القرائــن التاليــة ‪-:‬‬\n‫‪ -1‬إقرارهمــا املنــوه عنــه املــدون علــى الصفحــات رقــم (‪)11،12 ، 5،6‬‬\n                                         ‫مــن دفتــر التحقيــق علــى اللفــة رقــم (‪.)2‬‬\n‫‪ -2‬محضــر تنفيــذ املهمــة وتســليمها جلهــة االختصــاص املنــوه عنــه بشــأن‬\n                             ‫بــاغ املقيــم ‪ ............‬املرفــق علــى اللفــة رقــم (‪.)3‬‬\n‫‪ -3‬محضــر تنفيــذ املهمــة وتســليمها جلهــة االختصــاص املنــوه عنــه‬\n‫املتضمــن بتقريــر التحريــات والبحــث اجلنائــي بتوفــر معلومــات عــن قيــام‬\n‫املتهمــن املذكوريــن بتحميــل اســطوانات غــاز مــن ســيارة نــوع (فــورد)‬\n                                                      ‫املرفــق علــى اللفــة رقــم (‪.)4‬‬\n‫‪ -4‬محضــر االنتقــال واملعاينــة املنــوه عنــه املــدون علــى الصفحــة رقــم (‪)2‬‬\n                                        ‫مــن دفتــر التحقيــق علــى اللفــة رقــم (‪. )1‬‬\n‫‪ -5‬محضــر االنتقــال والعثــور علــى املســروقات املنــوه عنــه املــدون علــى‬\n      ‫الصفحــة رقــم (‪ )7‬مــن دفتــر التحقيــق املرفــق علــى اللفــة رقــم (‪.)2‬‬\n‫‪ -6‬محضــر ســند اســتالم املنــوه عنــه املــدون علــى الصفحــة رقــم (‪)12‬‬\n                                       ‫مــن دفتــر التحقيــق علــى اللفــة رقــم (‪.)1‬‬\n‫وبالبحــث عمــا إذا كان لهمــا ســوابق جنائيــة لــم يعثــر لهمــا علــى ســوابق‬\n‫مســجلة‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا ‪ ،‬وهمــا بكامــل‬\n‫أهليتهمــا املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا وهــو ســرقة‬\n‫مــال محتــرم مــن حــرزه بعــد هتكــه يزيــد عــن النصــاب ال شــبهة لــه‬\n‫فيــه وطالــب بــه صاحبــه ولكــون اجلانــي مكلف ـ ًا غيــر مكــره أطلــب‬\n‫إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بحــد الســرقة الــواردة يف اآليــة‬\n‫الكرميــة رقــم (‪ )38‬مــن ســورة املائــدة ‪( ،‬علمـ ًا بــأن احلــق اخلــاص انتهــى‬\n                                                                             ‫بالتنــازل)‪.‬‬\n\n\n                                                                                             ‫‪368‬‬\n\f      ‫واهلل الهــادي إلــى ســواء الســبيل‪ ( .‬واهلل املوفــق ) ا‪.‬ه ـ هــذه دعــواي‬\n      ‫وبتــاوة دعــوى املدعــي العــام علــى املدعــى عليهمــا أجــاب املدعــى عليــه‬\n      ‫األول مبفــرده قائــا ‪ :‬مــا ذكــره املدعــي العــام يف دعــواه كلــه صحيــح‬\n      ‫جملــة وتفصيــا غيــر أن احملــل وهــو املطعــم لــم يتــم كســره مــن قبلنــا‬\n      ‫بــل قــام صاحبــي ‪ ......‬بوضــع رجلــه عليــه وانفتــح ‪ ،‬وقــد متــت ســرقة‬\n      ‫تصرفــت أنــا واملدعــى عليــه‬\n                                  ‫ّ‬      ‫صنــدوق الكاشــير واملبلــغ املذكــور وقــد‬\n      ‫الثانــي مببلــغ خمســن ريــال تقريبــا والباقــي موجــود حاليــا لــدى املدعــى‬\n      ‫عليــه الثانــي ‪ ، ......‬وأمــا الصنــدوق احلديــدي والــذي يحتــوي علــى (‪)13‬‬\n      ‫اســطوانة غــاز فقــد أخذنــا منهــا تســع اســطوانات فقــط وقــد قــام‬\n      ‫املدعــى عليــه الثانــي بكســر قفــل هــذا الصنــدوق مبفتــاح عجــل وقــد‬\n      ‫مت حتميــل هــذه االســطوانات بســيارة والــدي وهــذا الصنــدوق يقــع خــارج‬\n      ‫ا‬\n      ‫احملــل هكــذا أجــاب ‪ .‬كمــا أجــاب املدعــى عليــه الثانــي مبفــرده قائـ ً‬\n      ‫‪ :‬مــا ذكــره املدعــي العــام يف دعــواه كلــه صحيــح جملــة وتفصيــا غيــر‬\n      ‫أنــي لــم أقــم بكســر قفــل احملــلّ الداخلــي بــل قمــت أنــا بكســر قفــل‬\n      ‫الصنــدوق احلديــدي الــذي يحتــوي علــى (‪ )13‬اســطوانة غاز وأخذت منها‬\n      ‫وصاحبــي ‪ )9( .....‬تســع اســطوانات ألن املــكان ال يتســع حلمــل البقيــة‬\n      ‫ـارة وقمــت بكســره عــن‬   ‫وهــذا الصنــدوق احلديــدي خــارج احملــل يــراه املـ ّ‬\n      ‫طريــق مفتــاح العجــل ‪ ،‬وأمــام بــاب املطعــم فإنــه كان مفتوحــا حيــث‬\n      ‫قمــت بــإدارة املقبــض فانفتــح معــي البــاب كمــا قمنــا بأخــذ صنــدوق‬\n      ‫الكاشــير واملبلــغ املذكــور وقــد كانــت االســطوانات محملــة بســيارة‬\n      ‫والــد املدعــى عليــه األول ‪ .......‬هكــذا أجــاب ‪.‬ثــم جــرى ســؤال املدعــى‬\n      ‫عليــه األول والثانــي عــن ســوابقهما ‪ :‬فأجــاب كل واحــد منهمــا مبفــرده‬\n      ‫بقولــه ‪ :‬ال توجــد لــدي أي ســابقة هكــذا أجابــا ‪ .‬وعليــه والنتهــاء الوقــت‬\n\n\n‫‪369‬‬\n\f‫احملــدد لهــذه اجللســة وملزيــد التأمــل رفعــت اجللســة ‪ .‬وكان ختــام هــذه‬\n‫اجللســة الســاعة احلاديــة عشــرة واهلل املوفــق وصلــى اهلل علــى نبينا محمد‬\n                   ‫وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف ‪1433/07/21‬هــ‪.‬‬\n‫ويف يــوم الثالثــاء ‪1433/09/05‬ه ـ افتتحــت اجللســة الســاعة الواحــدة‬\n‫والنصــف وفيهــا حضــر املدعــي العــام واملدعــى عليــه األول والثانــي ثــم‬\n‫جــرى االطــاع علــى أوراق املعاملــة فوجدنــا فيهــا اإلقراريــن املنســوبني‬\n‫للمدعــى عليهمــا واملتضمنــان إقــرار املدعــى عليــه األول ‪ ......‬بــأن املدعــى‬\n‫عليــه الثانــي قــام بخلــع بــاب البوفيــة مبفتــاح العجــل وبقيــة إقــراره كمــا‬\n‫ذكــر املدعــي العــام وأقــر بــه املدعــى عليــه األول‪ .‬وإقــرار املدعــى عليــه‬\n‫الثانــي ‪ .......‬بأنــه قــام بالتنســيق لعمليــة الســرقة وأنــه هــو مــن حـ َّـرض‬\n‫املدعــى عليــه األول علــى ذلــك‪ ،‬وهــو مــن قــام بأخــذ مفتــاح العجــل‬\n‫وكســر قفــل بــاب الشــبك‪ ،‬وأ َّنــه قــام بصــرف مــا معــه مــن مبلغ‪...‬إلــخ‬\n‫وبقيــة اعترافــه كمــا ذكــر أثنــاء اجللســة وكمــا جــاء يف الئحــة املدعــي‬\n‫أن احملــل‬\n         ‫العــام‪ .‬كمــا جــرى االطــاع علــى بــاغ املدعــو ‪ .....‬واملتضمــن ّ‬\n‫وأن طريقــة الدخــول للمطعــم‬      ‫السـ ّـراق َّ‬\n                                             ‫تعـ َّـرض للتكســير مــن قبــل ُ‬\n‫كانــت عــن طريــق كســر قفــل البــاب األمامــي‪ ،‬كمــا جــرى االطــاع‬\n‫علــى احملاضــر املرفقــة وهــي محضــر تنفيــذ مهمــة‪ ،‬ومحضــر االنتقــال‬\n‫واملعاينــة‪ ،‬ومحضــر االنتقــال والعثــور علــى املســروقات ومحضــر ســند‬\n‫االســتالم وبســؤال املدعــى عليهمــا عــن التقاريــر واحملاضــر اآلنفــة‬\n‫الذكــر أجــاب كل واحــد منهمــا حيــث أجــاب ‪ ........‬بقولــه‪ :‬الصحيــح‬\n‫مــا ذكرتــه يف اجللســة املاضيــة مــن كــون البــاب لــم يكــن مقفــا بــل‬\n‫رفعــه املدعــى عليــه الثانــي‪ .....‬وانفتــح هكــذا أجــاب وأجــاب ‪ ......‬بقولــه‪:‬‬\n‫الصحيــح مــا ذكرتــه يف اجللســة املاضيــة ولــم أقــم بكســر قفــل البــاب‬\n\n\n                                                                                       ‫‪370‬‬\n\f      ‫وإمنــا قمــت بكســر قفــل الصنــدوق احلديــدي مبفتــاح عجــل وأنــا مــن‬\n      ‫حـ ّـرض املدعــى عليــه األول ‪ ......‬علــى هــذه الســرقة فجــرى ســؤالهما عــن‬\n      ‫أي ســابقة‪ .‬وملزيــد التأمــل يف أوراق‬                     ‫ســوابقهما فأجابــا‪ :‬ال توجــد علينــا ّ‬\n      ‫املعاملــة ولتــداول احلكــم قررنــا رفــع اجللســة وعليــه جــرى التوقيع وكان‬\n      ‫ختــام هــذه اجللســة الســاعة الثانيــة والنصــف وبــاهلل التوفيــق‪ ،‬وصلى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/09/05‬ه ـ‬\n      ‫ويف يــوم األحــد ‪1433/09/12‬ه ـ افتتحت اجللســة الســاعة الثانية عشــرة‬\n      ‫والربــع وفيهــا حضــر املدعــي العــام واملدعــى عليهمــا فبنــاء علــى مــا تقـ َّـدم‬\n      ‫الدعــوى واإلجابــة وملصادقــة املدعــى عليهمــا علــى مــا جــاء يف دعــوى‬                                 ‫مــن ّ‬\n      ‫املدعــي العــام جملــة وتفصيــا ســوى قضيــة كســر قفــل بــاب املطعــم‪،‬‬                                        ‫ّ‬\n      ‫وألن مثــل هــذا العمــل محـ َّـر ٌم شــرعاً‪ ،‬ومجـ ّـر ٌم نظام ـاً‪ ،‬حيــث قــال‬                                ‫ّ‬\n      ‫كـ ْـم‪،‬‬     ‫ـإن د َِم َاء ُ‬\n                               ‫ال َّنبــي ص َّلــى اهلل عليــه وســلم يف احلديــث الصحيــح ‪« :‬فـ َّ‬\n      ‫ك ْم َه َذا‪ِ ،‬ف‬         ‫ك ُح ْر َمـ ِة َي ْومِ ُ‬\n                                                     ‫ينكـ ْـم َحـ َـر ٌام‪َ ،‬‬\n                                                                          ‫كـ ْـم َب ُ‬ ‫عراض ُ‬\n                                                                                           ‫َ‬       ‫َكـ ْـم‪َ ،‬و َأ‬\n                                                                                                               ‫َو َأ َموال ُ‬\n      ‫كـ ْـم َهـ َـذا» متفــق عليــه مــن حديــث أبــي بكــرة‬                       ‫ك ْم َهـ َـذا‪ِ ،‬ف َبلَدِ ُ‬   ‫ـهر ُ‬\n                                                                                                                    ‫َشـ ِ‬\n      ‫«كلُّ ا ُملسـل ِِم َع َلــى ا ُملسـل ِِم َحـ َـر ٌام‪َ ،‬د ُمـ ُه‪َ ،‬و َما ُلـ ُه‪َ ،‬وعِ ْر ُضـ ُه» رواه‬ ‫وقــال ‪ُ :‬‬\n      ‫املدعــى عليهمــا أنكــرا كــون‬                  ‫أن َّ‬  ‫مســلم مــن حديــث أبــي هريــرة ومبــا َّ‬\n      ‫بــاب املطعــم ُمحــرزا ومقفــا‪ ،‬أو أنَّهمــا قامــا بكســره‪ ،‬وال توجــد ِّبينـ ٌة‬\n      ‫علــى ذلــك‪ ،‬ولكــون الصنــدوق الــذي وضــع بــه أســطوانات الغــاز غيــر‬\n      ‫ممــا جعــل شــروط حـ ِّـد الســرقة ال‬                ‫ـارة؛ َّ‬    ‫مت وضعــه أمــام املـ ّ‬  ‫محــرز حيــث َّ‬\n      ‫حقهمــا‪ ،‬إضافــة لوجــود الشــبهة يف إجاباتهمــا املؤديــة لــدرء‬                              ‫تكتمــل يف ِّ‬\n      ‫املدعــى عليــه الثانــي أقـ َّـر بكونــه هــو مــن بــادر باالتصال‬                     ‫احلـ ِّـد‪ ،‬ولكــون َّ‬\n      ‫والتنســيق لهــذه اجلرميــة‪ ،‬كمــا أقـ َّـر بأ َّنــه هــو مــن قــام بكســر قفــل‬\n      ‫املدعــى‬  ‫الصنــدوق احلديــدي عبــر مفتــاح العجــل فقــد ثبــت لدينــا إدانــة َّ‬\n\n‫‪371‬‬\n\f‫عليهمــا بكســر قفــل الصنــدوق احلديــدي وســرقة تســع اســطوانات غــاز‬\n‫صغيــرة ودخــول املطعــم املذكــور وســرقة صنــدوق احملاســبة منــه ومبلــغ‬\n‫مالــي قــدره ألــف وثالثمائــة ريــال واالســتيالء عليــه وحكمنــا باإلجمــاع‬\n‫بــدرء حـ ّـد الســرقة عــن املدعــى عليهمــا كمــا حكمنــا عليهمــا تعزيــرا‬\n‫املدعــى عليــه الثانــي ‪ ........‬ســنتني ونصــف‬      ‫مبــا يلــي ‪ -:‬أوال‪ُ /‬يســجن َّ‬\n‫املدعــى‬‫تبــدأ مــن تأريــخ إيقافــه علــى ذمــة هــذه القضيــة ‪ .‬ثانيــا‪ُ /‬يســجن َّ‬\n‫ذمــة هــذه القضيــة‬    ‫عليــه األول ‪ .......‬ســنتني تبــدأ مــن تأريــخ إيقافــه علــى ّ‬\n‫مفرقــة علــى عشــرين‬     ‫املدعــى عليــه الثانــي ‪ .......‬ألــف جلــدة َّ‬\n                                                                      ‫ثالثــا‪ُ /‬يجلــد َّ‬\n ‫دفعــة كلُّ دفعــة خمســون جلــدة بــن كل دفعــة واألخــرى مـ َّـدة ال تقــلَّ‬\n‫األول ‪ ......‬ســبع مئــة جلــدة‬ ‫عــن أســبوعني‪ .‬رابعــا‪ُ /‬يجلــد املدعــى عليــه ّ‬\n‫مفرقــة علــى أربعــة عشــر دفعــة كل دفعــة خمســون جلــدة بــن كل‬\n‫الوصيــة بــأن تكــون آخــر‬ ‫ّ‬       ‫دفعــة واألخــرى مــدة ال تقــل عــن أســبوعني مــع‬\n‫املدعــى عليهمــا أمــام أقــرب جامـ ٍـع للمطعــم‬  ‫ـكل مــن َّ‬ ‫دفعتــن مــن اجللــد لـ ٍّ‬\n‫املذكــور بعــد خــروج النــاس مــن صــاة اجلمعــة‪ ،‬وبعــرض ذلــك علــى‬\n‫الطرفــن قـ َّـرر املدعــي العــام االعتــراض ورغــب برفــع احلكــم بــدون‬\n‫الئحــة اعتراضيــة وقـ َّـرر املدعــى عليهمــا القناعــة ‪ .‬وكان ختــام هــذه‬\n‫اجللســة الســاعة الواحــدة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/09/12‬ه ـ ‪.‬‬\n‫احلمد هلل وحده وبعد ويف يوم االثنني ‪ 1434/02/18‬هـ افتتحت اجللسة‬\n‫الســاعة العاشــرة وقــد كانــت املعاملــة وردتنــا مــن محكمــة االســتئناف‬\n‫بالقــرار رقــم ‪ 33456837‬وتاريــخ ‪1433/11/16‬ه ـ واملتضمــن املالحظة‬\n‫ونــص احلاجــة منــه مــا يلــي ‪((:‬وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة لوحــظ أن أصحــاب الفضيلــة درءوا حــد الســرقة عــن املدعــى‬\n\n\n                                                                                            ‫‪372‬‬\n\f      ‫عليهمــا ألنهــا متــت مــن غيــر حــرز وهــذا محــل نظــر حيــث جــرت العــادة‬\n      ‫علــى حتريــز اســطوانات الغــاز مبثــل ذلــك ملالحظــة مــا ذكــر وإكمــال‬\n      ‫الــازم ومــن ثــم إعــادة املعاملــة إلكمــال الزمهــا واهلل املوفــق)) ا‪ .‬ه ـ‬\n      ‫وجوابــا علــى مــا ذكــره أصحــاب الفضيلــة ســددهم اهلل وأعانهــم نقــول‬\n      ‫إنــه جــرى الشــخوص إلــى موقــع اســطوانات الغــاز املذكــورة مــن قبــل‬\n      ‫رئيــس اجللســة فوجــدت خــارج املطعــم داخــل شــبك علــى الرصيــف ومثــل‬\n      ‫ذلــك ال يعــد حــرز االســطوانات الغــاز ألنــه جــرت عادتهــا أن تكــون‬\n      ‫داخــل امللــك ال خارجــة عنــه وحرزهــا مبثــل ذلــك وإن كان أســلم مــن‬\n      ‫األخطــار إال أنــه قريــب مــن أيــدي اللصــوص واألشــرار وأقــل مــا يف‬\n      ‫ذلــك أنــه شــبهة واحلــدود تــدرأ بالشــبهات وألجــل ذلــك فقــد جــرى درؤ‬\n      ‫حــد الســرقة عنهمــا وقررنــا رفــع احلكــم حملكمــة االســتئناف وأقفلــت‬\n      ‫اجللســة الســاعة احلاديــة عشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/18‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n      ‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة اجلبيــل‬\n      ‫الشــيخ‪ ..........‬برقــم ‪ 332195890‬وتاريــخ ‪1434/2/23‬ه ـ واملقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪/34/492770‬خ‪ 1‬وتاريــخ ‪1434/2/26‬ه ـ املرفــق‬\n      ‫بهــا القــرار الشــرعي ذو الرقــم ‪ 33410091‬والتاريــخ ‪1433/9/12‬ه ـ‬\n      ‫الصــادر مــن فضيلتــه وأصحــاب الفضيلــة القضــاة باحملكمــة‬\n      ‫املشــاركني لــه الشــيخ‪ ...............‬والشــيخ‪ .........‬اخلــاص بدعــوى املدعــي‬\n      ‫كل مــن‪ ......-2 .......-1:‬يف قضيــة ســرقة وقــد تضمــن‬           ‫ٍ‬    ‫العــام ضــد‬\n      ‫القــرار حكــم أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل فيــه ‪ .‬وحيــث‬\n\n\n‫‪373‬‬\n\f‫ســبق دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى‬\n‫مــا أجــاب بــه أصحــاب الفضيلــة علــى قرارنــا رقــم ‪/33456837‬خ‪/1‬ب‬\n‫وتاريــخ ‪1433/11/16‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء‬\n‫األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                ‫حــرر يف ‪ 1434/4/2‬هـ ـ ـ ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪374‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":363,"source_page_end":374,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"919ffef4427ea1bc8d48ed6e081bbbae5529d62ad5cfde0f8510340893c6883c","normalized_text_hash":"362ceb2e1eb06e972472292e500e61c66968544a9412c1b43af1bb350b246bc4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p363-33410091"},{"id":"823116e4-640e-58b9-b97c-1190fde06a73","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة منزل -سرقة بعض محتويات املنزل ومبلغ مالي - إقرار املدعى عليه حتقيق ا -رجوع عن إقرار -ادعاء إكراه بانتزاع إقراره -درء حد السرقة -التعزير بالسجن واجللد .","document_number":"33463561","case_number":"33454005","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة االحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/23","year":"1434","subject":"سرقة -سرقة منزل -سرقة بعض محتويات املنزل ومبلغ مالي - إقرار املدعى عليه حتقيق ا -رجوع عن إقرار -ادعاء إكراه بانتزاع إقراره -درء حد السرقة -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 33463561:‬تاريخه ‪1433/11/23:‬هـ‬\n                          ‫رقم الدعوى ‪33454005:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n            ‫االستئناف‪ 3454597:‬تاريخه‪1434/3/3 :‬ه‬\n\n\n\n      ‫ســرقة‪ -‬ســرقة منــزل ‪ -‬ســرقة بعــض محتويــات املنــزل ومبلــغ مالــي ‪-‬‬\n      ‫إقــرار املدعــى عليــه حتقيقـ ًا ‪ -‬رجــوع عــن إقــرار‪ -‬ادعــاء إكــراه بانتــزاع‬\n                        ‫إقــراره‪ -‬درء حــد الســرقة‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n                      ‫قوله صلى اهلل عليه وسلم ( ادرؤوا احلدود بالشبهات )‪.‬‬\n\n\n\n\n      ‫دعــوى املدعــي العــام ضــد املدعــى عليــه بدخــول منــزل أحــد األشــخاص‬\n      ‫عــن طريــق كســر بــاب املنــزل وســرقة مبلــغ مالــي‪ ،‬وشاشــة بالزمــا‬\n      ‫وجهــاز ريســيفر وجهــاز دي يف دي وســماعات‪ ،‬طلــب املدعــي العــام‬\n      ‫إقامــة حــد الســرقة‪ ،‬مت القبــض علــى املدعــى عليــه بعــد بــاغ مــن أحــد‬\n      ‫املواطنــن يفيــد بتعــرض منزلــه للســرقة ويتهــم املدعــى عليــه وبعــد‬\n      ‫اســتجوابه أقــر مبــا نســب إليــه‪ ،‬أنكــر املدعــى عليــه للدعــوى‪ ،‬وجــد‬\n      ‫إقــرار للمدعــى عليــه حتقيق ـاً‪ ،‬رجــع املدعــى عليــه عــن إقــراره‪ ،‬مت درء‬\n      ‫حــد الســرقة عــن املدعــى عليــه‪ ،‬وتعزيــر املدعــى عليــه بالســجن واجللــد‪،‬‬\n                                 ‫مت تصديــق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪375‬‬\n\f‫احلمــد هلل وحــده وبعــد لدينــا نحــن ‪ ........‬و ‪ ........‬و ‪ ..........‬القضــاة يف‬\n‫العامــة باإلحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n                                                                    ‫ّ‬     ‫احملكمــة‬\n‫رئيــس احملكمــة العامــة مبحافظــة االحســاء برقــم ‪ 33454005‬وتاريــخ‬\n‫‪1433/07/08‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331285606‬وتاريــخ‬\n‫‪1433/07/08‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1433/10/25‬ه ـ حضــر‬\n‫املدعــي العــام ‪ .....‬وادعــى علــى احلاضــر معــه ‪ .....‬قائــا بصفتــي مدعي ـ ًا‬\n‫عامــا بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى ‪، ...... :‬‬     ‫ً‬\n‫‪ 24‬عام ـ ًا ‪ ،‬محصــن ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ ، )....‬إنــه بتاريــخ ‪ 1433 / 3 / 19‬ه ـ تقــدم املواطــن ‪ .....‬ببــاغ‬\n‫يتضمــن قيــام شــخص بالدخــول إلــى منزلــه الواقــع بحــي ‪ ......‬وســرقة‬\n‫مبلــغ (‪ )7500‬ســبعة آالف وخمســمائة ريــال وشاشــة ( بالزمــا ) وجهــاز‬\n‫(ريســيفر ) وجهــاز ( دي يف دي ) وســماعات ‪ .‬وباالنتقــال واملعاينــة تبــن‬\n‫أن منــزل املبلــغ يقــع بحــي ‪ ........‬وهــو عبــارة عــن منــزل قــدمي وقــد شــوهد‬\n‫بــأن اجلانــي متكــن مــن الدخــول للمنــزل عــن طريــق البــاب الرئيســي ‪،‬‬\n‫ومــن ثــم الدخــول إلــى داخــل املنــزل وســرقة األجهــزة الكهربائيــة وفتــح‬\n‫إحــدى الغــرف وســرقة مبلــغ (‪ )7500‬ســبعة آالف وخمســمائة ريــال‬\n‫كانــت موضوعــة بداخــل درج إحــدى الطــاوالت ولــم يشــاهد أي آثــار‬\n‫للجنــاة وبضبــط أقــوال املبلــغ أفــاد أنــه بتاريــخ ‪1433/3/19‬ه ـ توجــه إلى‬\n‫مقــر عملــه وبعــد عودتــه مــن العمــل اكتشــف بــأن هنــاك شــخص قــام‬\n‫بالدخــول إلــى منزلــه وســرق منــه مبلــغ (‪ )7500‬ســبعة آالف وخمســمائة‬\n‫ريــال وشاشــة ( بالزمــا ) وجهــاز ( ريســيفر ) وجهــاز ( دي يف دي )‬\n\n                                                                                        ‫‪376‬‬\n\f      ‫وســماعات ‪ .‬وبتاريــخ ‪1433/3/26‬ه ـ حضــر املبلــغ ملركــز شــرطة ‪....‬‬\n      ‫وقــرر اتهامــه ضــد املدعــى عليه يف ســرقة منزلــه ‪ .‬وبتاريخ ‪1433/5/5‬هـ‬\n      ‫مت إحضــار املدعــى عليــه مــن قبــل مركــز شــرطة ‪ . ....‬وباســتجواب‬\n      ‫املدعــى عليــه أقــر أنــه بتاريــخ ‪ 1433/3/19‬ه ـ اجتــه إلــى حــي ‪......‬‬\n      ‫وحتديـ ًـدا ملنــزل املدعــي بعــد أن تأكــد خلــوه مــن صاحبــه وشــاهد‬\n      ‫صاحــب املنــزل متوج ًهــا إلــى عملــه ولوجــود معرفــة بينهمــا ســابقة فقــد‬\n      ‫قــام بكســر بــاب املنــزل والدخــول وســرقة شاشــة ( بالزمــا ) وجهــاز‬\n      ‫(ريســيفر) وجهــاز ( دي يف دي ) وســماعات ومبلــغ مالــي قــدره (‪)7500‬‬\n      ‫ســبعة آالف وخمســمائة ريــال ‪ ،‬وقــام بتحميــل املســروقات يف ســيارته‬\n      ‫اخلاصــة والتوجــه بهــا إلــى محافظــة ‪ .....‬وباعهــا هنــاك علــى إحــدى‬\n      ‫احملــات التجاريــة مببلــغ (‪ )4500‬أربعــة آالف وخمســمائة ريال وتصرف‬\n      ‫باملبلــغ ‪ .‬وقــد أســفر التحقيــق معــه عــن توجيــه االتهــام لــه بدخــول منــزل‬\n      ‫أحــد األشــخاص عــن طريــق كســر البــاب وســرقة مبلــغ (‪ )7500‬ســبعة‬\n      ‫آالف وخمســمائة ريــال وشاشــة بالزمــا وجهــاز ريســيفر وجهــاز دي يف‬\n      ‫دي وســماعات ؛ وذلــك لألدلــة والقرائــن التاليــة ‪ 1 :‬إقــراره املنــوه عنــه‬\n      ‫املــدون علــى الصفحــات رقــم (‪ )3‬مــن ملــف التحقيــق املرفــق لفــه رقــم‬\n      ‫(‪ 2. )1‬محضــر االنتقــال واملعاينــة املنــوه عنــه واملــدون علــى الصفحتــن‬\n      ‫رقمــي (‪ )3.2‬مــن دفتــر التحقيــق املرفــق علــى اللفــة رقــم (‪ 3 . )1‬توافــق‬\n      ‫أقــوال املدعــى عليــه مــع مــا جــاء يف أقــوال املبلــغ قرينــة علــى صحــة مــا‬\n      ‫أســند إليــه ‪ .‬وبالبحــث عمــا إذا كان عليــه ســوابق عثــر له على ســابقتني‬\n      ‫مســجلتني عليــه األولــى محاولــة ســرقة ‪ ،‬والثانيــة النصــب واالحتيــال ‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا لقيامــه بســرقة مــال محتــرم‬\n\n\n‫‪377‬‬\n\f‫يزيــد عــن النصــاب مــن حــرزه بعــد هتكــه ال شــبهة لــه فيــه وطالــب بــه‬\n‫مكلفــا غيــر مكــره ؛ لــذا أطلــب إثبــات مــا أســند‬‫ً‬       ‫صاحبــه ولكونــه‬\n‫إليــه ‪ ،‬واحلكــم عليــه بحــد الســرقة الــوارد يف اآليــة الكرميــة رقــم (‪)38‬‬\n‫علمــا أن احلــق اخلــاص انتهــى بالتنــازل ) وبســؤال‬   ‫مــن ســورة املائــدة ‪ً ( .‬‬\n‫املدعــى عليــه عــن دعــوى املدعــي العــام أجــاب قائــا مــا ذكــره املدعــي‬\n‫العــام يف دعــواه غيــر صحيــح والصحيــح أنــي اســتأجرت للمدعــو ‪......‬‬\n‫ســيارة نــوع ‪ .....‬باســمي مــن شــركة الفــاح لتاجيــر الســيارات وســلمتها‬\n‫لــه لكونــه غيــر موظــف وتأخــر عــن ســداد إيجــار الســيارة فاتصلــت بــي‬\n‫الشــركة عــدة مــرات وطالبتنــي بســداد مبلــغ وقــدره أكثــر مــن عشــرة‬\n‫آالف ريــال وأخبرتــه بذلــك وطلبــت منــه ســداد الشــركة واتفقنــا علــى‬\n‫أن آخــذ شاشــة البالزمــا مــن شــقته وأبيعهــا وأســدد مــن ثمنهــا للشــركة‬\n‫ويف يــوم ‪1433/3/19‬ه ـ حضــرت لشــقته وفتحتها باملفتاح وكان يوجد‬\n‫لــدي نســخة مــن املفتــاح كمــا يوجــد مــع آخريــن غيــري لكوننــا جنتمــع‬\n‫فيهــا باســتمرار ونشــاهد املباريــات وهــو يســكن لوحــده وبــدون عائلتــه‬\n‫وأخــذت شاشــة البالزمــا وبعتهــا مببلــغ ألــف ومائتــي ريــال وســددتها‬\n‫للشــركة وأمــا مــا ذكــر املدعــي العــام مــن أخــذي املبلــغ املالــي وبقيــة‬\n‫األجهــزة فغيــر صحيــح هكــذا أجــاب وبســؤال املدعــي العــام عــن البينــة‬\n‫علــى دعــواه قــال بينتــي مــا هــو موجــود يف أوراق املعاملــة ثــم جــرى ســؤال‬\n‫املدعــى عليــه عــن البينــة علــى مــا ذكــر مــن اتفاقــه مــع ‪ .....‬علــى أخــذ‬\n‫شاشــة البالزمــا مــن شــقته وبيعهــا وأخــذ ثمنهــا فقال ليس لــدي بينة على‬\n‫ذلــك وبالرجــوع إلــى أوراق املعاملــة جــرى االطــاع علــى إقــرار املدعــى‬\n‫عليــه علــى صحيفــة رقــم (‪ )3‬مــن ملــف التحقيــق لفــه رقــم (‪ )1‬ونصــه‬\n‫(أقــر انــا املدعــو ‪23 .....‬ســنه ســعودي اجلنســية ســجل مدنــي رقــم (‪)......‬‬\n\n\n                                                                                       ‫‪378‬‬\n\f      ‫بطوعــي واختيــاري ومــن دون اجبــار مــن أحــد وانــا بكامــل قــواي العقلية‬\n      ‫املعتبــرة شــرع ًا بأنــه منــذ شــهرين مــن تاريــخ هــذا االعتــراف ذهبــت إلــى‬\n      ‫منــزل زميلــي ‪ .....‬الواقــع بحــي‪ .........‬بعــد أن قــام بالذهــاب إلــى عملــه‬\n      ‫فقمــت بكســر بــاب املنــزل املكــون مــن خشــب والدخــول وســرقت‬\n      ‫منــه شاشــة بالزمــا وجهــاز دي يف دي وســماعات وقيمبــوي وريســيفر‬\n      ‫وجهــاز ال بتــوب ومبلــغ ســبعة آالف وخمســمائة ريــال شــاهدت بإحــدى‬\n      ‫دروج التســريحة وبعدهــا قمــت بأخــذ جميــع املســروقات والذهــاب بهــا‬\n      ‫إلــى محافظــة اجلبيــل وبيعهــا هنــاك مببلــغ اربعــة آالف وخمســمائة ريــال‬\n      ‫وتصــرف باملبلــغ وهــذا اعتــراف منــي بذلــك بــدون اجبــار مــن أحــد وعلــى‬\n      ‫هــذا اوقــع) أ‪ .‬ه ـ وبعرضــه علــى املدعــى عليــه أجــاب قائــا مــا ذكــر يف‬\n      ‫اعتــرايف كلــه غيــر صحيــح وقــد انتــزع منــي بالقــوة واالكــراه هكــذا‬\n      ‫قــرر فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلنــكار املدعــى عليــه‬\n      ‫دعــوى املدعــي العــام وألنــه ال بينــة للمدعــي العــام علــى دعــواه ســوى‬\n      ‫إقــرار املدعــى عليــه لــدى جهــات التحقيــق وقــد رجــع عنــه وحيــث جــاءت‬\n      ‫الشــريعة بحفــظ الضــرورات اخلمــس ومنهــا املــال ولقولــه صلــى اهلل‬\n      ‫عليــه وســلم ( ادرؤوا احلــدود بالشــبهات ) وألن رجوعــه عــن اعترافــه‬\n      ‫شــبهه توجــب درء احلــد عنــه فقــد قررنــا درء حــد الســرقة عــن املدعــى‬\n      ‫عليــه وســجنه ســنتني اعتبــار مــن تاريــخ ايقافــه وجلــد ثالثمائــة جلــدة‬\n      ‫مفرقــة علــى دفعــات كل دفعــة خمســن جلــدة بــن كل دفعــة وأخــرى‬\n      ‫شــهر وبــه حكمنــا وبعــرض احلكــم قــرر املدعــى عليــه قناعتــه باحلكــم‬\n      ‫وقــرر املدعــي العــام عــدم القناعــة فأفهمنــاه املراجعــة يف يــوم األحــد‬\n      ‫املوافــق ‪1433/11/21‬ه ـ الســتالم نســخة مــن احلكــم لتقــدمي الئحتــه‬\n      ‫االعتراضيــة خــال ثالثــن يومــا وإال يســقط حقــه يف االعتــراض وترفــع‬\n\n\n‫‪379‬‬\n\f‫املعاملــة بــدون الئحــة اعتراضيــة ففهــم ذلــك وبــاهلل التوفيــق وصلــى‬\n‫اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1433/11/17‬ه ـ ‪ .‬احلمــد هلل‬\n‫وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة اخلماسـي ــة‬\n‫األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة األحســاء برقــم‬\n‫‪ 34/108329‬وتاريــخ ‪1434/1/20‬ه ـ واملقيــدة لــدى احملكمــة برقــم‬\n‫‪/34/224896‬خ‪ 1‬وتاريــخ ‪1434/1/26‬ه ـ املرفــق بهــا القــرار الشــرعي‬\n‫ذو الرقــم ‪ 33463561‬والتاريــخ ‪1433/11/23‬ه ـ الصــادر مــن أصحــاب‬\n‫الفضيلــة القضــاة باحملكمــة الشــيخ ‪ ......../‬والشــيخ ‪ ...... /‬والشــيخ ‪/‬‬\n‫‪.........‬اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد ‪ ......./‬يف قضيــة ســرقة وقــد‬\n‫تضمــن القــرار حكــم أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل فيــه‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                        ‫حــرر يف ‪ 1434/3/3‬ه ـ ـ ــ‪.‬‬\n\n\n\n\n                                                                                         ‫‪380‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":375,"source_page_end":380,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"26d21a2bd72604a3f329ddb41f2dcd7e86923e8e8a05978691b38187e98a146e","normalized_text_hash":"66d9aafdd4dbedf0677843753399dc25143d0ced915c22eb8514d0911b7264cb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p375-33463561"},{"id":"877080bb-eaae-5fcd-80bb-55ca5d65ca1e","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -انتهاك حرمة عدة منازل -سرقة بعض محتويات املنازل - سرقة من بيت اجلار -إقرار حتقيق ا -مطالبة بحد السرقة -تغليظ العقوبة -تعزير بالسجن واجللد -1قوله صلى اهلل عليه وسلم (يسرق الرجل من عشر أبيات أيسر عليه من أن يسرق من جاره).","document_number":"33415014","case_number":"33463366","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باجلبيل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/18","year":"1434","subject":"سرقة -انتهاك حرمة عدة منازل -سرقة بعض محتويات املنازل - سرقة من بيت اجلار -إقرار حتقيق ا -مطالبة بحد السرقة -تغليظ العقوبة -تعزير بالسجن واجللد -1قوله صلى اهلل عليه وسلم (يسرق الرجل من عشر أبيات أيسر عليه من أن يسرق من جاره).","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫رقم الصك‪ 33415014:‬تاريخه ‪1433/9/18:‬هـ‬\n                          ‫رقم الدعوى ‪33463366:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                   ‫‪ 3463763‬تاريخه ‪1434/03/16:‬ه‬\n\n\n\n      ‫ســرقة ‪ -‬انتهــاك حرمــة عــدة منــازل ‪ -‬ســرقة بعــض محتويــات املنــازل ‪-‬‬\n      ‫ســرقة مــن بيــت اجلــار‪ -‬إقــرار حتقيقـ ًا‪ -‬مطالبــة بحــد الســرقة‪ -‬تغليــظ‬\n                                              ‫العقوبــة‪ -‬تعزيــر بالســجن واجللــد‬\n\n\n\n\n      ‫‪ -1‬قولــه صلــى اهلل عليــه وســلم (يســرق الرجــل مــن عشــر أبيــات أيســر‬\n                                                   ‫عليــه مــن أن يســرق مــن جــاره)‪.‬‬\n      ‫‪ -2‬قولــه صلــى اهلل عليــه وســلم (ال يدخــل اجلنــة مــن ال يأمــن جــاره‬\n                                                                           ‫بوائقــه)‪.‬‬\n      ‫‪ -3‬قــال يف كشــاف القنــاع ( فــإن وجــد حــرز ًا مهتــوك ًا فأخــذ منــه فــا‬\n      ‫قطــع أو وجــد بابــا مفتوحـ ًا فأخــذ منــه فــا قطــع لعــدم شــرطه) ‪134/6‬‬\n      ‫‪ -4‬قــال شــيخ اإلســام ابــن تيميــة (وغلــظ املعصيــة وعقابهــا بقــدر‬\n                                   ‫فضيلــة الزمــان واملــكان) االختيــارات ‪.294‬‬\n\n\n\n      ‫دعــوى املدعــي العــام ضــد املدعــى عليــه بانتهــاك حرمــة عــدة منــازل‬\n      ‫وســرقة أجهــزة حاســب آلــي محمولــة وجــواالت وأســطوانات غــاز‬\n      ‫وإســوارين ذهــب وأجهــزة كهربائيــة (كاميــرات‪ -‬بــاي ستيشــن ‪-‬‬\n      ‫وبعــض املقتنيــات اخلاصــة مــن حــرز بعــد هتكــه) منهــا وطلــب املدعــى‬\n\n‫‪381‬‬\n\f‫العــام إقامــة حــد الســرقة‪ ،‬وبعــد التحــري مت القبــض علــى املدعــى عليــه‬\n‫واعترافــه بســرقة عــدة منــازل ويشــاركه «حدثــان» فــرزت لهمــا أوراق‬\n‫مســتقلة‪،‬أقر املدعــى عليــه بســرقة بيــت واحــد دخلــه مــن البــاب اخللفــي‬\n‫الــذي يســحب ووجــد داخــل املنــزل جهــاز الب تــوب يف الصالــة وباعــه‬\n‫وأنكــر غيــر ذلــك‪ ،‬وجــود إقــرار للمدعــى عليــه حتقيقـاً‪ ،‬رجــع املدعــى‬\n‫عليــه عــن إقــراره حتقيقـاً‪ ،‬صــرف النظــر عــن دعــوى املدعــي العــام ألن‬\n‫الســرقة مــن حــرز مهتــوك حيــث كان البــاب مفتوحاً‪،‬تعزيــر املدعــى‬\n‫عليــه بالســجن واجللــد‪ ،‬مت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ -:‬فلدينا‬\n‫نحــن ‪ ......‬و ‪ ....‬و ‪ .....‬القضــاة باحملكمــة العامــة باجلبيــل وبنــاء علــى‬\n‫املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة برقــم ‪33463366‬‬\n‫تأريخ‪1433/07/13‬ه ـ املقيــدة باحملكمــة برقــم‪ 331316810‬وتأريــخ‬\n‫‪1433/07/13‬ه ـ ويف يــوم األحــد تاريــخ ‪1433/07/13‬ه ـ الســاعة‬\n‫الواحــدة والنصــف افتتحــت اجللســة وفيهــا حضــر املدعــي العــام وحضــر‬\n‫حلضــوره املدعــى عليــه ‪ .....‬فجــرى ســؤاله عــن هويته فأجاب بأنها ليســت‬\n‫بحوزتــه كمــا أنهــا ليســت بحــوزة مــن أحضــره فطلبنــا مــن محضريــه‬\n‫إحضــار هويتــه باجللســة القادمــة ورفعــت اجللســة لذلــك وأجلــت الــى يــوم‬\n‫غدٍ االثنني ‪1433/07/14‬هـ وكان ختام هذه اجللســة الســاعة الواحدة‬\n‫وخمــس وأربعــن دقيقــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/07/13‬ه ـ ويف يــوم االثنــن‬\n‫‪1433/07/14‬ه ـ الســاعة الواحــدة والربــع افتتحــت اجللســة وفيها حضر‬\n\n                                                                                   ‫‪382‬‬\n\f      ‫املدعــي العــام بهيئــة التحقيــق واالدعــاء العــام مبحافظــة اجلبيــل ‪......‬‬\n      ‫واملدعــى عليــه ‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪).....‬‬\n      ‫وبســؤال املدعــي العــام عــن دعواه قدم الئحــة دعوى عامة وطلب ضبطها‬\n      ‫وهــذا نصهــا‪ :‬بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة التحقيــق واالدعــاء العــام‬\n      ‫مبحافظــة اجلبيــل أدعــي علــى املواطــن ‪ ،......‬مبوجــب الســجل املدني رقم‬\n      ‫(‪ ، )......‬البالــغ مــن العمــر (‪ )18‬عام ـاً‪ ،‬موقــوف لــدى ســجن محافظــة‬\n      ‫اجلبيــل مبوجــب مذكــرة التوقيــف رقــم (‪/10073/21/21‬ج) وتاريــخ‬\n      ‫‪1432/11/21‬ه ـ حيــث أنــه بتاريــخ ‪1432/10/8‬ه ـ ورد خطــاب ضابــط‬\n      ‫خفــر القاعــدة البحريــة عــن قيــام املدعــى عليــه واحلــدث ‪.....‬واحلــدث ‪......‬‬\n      ‫بســرقة عــدة منــازل بالقاعــدة البحريــة (مت فــرز أوراق مســتقلة للحــدث‬\n      ‫(‪ ) ....‬واحلــدث (‪ )....‬وإحالتهمــا لــدار املالحظــة االجتماعيــة بالدمــام)‬\n      ‫وبضبــط إفــادة املواطن‪.......‬أفــاد أنــه عــاد إلــى منزلــه يــوم األحــد املوافــق‬\n      ‫‪1432/10/6‬ه ـ واكتشــف أن منزلــه تعــرض للدخــول مــن خــال البــاب‬\n      ‫اخللفــي للمنــزل وســرق منــه اســطوانتني غــاز وجهــاز (بــاي ستيشــن)‬\n      ‫وجهــاز هاتــف محمــول مــن نــوع ‪ ....‬وقــد أثبــت محضــر االسترشــاد مــن‬\n      ‫قبــل املدعــى عليــه إلــى منــزل املواطــن ‪ .......‬رقــم (‪ )20/13‬حيــث ذكــر‬\n      ‫أنــه ســرق مــن داخلــه (كاميــرا) وجهــاز (البتــوب) وجهــاز (ســوني)‬\n      ‫وجهــاز (بــاي ستيشــن) كمــا مت االسترشــاد إلــى املنــزل رقــم (‪)18/12‬‬\n      ‫واملنــزل رقــم (‪ )18/13‬التــي ذكــر املتهــم بأنهــا خاليــة مــن الســكان‬\n      ‫ا ولــم يســرق منهــا شــيء ‪ ،‬وكذلــك االسترشــاد إلــى منــزل رقــم‬             ‫أص ـ ً‬\n      ‫(‪ )B /18‬وذكــر بأنــه خالــي مــن الســكان ‪ ،‬وكذلــك االسترشــاد إلــى‬\n      ‫املنــزل رقــم (‪ )17/07‬العائــد للمواطــن ‪ ، ......‬واملنــزل رقــم (‪)17/09‬‬\n      ‫العائــد للمواطــن ‪ ،......‬واملنــزل رقــم (‪ )17/12‬العائــد للمواطــن‪.....‬‬\n\n\n‫‪383‬‬\n\f‫وكانــت جميعهــا حتــت حراســة الشــرطة العســكرية بحــي ‪ ........‬التابــع‬\n‫للقاعــدة البحريــة وبضبــط إفــادة املواطــن ‪ .....‬أفــاد أنــه عــاد إلــى منزلــه‬\n‫بتاريــخ ‪1432/10/12‬ه ـ وتبــن أن منزلــه تعــرض للدخــول عــن طريــق‬\n‫البــاب اخللفــي للمنــزل وســرقة جهــاز حاســب آلــي محمــول وأســطوانتني‬\n‫غــاز وثالثــة أجهــزة هواتــف محمولــة نــوع‪ .....‬وبضبــط إفــادة املواطــن‬\n‫‪ .......‬أفــاد بأنــه يف يــوم األحــد املوافــق ‪1432/10/6‬ه ـ وعنــد عودتــه مــن‬\n‫اإلجــازة وجــد أن منزلــه قــد تعــرض للدخــول عــن طريــق أحــد النوافــذ‬\n‫وســرقة أســطوانة غــاز صغيــرة مــن داخــل املنــزل وبضبــط إفــادة املواطــن‬\n‫‪ .......‬أفــاد أنــه عنــد عودتــه للمنــزل مــن إجازتــه الرســمية وجــد منزلــه‬\n‫تعــرض للدخــول عــن طريــق البــاب اخللفــي للمنــزل وســرقة جهــاز حاســب‬\n‫آلــي محمــول وأســوارتني ذهــب وكاميــرا تصويــر (ديجيتــال) مــن نــوع‬\n‫(كانــون) والبــوم صــور عائليــة خاصــة وبضبــط إفــادة املواطــن‪ .....‬أفــاد‬\n‫بأنــه اســتلم املنــزل يف أواخــر شــهر شــعبان ولــم يقــم بتأثيثــه أو ســكنه‬\n‫إلــى اآلن ولــم يالحــظ أي دخــول ملنزلــه ولــم يفتقــد أي شــيء كــون املنزل‬\n‫خالــي مــن األثــاث وبضبــط إفــادة املواطــن‪ .......‬أفــاد بأنــه اســتلم املنــزل‬\n‫مــن القاعــدة البحريــة يف شــهر رمضــان ولــم يقــم بتأثيثــه أو ســكنه ولــم‬\n‫يالحــظ أي دخــول أو مفقــودات مــن املنــزل وال يوجــد أي تكســير أو‬\n‫عبــث وبضبــط إفــادة املواطــن ‪ .........‬أفــاد أنــه اســتلم املنــزل مــن القاعــدة‬\n‫البحريــة يف شــهر شــعبان ولــم يقــم بتأثيثــه أو ســكنه وال حــظ أن البــاب‬\n‫مفتوحـ ًا وال يوجــد أي تكســير أو نحــوه وكان املنــزل خاليـ ًا مــن األثــاث‬\n‫وباســتجوابه أفــاد بأنــه قــام بالدخــول الغيــر مشــروع إلــى عشــر منــازل‬\n‫برفــق احلــدث ‪ .......‬وذلــك بالقفــز عــن طريــق الســور اخلارجــي ومــن ثــم‬\n‫الدخــول عبــر البــاب اخللفــي وأنــه قــام بالدخــول للمنــزل رقــم (‪)20/13‬‬\n\n\n                                                                                         ‫‪384‬‬\n\f      ‫العائــد للمواطــن‪ .....‬رفــق احلــدث ‪ .......‬وقيامهمــا بســرقة جهــاز حاســب‬\n      ‫آلــي محمــول و(كاميــرا) تصويــر والبــوم صــور وإســوارتني ذهــب أطفــال‬\n      ‫وجهــاز (بــاي ستيشــن) وأنــه قــام ببيــع جهــاز احلاســب آلــي احملمــول‬\n      ‫مببلــغ (‪ )500‬خمســمائة ريــا ًال رفــق احلــدث ‪ ......‬يف محافظــة اجلبيــل‬\n      ‫وأعطــى احلــدث ‪ ......‬جهاز(البــاي ستيشــن) أمــا (الكاميــرا) فأخذهــا‬\n      ‫احلــدث ‪ ......‬وباعهــا علــى املواطــن ‪ ......‬مبحافظــة األحســاء وأمــا الصــور‬\n      ‫وأســوارتي الذهــب فتوجــد لديــه يف املنــزل ‪ ،‬كمــا أنــه قــام بالدخــول‬\n      ‫إلــى منــزل رقــم (‪ )18/12‬رفــق احلــدث ‪ ................‬وكان خالي ـ ًا ولــم‬\n      ‫يســرق منــه شــيء ‪ ،‬وقــام بالدخــول إلــى منــزل رقــم (‪ )18/13‬رفــق‬\n      ‫احلــدث‪..................‬وكان خاليـ ًا ولــم يســرق منــه شــيء ‪ ،‬وقــام بالدخــول‬\n      ‫إلــى منــزل رقــم (‪ )B / 18‬رفــق احلــدث ‪...........‬وكان خاليـ ًا ولــم يســرق‬\n      ‫منــه شــيء ‪ ،‬وقــام بالدخــول إلــى منــزل رقــم (‪ )17/07‬العائــد للمواطــن‬\n      ‫‪ ............‬وقــام بســرقة جهــاز (بــاي ستيشــن) وأنــه قــام ببيعــه مــع احلــدث‬\n      ‫‪ .......‬وتقاســما املبلــغ بينهمــا ‪ ،‬وقــام بالدخــول إلــى منــزل رقــم (‪)17/09‬‬\n      ‫للمواطــن ‪ ......‬رفــق احلــدث ‪ ........‬وقامــا بســرقة جهــاز‬              ‫العائــد‬\n      ‫حاســب آلــي محمــول وثالثــة أجهــزة هواتــف محمولــة وأخذهــا جميعهــا‬\n      ‫احلــدث‪ ، .........‬وقــام بالدخــول إلــى منــزل رقــم (‪ )17/12‬يعــود للمواطــن‬\n      ‫‪ .........‬رفــق احلــدث ‪ ......‬وقامــا بســرقة عــدد (‪ )3‬ثالثــة أجهــزة (بــاي‬\n      ‫ستيشــن) وجهــازي حاســب آلــي محمــول وقــام ببيعهــا بنفســه وتقاســم‬\n      ‫املبلــغ مــع احلــدث ‪ ، ........‬وقــام بالدخــول إلــى املنــزل رقــم (‪ )16/8‬العائــد‬\n      ‫للمواطــن ‪ ......‬رفعــه احلــدث ‪ .......‬وســرقة اســطوانة غــاز مــن داخلــه مــن‬\n      ‫قبــل احلــدث ‪ ، .......‬وقــام بالدخــول إلــى املنــزل رقــم (‪ )16/11‬رفــق‬\n      ‫احلــدث ‪ ..........‬وكان خاليـ ًا ولــم يســرق منــه شــيء ‪ ،‬وقــام بالدخــول إلــى‬\n\n\n‫‪385‬‬\n\f‫املنــزل رقــم (‪ )16/9‬العائــد للمواطــن ‪ .........‬رفــق احلــدث ‪ ........‬وقامــا‬\n‫بســرقة جهــاز (بــاي ستيشــن ‪ )2‬مــن قبــل احلــدث ‪ ..........‬وال يعلــم أيــن‬\n‫ذهــب بــه ونفــى مــا ســوى ذلــك وبضبــط إفــادة املواطــن‪ ........‬أفــاد بأنــه‬\n‫قبــل عيــد الفطــر بيومــن تقريب ـ ًا وجــد احلــدث ‪ .......‬ومعــه (كاميــرا)‬\n‫تصويــر لونهــا أســود وقــال لــه بأنهــا لعائلتــه ويرغبــون ببيعهــا وعــرض‬\n‫عليــه شــراءها مببلــغ (‪ )120‬مائــة وعشــرين ريــا ًال فوافــق واشــتراها‬\n‫منــه بذلــك املبلــغ ‪ ،‬وبعــد طلــب الشــرطة العســكرية لــه وســؤاله عنهــا‬\n‫أحضرهــا لهــم وأنــه عندمــا قــام بشــرائها مــن احلــدث ‪ .......‬كانــت خاليــة‬\n‫مــن الصــور ولــم يعلــم بأنهــا مســروقة وقــد أثبــت محضــر االســتالم أن‬\n‫املواطــن ‪ ........‬قــد اســتلم (‪ )10‬عشــر صــور عائليــة خاصــه بعــد التأكــد‬\n‫منهــا وتعرفــه عليهــا كاملــة وأســاور ذهــب صغيــرة بعــد التأكــد منهــا‬\n‫وأكــد بــأن جميعهــا تعــود لــه وأنهــا هــي التــي ســرقت مــن منزلــه بحــي‬\n‫الســام كمــا أثبــت محضــر االســتالم‪ .‬أن املواطــن ‪ ........‬تســلم كاميــرا‬\n‫مــن نــوع (كانــون ديجيتــال) ســوداء اللــون وانتهــى التحقيــق إلــى توجيــه‬\n‫االتهــام لــه بانتهــاك حرمــة عــدة منــازل والســرقة منهــا ألجهــزة حواســيب‬\n‫آليــة محمولــة وأجهــزة هواتــف محمولــة واســطوانات غــاز واســوارتني‬\n‫ذهــب وأجهــزة كهربائيــة (كاميــرات ‪ ،‬باليستيشــن) وبعــض املقتنيــات‬\n      ‫اخلاصــة مــن حــرز بعــد هتكــه ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪-:‬‬\n‫‪ -1‬اعترافــه املنــوه عنــه واملــدون علــى الصفحــات رقــم (‪- 9 ، 4 - 2‬‬\n‫‪ )16 - 15 ، 10‬مــن دفتــر التحقيــق املرفــق علــى اللفــة رقــم (‪ )2‬وعلــى‬\n‫الصفحــات رقــم (‪ )6 ، 3 - 1‬مــن دفتــر التحقيــق املرفــق علــى اللفــة رقــم‬\n‫(‪ )1‬وعلــى الصفحتــن رقــم (‪ )10 - 9‬مــن دفتــر التحقيــق املرفــق علــى‬\n                                                                ‫اللفــة رقــم (‪.)46‬‬\n\n\n                                                                                      ‫‪386‬‬\n\f      ‫‪ -2‬خطــاب ضابــط خفــر القاعــدة البحريــة املنــوه عنــه املرفــق علــى اللفــة‬\n                                                                                    ‫رقــم (‪.)14‬‬\n      ‫‪ -3‬محضــري االسترشــاد املنــوه عنهمــا املدونــن علــى الصفحتــن‬\n      ‫رقــم (‪ )14-13‬مــن ملــف التحقيــق رقــم (‪ )1‬علــى اللفــة رقــم (‪ )1‬وعلــى‬\n      ‫الصفحــة رقــم (‪ )11‬مبلــف التحقيــق رقــم (‪ )4‬علــى اللفــة رقــم (‪.)46‬‬\n      ‫‪ -4‬محضــر اإلثبــات املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )4‬مــن ملــف‬\n                                                     ‫حتقيــق رقــم (‪ )2‬علــى اللفــة رقــم (‪.)2‬‬\n      ‫‪ -5‬محضــر ســند اســتالم املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )5‬مــن‬\n                                            ‫ملــف حتقيــق رقــم (‪ )2‬علــى اللفــة رقــم (‪.)2‬‬\n      ‫‪ -6‬مــا جــاء يف أقــوال الشــاهد املواطــن ‪ ............‬املنــوه عنــه املدونــة علــى‬\n      ‫الصفحــات رقــم (‪ )4-2‬مبلــف التحقيــق رقــم (‪ )4‬علــى اللفــة رقــم (‪.)46‬‬\n      ‫‪ -7‬محاضــر االنتقــال واملعاينــة املرفقــة علــى اللفــات رقــم (‪.)77-74‬‬\n      ‫وبالبحــث عمــا إذا كان لــه ســوابق جنائيــة لــم يعثــر لــه علــى ســوابق‬\n      ‫مســجلة وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليه شــرع ًا وهو ســرقة مــال محترم‬\n      ‫مــن حــرزه بعــد هتكــه يزيــد عــن النصــاب ال شــبهة لــه فيــه وطالــب بــه‬\n      ‫صاحبــه ولكــون اجلانــي مكلف ـ ًا غيــر مكــره أطلــب إثبــات مــا أســند‬\n      ‫إليــه واحلكــم عليــه بحــد الســرقة الــواردة يف اآليــة الكرميــة رقــم (‪)38‬‬\n                ‫مــن ســورة املائــدة‪( ،‬علم ـ ًا بــأن احلقــوق اخلاصــة ال تــزال قائمــة)‪.‬‬\n      ‫واهلل الهــادي إلــى ســواء الســبيل ( واهلل املوفــق ) ا‪.‬ه ـ هــذه دعــواي‬\n      ‫وبتــاوة دعــوى املدعــي العــام علــى املدعــى عليــه وســؤاله عنهــا أجــاب‬\n      ‫قائــا‪ :‬مــا ذكــره املدعــي العــام يف دعــواه كلــه غيــر صحيــح جملــة‬\n      ‫وتفصيــا والصحيــح أننــي دخلــت منــزل ‪ ........‬رقــم ‪ .....‬فقــط مــن‬\n\n\n‫‪387‬‬\n\f‫البــاب اخللفــي حيــث يســحب ســحب ووجــدت داخــل املنــزل « البتــوب»‬\n‫يف الصالــة وأخذتــه وبعتــه مببلــغ خمســمائة ريــال علــى محــل يف اجلبيــل‬\n‫مقابــل بنــده بحــي الدخــل احملــدود وأمــا بقيــة البيــوت فــا أعــرف عنهــا‬\n‫شــيء كمــا أننــي ال أعــرف املدعــو ‪ .......‬كمــا أننــي ال أعــرف املدعــو‬\n‫‪ .......‬جيــدا وقــد كنــت أشــاهده حــول بيتنــا هــو وأبنــاء عمومتــه وبينــي‬\n‫وبينهــم خصومــة هكــذا أجــاب ‪ .‬ثــم جــرى ســؤال املدعــي العــام هــل‬\n‫املفصلــة‬\n     ‫ّ‬     ‫لديــه بينــة علــى دعــواه مــن ســرقة املنــازل املذكــورة واألغــراض‬\n‫يف الدعــوى واملقتنيــات اخلاصــة ؟ فأجــاب ‪ :‬بينتــي مــا ذكــرت يف الئحــة‬\n‫الدعــوى ومــا هــو موجــود بــأوراق املعاملــة هكــذا أجــاب فرفعــت اجللســة‬\n‫لالطــاع علــى أوراق املعاملــة وســؤال املدعــى عليــه عنهــا وكان ختــام‬\n‫هــذه اجللســة الســاعة الثانيــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                ‫وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف ‪1433/07/14‬ه ـ ‪.‬‬\n‫ويف يــوم الثالثــاء ‪1433/09/05‬ه ـ افتتحــت اجللســة الســاعة الثانيــة‬\n‫عشــرة والنصــف وفيهــا حضــر املدعــي العــام واملدعــى عليــه ثــم جــرى‬\n‫االطــاع علــى أوراق املعاملــة فوجدنــا فيهــا االعتــراف املــدون علــى‬\n‫الصفحــة (‪ )16-10،15 -9 ،4 -2‬مــن دفتــر التحقيــق املرفــق علــى‬\n‫اللفــة رقــم (‪ )2‬والصفحــات رقــم (‪ )6 ، 3-1‬مــن دفتــر التحقيــق‬\n‫املرفــق علــى اللفــة رقــم (‪ )1‬وعلــى الصفحتــن رقــم (‪ )10-9‬مــن دفتــر‬\n‫التحقيــق املرفــق علــى اللفــة رقــم (‪ )46‬واملتضمنــة إقــرار املدعــى عليــه‬\n‫بتفاصيــل الســرقات املثبتــة يف الئحــة الدعــوى وإقــراره بانتهــاك حرمــة‬\n‫عــدة منــازل كمــا أجــاب علــى ســؤال مــن قبــل احملقــق وهــذا نصــه س‪/‬‬\n‫كيــف تقومــون بالدخــول إلــى املنــازل ؟ ج ‪ :‬عــن طريــق القفــز مــن الســور‬\n‫ا فنقــوم‬ ‫اخلارجــي ونقــوم بســحب البــاب اخللفــي الــذي يكــون مقف ـ ً‬\n\n\n                                                                                     ‫‪388‬‬\n\f      ‫بســحبه حتــى يتــم فتحــه ونقــوم بالدخــول مــن خاللــه للمنــزل ا‪.‬ه ـ وبتــاوة‬\n      ‫جميــع مــا ذكــر مــن التقاريــر املدونــة بدفاتــر التحقيــق علــى املدعــى‬\n      ‫ا ‪ :‬هــذا الــكالم غيــر صحيــح ولــم اطلــع‬    ‫عليــه وســؤاله عنهــا أجــاب قائـ ً‬\n      ‫احملقــق إال علــى بيــت ‪ ......‬كمــا جــرى االطــاع علــى خطــاب ضابــط‬\n      ‫خفــر القاعــدة البحريــة املرفــق مــع اللفــة رقــم (‪ )14‬واملتضمــن تســليم‬\n      ‫املدعــى عليــه مــع املدعويــن ‪ ......‬و ‪ .......‬لضابــط خفــر شــرطة اجلبيــل‬\n      ‫‪ ...‬وبتــاوة ذلــك علــى املدعــى عليــه وســؤاله عنــه أجــاب قائــا‪ -:‬ال‬\n      ‫أعــرف الشــخصني املذكوريــن و ‪ ......‬أراه بجــوار الســكن كمــا جــرى‬\n      ‫اال طــاع علــى محضــري االسترشــاد املدونــن علــى اللفــة رقــم(‪،)1‬‬\n      ‫(‪ )46‬واملتضمنــان الشــخوص مــن قبــل احملقــق إلــى املنــازل املســروقة‬\n      ‫برفقــة املدعــى عليــه ويرافقــه املدعــو ‪ ......‬وبتــاوة ذلــك علــى املدعــى‬\n      ‫عليــه وســؤاله عنــه أجــاب قائ ـاً‪ :‬الصحيــح مــا ذكرتــه يف اجللســة‬\n      ‫املاضيــة وهــذا الــكالم املتضمــن ســرقات كثيــرة غيــر صحيــح كمــا‬\n      ‫جــرى االطــاع علــى محضــر اإلثبــات علــى اللفــة رقــم (‪ )1‬واملتضمــن‬\n      ‫اســتالم بعــض املســروقات مــن والــد املدعــى عليــه ‪ ..........‬وبتــاوة جميــع‬\n      ‫ذلــك علــى املدعــى عليــه وســؤاله عنــه أجــاب قائـاً‪ :‬هــذا الــكالم غيــر‬\n      ‫صحيــح ولــم أســرق اال مــن بيــت ‪ .....‬كمــا جــرى االطــاع علــى محضــر‬\n      ‫ســند االســتالم املرفــق علــى اللفــة رقــم (‪ )2‬واملتضمــن اســتالم املواطــن‬\n      ‫‪ .......‬لبعــض املســروقات اخلاصــة بــه‪ ،‬وبتــاوة ذلــك علــى املدعــى عليــه‬\n      ‫وســؤاله عنــه أجــاب قائـاً‪ :‬هــذا يؤكــد مــا ذكرتــه أننــي لــم أســرق اال‬\n      ‫مــن بيــت ‪ .....‬كمــا جــرى اال طــاع علــى أقــوال الشــاهد ‪ ......‬واملــدون‬\n      ‫علــى اللفــة رقــم (‪ )46‬واملتضمــن شــراء الشــاهد ‪ .....‬كاميــرا مســروقة‬\n      ‫مــن املدعــو ‪ ......‬والــذي رافــق املدعــى عليــه يف الســرقة وبتــاوة ذلــك‬\n\n\n‫‪389‬‬\n\f‫ا ‪ :‬هــذا الــكالم غيــر‬                  ‫علــى املدعــى عليــه وســؤاله عنــه أجــاب قائ ـ ً‬\n‫صحيــح و‪ .....‬هــو الســارق وقــد أتيــت إليــه لبيعهــا ســويا هكــذا أجــاب‬\n‫كمــا جــرى االطــاع علــى محاضــر االنتقــال واملعاينــة ثــم جــرى ســؤال‬\n‫املدعــى عليــه عــن ســوابقه فقــال‪ :‬ال يوجــد علـ ّـي أي ســابقة ثــم جــرى‬\n‫ســؤاله عــن وقــت الســرقة وعــن مــكان بيــت ‪ ........‬املذكــور؟ فقــال ‪:‬‬\n‫كانــت الســرقة يف العشــر االخيــر مــن رمضــان وبيــت ‪ .....‬هــو جارنــا‬\n‫املالصــق هكــذا أجــاب ‪ .‬وملزيــد التأمــل يف أوراق املعاملــة ولتــداول‬\n‫احلكــم قررنــا رفــع اجللســة وعليــه جــرى التوقيــع وكان ختــام هــذه‬\n‫اجللســة الســاعة الواحــدة والنصــف وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/09/05‬ه ـ ويف‬\n‫يــوم االثنــن ‪1433/09/18‬ه ـ الســاعة احلاديــة عشــر والربــع افتتحــت‬\n‫اجللســة وفيهــا حضــر املدعــي العــام واملدعــى عليــه فبنــاء علــى مــا تقـ َّـدم‬\n‫املدعــى عليــه مــا جــاء يف دعــوى‬                   ‫الدعــوى واإلجابــة املتضمنــة إنــكار ًّ‬                            ‫مــن ًّ‬\n‫املدعــي العــام جملــة وتفصيــا ســوى دخــول منــزل ‪ ........‬وســرقة جهــاز‬                                                       ‫ّ‬\n‫وألن مثــل هــذا العمــل محـ َّـر ٌم‬              ‫حاســب آلــي محمــول (الب تــوب) منــه‪ّ ،‬‬\n‫شــرعاً‪ ،‬ومجـ ّـر ٌم نظام ـاً‪ ،‬يســتحق فاعلــه التأديــب‪ ،‬حيــث قــال ال َّنبــي‬\n‫«كلُّ ْال ُْسـل ِِم َع َلــى ْال ُْسـل ِِم‬  ‫ص َّلــى اهلل عليــه وســلم يف احلديــث الصحيــح‪ُ :‬‬\n‫َحـ َـر ٌام‪َ ،‬د ُمـ ُه‪َ ،‬و َما ُلـ ُه‪َ ،‬وعِ ْر ُضـ ُه» رواه مســلم مــن حديــث أبــي هريــرة ومبا‬\n‫املدعــى عليــه أنكــر كــون بــاب املنــزل املذكــور مقفــا‪ ،‬أو أ َّنــه قــام‬                                                 ‫أن َّ‬‫َّ‬\n‫حد الســرقة ال تكتمل‬                   ‫مما جعل شــروط ِّ‬                   ‫بكســره‪ ،‬وال ِّبينة على ذلك؛ َّ‬\n‫ـوكا ) َف َأ َخـ َـذ مِ ْن ـ ُه‬\n                             ‫[(ف ـ ِإنْ َو َجـ َـد حِ ـ ْـر ًزا َم ْه ُتـ ً‬   ‫حقــه قــال يف الكشــاف‪َ :‬‬                      ‫يف ِّ‬\n‫وحــا َف َأ َخـ َـذ مِ ْنـ ُه َفـ َـا قَ ْطـ َـع) ل َِعـ َـد ِم َشـ ْـر ِطهِ]‬                  ‫َفـ َـا قَ ْطـ َـع ( َأ ْو) َو َجـ َـد َ‬\n                                                                             ‫(ب ًابــا َم ْف ُت ً‬\n‫‪ ،. 134/6‬إضافــة لوجــود الشــبهة يف أجوبــة املدعــى عليــه املؤديــة لــدرء‬\n\n\n                                                                                                                                          ‫‪390‬‬\n\f      ‫املدعــى عليــه أقـ َّـر بأ َّنــه ارتكــب هــذه اجلرميــة يف شــهر‬                          ‫احلـ ِّـد‪ ،‬ولكــون َّ‬\n      ‫رمضــان ويف العشــر األخيــر منــه؛ مــع ق ّلــة دواعــي املعصيــة‪ ،‬وكثــرة‬\n      ‫ـأن املنــزل املذكــور يف جوابــه والــذي أقــر‬                          ‫بواعــث الطاعــة‪ ،‬كمــا أقـ ّـر بـ َّ‬\n      ‫بانتهــاك حرمتــه هــو منــزل اجلــار املالصــق لبيــت والــده؛ وكال هذيــن‬\n      ‫األمريــن مدعــاة لتشــديد العقوبــة عليــه حيــث قــال ال َّنبــي ص َّلــى اهلل عليــه‬\n      ‫وسـلَّم‪... « »:‬ألن يســرق الرجل من عشــر أبيات أيســر عليه من أن يســرق‬\n      ‫مــن جــاره « رواه اإلمــام أحمــد والبخــاري يف األدب املفــرد وصححــه ابــن‬\n      ‫حبــان واملنــذري واأللبانــي يف الصحيحــة وجــاء يف صحيــح مســلم َعنْ َأ ِبي‬\n                      ‫{ل َيدْ ُخــلُ ْ َ‬\n       ‫ال َّنـ َة َمــنْ‬               ‫هلل ص َّلــى اهلل َع َل ْيـ ِه َو َسـل ََّم قَ ــالَ ‪َ :‬‬ ‫ُه َر ْيـ َـر َة‪َ ،‬أ َّن َر ُســولَ ا ِ‬\n      ‫ـار ُه َب َوائ َِقـ ُه} وقــال شــيخ اإلســام ابــن تيميــة‪« :‬وغلــظ املعصيــة‬                          ‫َل َي ْأ َمـ ُـن َجـ ُ‬\n      ‫وعقابهــا بقــدر فضيلــة الزمــان واملــكان» االختيــارات ‪ 294‬ألجــل ذلــك‬\n      ‫كلــه وجلميــع مــا ســبق فقــد ثبــت لدينــا إدانــة املدعــى عليــه ‪ ......‬بانتهــاك‬\n      ‫حرمــة منــزل جــاره‪ ،‬يف شــهر رمضــان املبــارك‪ ،‬وســرقة جهــاز حاســب‬\n      ‫املدعــى عليــه‬\n                   ‫آلــي محمــول منــه وحكمنــا عليــه مبــا يلــي‪ -:‬أوال‪ُ /‬يســجن ّ‬\n      ‫ســنتني تبــدأ مــن تأريــخ إيقافــه علــى ذمــة هــذه القضيــة ‪.‬ثانيــا‪ُ /‬يجلــد‬\n      ‫مفرقــة علــى عشــر دفعــات كل دفعــة‬        ‫املدعــى عليــه خمســمائة جلــدة َّ‬     ‫َّ‬\n      ‫خمســون جلــدة بــن كل دفعــة واألخــرى مـ َّـدة ال تقــلَّ عــن أســبوعني‪ ،‬مــع‬\n      ‫اإليصــاء بــأن تكــون آخــر دفعتــن مــن اجللــد أمــام أقــرب جامـ ٍـع للحــي‬\n      ‫الــذي يســكنه املدعــى عليــه بعــد صــاة اجلمعــة‪ ،‬وبعــرض ذلــك علــى‬\n      ‫الطرفــن قـ َّـرر املدعــي العــام االعتــراض وطلــب رفــع احلكــم لالســتئناف‬\n      ‫بــدون الئحــة اعتراضيــة وقـ َّـرر املدعــى عليــه القناعــة وكان ختــام هــذه‬\n      ‫اجللســة الســاعة الثانيــة عشــر والربــع وبــاهلل التوفيــق وصلــى اهلل علــى‬\n                                            ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n\n\n‫‪391‬‬\n\f‫احلمــد هلل وحــده وبعــد ‪ -:‬ويف يــوم االثنــن ‪1434/02/18‬ه ـ الســاعة‬\n‫التاســعة افتتحــت اجللســة لدينــا نحــن رئيــس احملكمــة العامــة باجلبيــل‬\n‫‪ ........‬و ‪ .......‬و ‪ .........‬القاضيــان باحملكمــة العامــة باجلبيــل وقــد باشــر‬\n‫فضيلــة الشــيخ ‪ .....‬عملــه بعــد دورة ملــدة شــهرين ابتــدأت بتاريــخ‬\n‫‪1433/12/18‬ه ـ ويف هــذه اجللســة حضــر املدعــي العــام وكانــت‬\n‫املعاملــة وردتنــا مــن محكمــة االســتئناف ومرفقــا بهــا القــرار رقــم‬\n‫‪ 33456744‬وتأريــخ ‪1433/11/16‬ه ـ ويتضمــن املالحظــة ونــص احلاجــة‬\n‫منــه مــا يلــي ‪ ( :‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ‬\n‫أن املدعــي العــام طالــب بإقامــة حــد الســرقة ولــم يبــن احلــرز الــذي مت‬\n‫هتكــه حتــى يتــم نظرهــا مشــترك ملالحظــة مــا ذكــر وإكمــال الــازم‬\n‫ومــن ثــم إعــادة املعاملــة إلكمــال الزمهــا واهلل املوفــق ) فجــرى عــرض‬\n‫مالحظــة أصحــاب الفضيلــة قضــاة االســتئناف علــى املدعــي العــام‬\n‫فأجــاب ‪ :‬إنــه قــد ورد يف جــواب املدعــى عليــه هتــك احلــرز املرفــق بدفتــر‬\n‫التحقيــق رقــم (‪ )1‬لفــة رقــم (‪ )2‬صحيفــة رقــم (‪ )15‬عنــد ســؤال احملقــق‬\n‫لــه الســؤال التالــي س‪ :‬أفدنــي كيــف تقومــون بالدخــول إلــى املنــازل؟‬\n‫ج‪ :‬عــن طريــق القفــز مــن الســور اخلارجــي ونقــوم بســحب البــاب اخللفــي‬\n‫الــذي يكــون مقفــا فنقــوم بســحبه حتــى فتحــه ونقــوم مــن خاللــه‬\n‫بالدخــول للمنــزل ‪ .‬كمــا جــاء يف اللفــة رقــم (‪ )45‬صحيفــة (‪ )2‬بــاغ‬\n‫صاحــب املنــزل املســروق ‪ ......‬حيــث جــرى ســؤاله مــن قبــل ضابــط خفــر‬\n‫املنــاوب الســؤال التالــي س‪ :‬أفدنــي مبضمــون بالغــك مفصــا ؟ ج ‪:‬‬\n‫كنــا نســافر أنــا وعائلتــي خــارج اجلبيــل وعنــد عودتنــا للمنــزل اليــوم‬\n‫وجــدت البــاب اخللفــي للمنــزل مكســور والبيــت مســروق وقــد ســرق منــه‬\n‫ســوار ذهــب ‪ ....‬إلــخ وال شــك أن األبــواب املغلقــة حــرز لهــذه الــدور وأن‬\n\n\n                                                                                       ‫‪392‬‬\n\f      ‫حديــة مــع باقــي الشــروط األخــرى ولــم‬   ‫هتكهــا وكســرها يعـ ُّـد جرميــة ّ‬\n      ‫تــرد اإلشــارة ملثــل ذلــك يف الئحــة املدعــي العــام ســهوا هكــذا أجــاب ‪.‬‬\n      ‫وقررنــا رفــع املعاملــة حملكمــة االســتئناف لتدقيقهــا وكان ختــام هــذه‬\n      ‫اجللســة الســاعة العاشــرة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه أجمعــن ‪ .‬حــرر يف ‪1434/12/18‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n      ‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة اجلبيــل‬\n      ‫الشــيخ ‪ .......‬برقــم ‪ 33/2134826‬وتاريــخ ‪1434/2/23‬ه ـ واملقيــدة لــدى‬\n      ‫احملكمــة برقــم ‪/34/482930‬خ‪ 1‬وتاريــخ ‪1434/2/26‬ه ـ املرفــق بهــا‬\n      ‫القرار الشرعي ذو الرقم ‪ 33415014‬والتاريخ ‪1433/9/18‬هـ الصادر‬\n      ‫مــن فضيلتــه وصاحبــي الفضيلــة القضــاة باحملكمــة املشــاركني لــه‬\n      ‫الشــيخ ‪ .........‬والشــيخ ‪ ........‬اخلــاص بدعــوى املدعــي العــام ضــد ‪........‬‬\n      ‫يف قضيــة ســرقة وقــد تضمــن القــرار حكــم أصحــاب الفضيلــة مبــا هــو‬\n      ‫مــدون ومفصــل فيــه ‪ .‬وحيــث ســبق دراســة القــرار وصورة ضبطــه وأوراق‬\n      ‫املعاملــة وباالطــاع علــى مــا أجــاب بــه أصحــاب الفضيلــة علــى قرارنــا‬\n      ‫رقــم ‪/33456744‬خ‪/1‬ب وتاريــخ ‪1433/11/16‬ه ـ ـ قررنــا املصادقــة‬\n      ‫علــى احلكــم بعــد االيضــاح األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                           ‫محمــد وآلــه وصحبــه وســلم حــرر يف ‪ 1434/3/16‬هـ ـ ـ ـ ‪.‬‬\n\n\n\n\n‫‪393‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":381,"source_page_end":393,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ffb80095b1f7c13e5d9a3f768fb9e80899bfb5d1d728c4f8fcf384d3ce452d4a","normalized_text_hash":"e35f1e1c4aad79af25ae3973f1a6180f55abb7b61a6f5dbd2d40c7acea726199","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p381-33415014"},{"id":"21b8f431-d401-5af8-b1e4-591ecaae0b01","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -اشتراك يف سرقة -سرقة سيارة ومركز جتاري و مقصف مدرسة-تعاطي احلبوب احملظورة -سرقة معدات كهربائية -تهديد بالقتل و مضايقة الغير بالسيارة -رجوع عن إقرار - -تطابق أمناط وراثية -درء حد السرقة -تعزير بالسجن واجللد.","document_number":"33480442","case_number":"33467073","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالباحة ( )","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/27","year":"1434","subject":"سرقة -اشتراك يف سرقة -سرقة سيارة ومركز جتاري و مقصف مدرسة-تعاطي احلبوب احملظورة -سرقة معدات كهربائية -تهديد بالقتل و مضايقة الغير بالسيارة -رجوع عن إقرار - -تطابق أمناط وراثية -درء حد السرقة -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 33480442:‬تاريخه ‪1433/12/27:‬هـ‬\n                    ‫رقم الدعوى ‪33467073:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n             ‫‪ 34243882‬تاريخه ‪1434/6/18:‬ه‬\n\n\n\n‫ســرقة‪ -‬اشــتراك يف ســرقة ‪ -‬ســرقة ســيارة ومركــز جتــاري و مقصــف‬\n‫مدرســة‪-‬تعاطي احلبــوب احملظــورة ‪ -‬ســرقة معــدات كهربائية‪ -‬تهديد‬\n‫بالقتــل و مضايقــة الغيــر بالســيارة‪ -‬رجــوع عــن إقــرار ‪ - -‬تطابــق أمناط‬\n                 ‫وراثيــة ‪ -‬درء حــد الســرقة ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n‫‪-1‬قولــه صلــى اهلل عليــه وســلم ( مــن أصــاب بفيــه مــن ذي حاجــة غيــر‬\n‫متخــذ خبنــة فــا شــيء عليــه ومــن خــرج بشــيء منــه فعليــه غرامــة‬\n‫مثليــه والعقوبــة ومــن ســرق منــه شــيئا بعــد أن يؤويــه اجلريــن فبلــغ‬\n                                              ‫ثمــن املجــن فعليــه القطــع)‪.‬‬\n‫‪-2‬قولــه صلــى اهلل عليــه وســلم (كل املســلم علــى املســلم حــرام دمــه‬\n                                                           ‫ومالــه وعرضــه)‪.‬‬\n‫‪-3‬قولــه عليــه الصــاة والســام (املســلم مــن ســلم املســلمون مــن لســانه‬\n                                                                     ‫ويــده )‪.‬‬\n‫‪-4‬ماقــرره أهــل العلــم وحكــوه إجماع ـ ًا مــن اشــتراط إخــراج الســارق‬\n                       ‫للمســروق مــن حــرز مثلــه إلقامــة احلــد عليــه ‪.‬‬\n\n\n\n\n                                                                                 ‫‪394‬‬\n\f      ‫دعــوى املدعــي العــام ضــد املدعــى عليهمــا باالشــتراك يف جرميــة ســرقة‬\n      ‫صيدليتــن ومحتويــات كهربائيــة لعمــارة حتــت اإلنشــاء ومحتويــات‬\n      ‫مقصف مدرســة ومركز جتاري وأجهزة حاســب آلي وجواالت وتهديد‬\n      ‫األول ملواطــن بالقتــل وســرقة ســيارة ومضايقــة الثانــي بســيارته ملواطــن‬\n      ‫بالطريــق العــام وإفاقتــه يف ســاعة متأخــرة مــن الليــل وتعاطــي احلبــوب‬\n      ‫احملظــورة وطلــب املدعــي العــام إقامــة حــد الســرقة علــى املدعــى عليهمــا‬\n      ‫وطلــب احلكــم علــى األول بعقوبــة تعزيريــة لقــاء تهديــده للغيــر بالقتــل‬\n      ‫وعقوبــة تعزيريــة علــى الثانــي لقــاء مضايقتــه للغيــر يف ســاعة متأخــرة‬\n      ‫مــن الليــل ‪ ،‬عــدل املدعــي العــام الئحتــه وأضــاف طلــب تعزيــر األول لقــاء‬\n      ‫تعاطيــه احلبــوب احملظورة‪،‬أقراملدعــى عليــه األول بســرقة ســيارة فقــط‬\n      ‫وإنــكاره مــا ســوى ذلك‪،‬أنكــر املدعــى عليــه الثانــي‪ ،‬وجــود إقــرارات‬\n      ‫حتقيق ـ ًا للمدعــى عليــه األول بالســرقات‪ ،‬تطابقــت األمنــاط الوراثيــة‬\n      ‫لعينــات دم مــن املدعــى عليهمــا مــع عينــات أخــذت مــن مســرح اجلرائــم‬\n      ‫ملواقــع مختلفــة‪ ،‬رجــع املدعــى عليــه األول عــن إقــراره حتقيقـاً‪ ،‬درء حــد‬\n      ‫الســرقة للمدعــى عليــه األول‪ ،‬وتعزيــر املدعــى عليهمــا بالســجن واجللــد‪،‬‬\n                                 ‫مت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪395‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لدينــا‬\n‫نحــن (‪ ).....‬رئيــس احملكمــة العامــة بالباحــة (‪ ).....‬القاضــي باحملكمــة‬\n‫العامــة بالباحــة و (‪ ).....‬القاضــي باحملكمــة العامــة بالباحــة وبنــاء علــى‬\n‫املعاملــة الــواردة إلينــا مــن هيئــة التحقيــق واالدعــاء العــام بالباحــة برقــم‬\n‫(‪ ).....‬يف ‪1433/7/13‬ه ـ واملقيــدة باحملكمــة برقــم (‪ ).....‬يف‬\n‫‪1433/7/15‬ه ـ واحملالــة إلينــا برقــم ‪ 33467073‬يف ‪1433/7/15‬ه ـ‬\n‫ويف يــوم االثنــن املوافــق ‪1433/7/28‬ه ـ افتتحت اجللســة األولى الســاعة‬\n‫العاشــرة وفيهــا حضــر املدعــي العــام (‪ ).....‬حامــل الســجل املدنــي رقــم‬\n‫(‪ ).....‬مبوجــب التكليــف رقــم ه ـ (‪ ).....‬يف ‪1430/12/28‬هـ وقدم الئحة‬\n‫الدعــوى العامــة رقــم ‪ 578‬لعــام ‪1432‬ه ـ واملرفقــة باملعاملــة علــى شــريط‬\n‫ســي دي والتــي جــاء فيهــا مــا نصــه « أدعــي علــى كل مــن ‪).....( /1‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬العمــر ‪ 19‬عامــا‬\n‫ومهنتــه طالــب موقــوف مبوجــب األمــر رقم (‪ ).....‬وتاريــخ ‪1433/3/11‬هـ‬\n‫بالســجن العــام بالباحــة ‪ ).....( /2‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ ).....‬العمــر ‪ 21‬ومهنتــه طالــب موقــوف مــن تاريــخ‬\n‫‪1433/3/11‬ه ـ بالســجن العــام بالباحــة فباالطــاع علــى محضــر تنفيــذ‬\n‫مهمــة رقــم ‪ ......‬وتاريــخ ‪1428/2/8‬ه ـ واملعــد مــن قبــل إحــدى فــرق‬\n‫الدوريــات األمنيــة بالباحــة واملتضمــن بــاغ موظــف (‪ ).....( / ).....‬ـ‬\n‫ـاء من‬\n     ‫مصــري اجلنســية ـ الواقعــه بالـ ـ (‪ ).....‬أنــه عنــد الســاعه (‪ )8.45‬مسـ ً‬\n‫يــوم االثنــن املوافــق ‪1428/2/8‬ه ـ ورد بــاغ لغرفــة العمليــات مــن قبــل‬\n‫املدعــي بحــدوث ســرقة الصيدليــة وباالنتقــال وجــد املدعــي داخــل‬\n\n                                                                                         ‫‪396‬‬\n\f      ‫ا وبعثرة بعــض األدراج‬      ‫الصيدليــة ميــارس البيــع وأفــاد بفقــد الــدرج كامـ ً‬\n      ‫ولــم يتضــح آثــار عنــف أو تكســير على باب الزجــاج اخلارجي والكيلون‬\n      ‫مقفــل وباالطــاع علــى محضــر االنتقــال واملعاينــة املعــد مــن قبــل رجــل‬\n      ‫الضبــط اجلنائــي املختــص بتاريــخ ‪1428/2/8‬ه ـ املتضمــن انــه عنــد‬\n      ‫الســاعة التاســعة مت اإلنتقــال إلــى صيدليــة (‪ ).....‬الواقعــة بالـ ـ (‪).....‬‬\n      ‫والتــي تبــن أن لهــا بــاب مــن احلديــد املســحوب علــى اخلــارج وبــاب زجاجــي‬\n      ‫وبهــا أدويــة مختلفــة ويف منتصفهــا طاولــة زجاجيــة الســتالم األدويــة مــن‬\n      ‫احملاســبني وخلفهــا طاولــة خشــبية وكرســي يســتخدمه احملاســب يف‬\n      ‫عملــه وتبــن أن البــاب اخلارجــي لــم يقفــل حــال اداء صــاة العشــاء وأقفــل‬\n      ‫البــاب الزجاجــي فقــط ولــم يظهــر بــه آثــار تكســير أو عنــف حيــث وجــد‬\n      ‫مفتــوح والقفــل خــارج مكانــه يف وضعيــة القفــل وقــد تعرضــت طاولــة‬\n      ‫احملاســبة للعبــث مبحتوياتهــا وفتــح األدراج اخلشــبية بخلعها من مكانها‬\n      ‫ولــم تكــن مقفلــة ولــم يعثــر علــى الدرج األوســط والذي به مبلــغ (‪)4500‬‬\n      ‫ريــال أربعــة اآلف وخمســمائة ريــال حســب قــول املبلــغ وباالطــاع علــى‬\n      ‫التقريــر الســري املعــد مــن قبــل البحــث اجلنائــي بتاريــخ ‪1433/3/8‬ه ـ‬\n      ‫املعــد عــن قضيــة ســرقة ســيارة مــن خلــف فــرع البنــك (‪ ).....‬بالـ ـ (‪).....‬‬\n      ‫واملتضمــن أن املدعــى عليــه األول ســيء الســلوك ومــن أربــاب الســوابق‬\n      ‫وقــد ســبق القبــض عليــه يف عــدة ســرقات حكــم فيهــا بالســجن ملــدة‬\n      ‫عامــن ولــه عالقــة باملدعــى عليــه الثانــي واملواطــن ‪ ).....( /‬وهــم برفقــة‬\n      ‫بعــض حتــى يف أوقــات متأخــرة مــن الليــل وقــد ســبق أن وجــه لهــم االتهــام‬\n      ‫يف قضايــا ســرقات وللثانــي بالتســتر عليــه يف ســرقة محــل جتــاري وأن‬\n      ‫املذكوريــن وكذلــك املواطــن ‪ ).....( /‬يتعاطــون احلبــوب احملظــورة‬\n      ‫واحلشــيش املخــدر والعــرق املســكر ويضطــرون للســرقة لعــدم وجــود‬\n\n\n‫‪397‬‬\n\f‫مصــادر دخــل ثابتــة وباالطــاع علــى محضــر تنفيــذ مهمــة رقــم (‪).....‬‬\n‫وتاريــخ ‪1429/3/23‬ه ـ واملعــد مــن قبــل إحــدى فــرق الدوريــات األمنيــة‬\n‫بالباحــة واملتضمــن انــه ورد بــاغ لغرفــة العمليــات مــن املبلــغ‪).....( /‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬مديــر مدرســة بالـ ـ‬\n‫(‪ ).....‬عــن ســرقة املدرســة وباالنتقــال اتضــح وجــود بعــض الكســر يف‬\n‫بــاب املقصــف والبــاب الداخلــي ووجــد البــاب اخللفــي غيــر مؤمــن ووجــد‬\n‫آثــار إطــار ســيارة وفقــد أنبــوب غازوباالنتقــال واملعاينــة مــن قبــل رجــل‬\n‫الضبــط اجلنائــي املختــص إلى مدرســة بال ـ (‪ ).....‬االثنــن ‪1429/3/23‬هـ‬\n‫الســاعه (‪ )8.00‬صباحـ ًا تبــن أنهــا تقــع يف (‪ ).....‬وهــي مدرســة متوســطة‬\n‫وإبتدائيــة ثــاث أدوار وتبعــد عــن الشــارع العــام حوالــي (‪ )2‬اثنــن كيلــو‬\n‫متــر محاطــه بســور مــن جميــع اجلهــات ولهــا مدخــل رســمي مــن اجلهــة‬\n‫الشــمالية ومدخــل فرعــي مــن اجلهــة اجلنوبيــة ومــن اجلهــة الشــرقية فنــاء‬\n‫مكشــوف وغيــر أمــن وميكــن الوصــول لداخــل املدرســة بســهولة‬\n‫وباملعاينــة الداخليــة تبــن أن اجلانــي اســتخدم ســيارة وأوقفهــا يف اجلهــة‬\n‫اجلنوبيــة وصعــد مــن جهــة الســور اخللفــي والنــزول إلــى جــوار املقصــف‬\n‫الواقــع بالفنــاء واجتــه إلــى البــاب الفرعــي الــذي يدخــل إلــى داخــل‬\n‫املدرســة وكســر الزجــاج وفتــح القفــل العلــوي ودفــع البــاب ودخــل‬\n‫املطبــخ وســرقة إســطوانتني وكســر بــاب املقصــف وســرق منــه مــواد‬\n‫غذائيــة (بســكويتات) وفتــح البــاب اخللفــي للمدرســة بآلــة حديديــة‬\n‫وأخــرج منهاإلســطوانات وتركــه مفتــوح ووجــد آثــار دخــول شــخص‬\n‫ا‬‫حــايف وغيــر واضحــة لكثــرة األتربــة ومت تصويــر املوقــع كام ـ ً‬\n‫وباالطــاع علــى محضــر تنفيــذ مهمــة رقــم ‪ 854‬وتاريــخ ‪1433/2/17‬ه ـ‬\n‫واملعــد مــن قبــل إحــدى فــرق الدوريــات األمنيــة بالباحــة واملتضمــن أن‬\n\n\n                                                                                    ‫‪398‬‬\n\f      ‫غرفــة العمليــات تلقــت بالغ ـ ًا مــن قبــل املبلــغ‪ ).....( /‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ ).....‬عــن ســرقة منزلــه وباالنتقــال إلــى‬\n      ‫املوقــع الكائــن بـ ــ(‪ ).....‬تبــن أن الســرقة كانــت مــن داخــل عمــارة‬\n      ‫مكونــه مــن أربعــة أدوار حتــت االنشــاء اليوجــد بهــا أبــواب داخليــة‬\n      ‫للغــرف ولهــا بــاب شــبك حديــد مقفــل بقفــل مت كســره وســرقة مجموعة‬\n      ‫مــن األســاك وأدوات ســباكة وســحب أســاك كهربائيــة مــن جــدار‬\n      ‫العمــارة وباالنتقــال واملعاينــة مــن قبــل رجــل الضبــط اجلنائــي املختــص‬\n      ‫إلــى العمــارة التــى حتــت االنشــاء يــوم االربعــاء ‪1433/2/17‬ه ـ عنــد‬\n      ‫الســاعة (‪ )10‬صباح ـ ًا تبــن أنهــا مكونــة مــن أربــع أدوار ب ـ (‪ ).....‬تبعــد‬\n      ‫عــن الطريــق العــام (‪ )100‬مائــة متــر تقريب ـ ًا وال يوجــد بداخلهــا أبــواب‬\n      ‫ومبعاينــة الغرفــة التــي ســرق منهــا محتوياتهــا تبــن أنهــا بالــدور الثانــي‬\n      ‫ومقفلــة ببــاب حديــدي مــن نــوع شــبك وبــه قفــل وكان القفــل مكســور‬\n      ‫وبهــا أدوات ســباكه وأدوات كهربائيــة ويتضــح أن اجلانــي دخــل مــن‬\n      ‫البــاب الرئيــس حيــث ال يوجــد أبــواب خارجيــة وال ســور للعمــارة‬\n      ‫وباالطــاع علــى محضــر اإلرشــاد ملــكان املســروقات (الكيابــل‬\n      ‫الكهربائيــة ) املــؤرخ يف ‪1433/2/10‬ه ـ وبحضــور املدعــى عليــه األول‬\n      ‫الــدال علــى مكانهــا تبــن أنهــا تقــع بـ ـ ــ(‪ ).....‬بــأرض زراعيــة بجــوار‬\n      ‫ورشــة عائــدة لوالــد املدعــى عليــه الثانــي ولــم يتــم العثــور علــى شــيء مــن‬\n      ‫املســروقات األخــرى وعلــى بعــد (‪ )100‬مائــة متــر تقريب ـ َا عثــر علــى‬\n      ‫بكرتــن ســوداء اللــون ألســاك كهربائيــة خاليــة وثالثــة كراتــن‬\n      ‫تخــص تلــك البكــرات وباالطــاع علــى محضــر تنفيــذ مهمــة رقــم(‪)959‬‬\n      ‫وتاريــخ ‪1433/2/22‬ه ـ واملعــد مــن قبــل إحــدى فــرق الدوريــات األمنيــة‬\n      ‫بالباحــة واملتضمــن انــه يف يــوم الثالثــاء ‪1433/2/23‬ه ـ ورد بــاغ لغرفــة‬\n\n\n‫‪399‬‬\n\f‫العمليــات مــن قبــل ضابــط خفــر شــرطة املدينــة مفــاده ســرقة ســياره‬\n‫للمواطــن ‪ ).....( /‬مــن نــوع (‪ ).....‬الصنــع (‪).....‬م رقــم اللوحــة (‪ ).....‬اللــون‬\n‫(‪ ).....‬وقــد مت العثورعليهــا امــام مركــز (‪ ).....‬بالـ ــ(‪ ).....‬ومفتوحــة‬\n‫األبــواب والــدرج وبداخلهــا عبــث وباالطــاع علــى محضــر انتقــال‬\n‫ومعاينــة ليــوم الثالثــاء ‪1433/2/23‬ه ـ عنــد الســاعة ‪ 12/24‬بعــد‬\n‫منتصــف الليــل عثــر علــى الســيارة املســروقة مــن نــوع (‪ ).....‬الصنــع (‪).....‬‬\n‫م رقــم اللوحــة (‪ ).....‬يف مــكان بال ـ ــ(‪ ).....‬مقابل احملل التجاري لل ـ ــ(‪).....‬‬\n‫املســمى (‪ ).....‬وباالطــاع علــى محضــر تنفيــذ مهمــة رقــم (‪ ).....‬وتاريــخ‬\n‫‪1433/2/24‬ه ـ واملعــد مــن قبــل إحــدى فــرق الدوريــات األمنيــة بالباحــة‬\n‫واملتضمــن انــه ورد بــاغ لغرفــة العمليــات مــن الوافــد‪- ).....( /‬ميانــي‬\n‫اجلنســية ‪-‬مبوجــب رخصــة اإلقامــة رقــم (‪ ).....‬عــن تكســير زجــاج‬\n‫مركــز (‪ ).....‬وفقــد الكاشــير وبداخلــه (‪ )1000‬الــف ريــال وباالنتقــال‬\n‫ملســرح اجلرميــة عثــر علــى األداة املســتخدمة يف اجلرميــة وجهــاز الكاشــير‬\n‫مرمــي خلــف املركــز وال يوجــد علــى زجــاج املركــز حاجــز حديــدي‬\n‫وباالطــاع علــى محضــر تنفيــذ مهمة رقم (‪ )1144‬وتاريخ ‪1433/3/5‬هـ‬\n‫املعــد مــن قبــل إحــدى فــرق الدوريــات األمنيــة بالباحــة واملتضمــن أنــه ورد‬\n‫بــاغ إلحــدى الدوريــات مــن قبــل الوافــد ‪ ).....( /‬عــن ســرقة ســيارة‬\n‫كفيلــه مــن نــوع (‪ ).....‬رقــم اللوحــة (‪ ).....‬الصنــع (‪ ).....‬بعــد أن أوقفهــا‬\n‫خلــف البنــك (‪ ).....‬بالباح ـ ًة بعــد صــاة الظهــر وعنــد الســاعة احلاديــة‬\n‫ـاء مــن نفــس اليــوم لــم يجدهــا مكانهــا وبالبحــث والتحــري‬          ‫عشــر مسـ ً‬\n‫مــن قبــل اجلهــات املختصة مت مشــاهدة الســيارة من قبــل أحدى الدوريات‬\n‫فتــم إســتيقاف قائدهــا املدعــى عليــه األول ومعــه ثــاث نســاء فتــم‬\n‫القبــض عليــه وأفــاد بــأن الســيارة طلبهــا مــن شــخص يدعــى ‪).....( /‬‬\n\n\n                                                                                         ‫‪400‬‬\n\f      ‫تعــرف عليــه منــذ ثالثــة أشــهر وال يعــرف عنــه أي معلومــات وباالطــاع‬\n      ‫علــى محضــر تنفيــذ مهمــة رقــم ‪ ......‬واملعــد مــن قبــل إحــدى فــرق‬\n      ‫الدوريــات األمنيــة بالباحــة املتضمــن أنــه بتاريــخ ‪1433/3/10‬ه ـ وعنــد‬\n      ‫الســاعة (‪ )9.30‬صباحــا مت االشــتباه يف ســيارة مــن نــوع (‪ ).....‬اللــون‬\n      ‫(‪ ).....‬الصنــع (‪).....‬م رقــم اللوحــة (‪ ).....‬يف ســوق الـ ـ ــ(‪ ).....‬متوقفــة بــدون‬\n      ‫لوحــة أماميــة وبحضــور صاحبهــا املدعــى عليــه الثانــي تبــن أنــه ال يوجــد‬\n      ‫لديــه إثبــات وقــد كان يف حالــة ارتبــاك وبســؤاله عــن أســباب عــدم‬\n      ‫وجــود لوحــة أماميــة أفــاد بأنــه أنزلهــا يف منزلــه وباالطــاع علــى محضــر‬\n      ‫تنفيــذ مهمــة رقــم (‪ )3236‬وتاريــخ ‪1432/8/22‬ه ـ املعــد مــن قبــل إحــدى‬\n      ‫فــرق الدوريــات األمنيــة بالباحــة املتضمــن انــه عنــد الســاعة (‪)9.15‬‬\n      ‫مســاء ورد بــاغ لغرفــة العمليــات مــن املبلــغ ‪ - ).....( /‬مصــري اجلنســية‬\n      ‫متضمــن ســرقة صيدليــة (‪ ).....‬الواقعــة بالقــرب مــن (‪ ).....‬وباالنتقــال‬\n      ‫أفــاد بســرقة مبلــغ (‪ )3000‬ثالثــة اآلف ريــال مــن الصيدليــة وقــت صــاة‬\n      ‫العشــاء ولــم تكــن مقفلــة بالســياج احلديــد وتبــن أن قفــل البــاب‬\n      ‫الزجاجــي مفتــوح وعثــر داخــل درج املكتبعلــى محفظــة تعــود للمبلــغ‬\n      ‫وبداخلهــا مبلــغ (‪ )200‬مائتــا ريــال ومبلــغ (‪ )203‬مائتــان وثالثــة ريــال يف‬\n      ‫درج آخــر وباالنتقــال واملعاينــة مــن قبــل رجــل الضبــط اجلنائــي املختــص‬\n      ‫بتاريــخ ‪1432/8/22‬ه ـ عنــد الســاعة (‪ )9.40‬لصيدليــة (‪ ).....‬تبــن أنهــا‬\n      ‫تقــع بجــوار (‪ ).....‬وأن البــاب احلديــدي مفتــوح وكان البــاب الزجاجــي‬\n      ‫مقفــل وقــت صــاة العشــاء حســب قــول املبلــغ ولوحــظ آثر بســيط حملاولة‬\n      ‫فتــح البــاب الزجاجــي وبداخلهــا لــم يالحــظ آثــر عنــف وكان درج‬\n      ‫املكتــب للمحاســب مفتــوح وباإلطــاع علــى بــاغ املواطــن ‪).....( /‬‬\n      ‫واملقــدم لرجــل الضبــط اجلنائــي املختــص بشــرطة مدينــة الباحــة بتاريــخ‬\n\n\n‫‪401‬‬\n\f‫‪1432/8/11‬ه ـ املتضمــن أن املدعــى عليــه األول ‪ ).....( /‬قــام بتهديــده‬\n‫بالقتــل وباالطــاع علــى محضــر تنفيــذ مهمــة رقــم (‪ )601‬وتاريــخ‬\n‫‪1433/2/5‬ه ـ املعــد مــن قبــل إحــدى فــرق الدوريــات األمنيــة املتضمــن‬\n‫أنــه عنــد الســاعة ‪ 12.30‬بعــد منتصــف الليــل مــن يــوم اجلمعــة ورد بــاغ‬\n‫مــن املبلــغ (‪ ).....‬مفــاده قيــام الثانــي‪ ).....( :‬مبضايقتــه بســيارته أثنــاء‬\n‫قيــادة الســيارة ومعــه عائلتــه ‪ ،‬وكان املدعــى عليــه يقــود ســيارة مــن نــوع‬\n‫ـاء علــى التقريــر‬‫(‪ ).....‬رقــم اللوحــة (‪ ).....‬وقــد مت القبــض عليهــم بنـ ً‬\n‫الســري واملعــد مــن قبــل الباحــث اجلنائــي بتاريــخ ‪1433/3/8‬ه ـ وبســماع‬\n‫أقــوال املدعــى عليــه األول‪ ).....( /‬أقــر بســرقة محافــظ عاملــن أثنــاء‬\n‫نومهمــا يف مســكنهما وكان بهــا (‪ )5000‬خمســة آالف ريــال وجهــاز‬\n‫جــوال مــن نــوع (‪ ).....‬وســرقة مبلــغ (‪ )3000‬ثالثــة اآلف ريــال من صيدلية‬\n‫(‪ ).....‬وذلــك بالدخــول مــن فتحــة صغيــرة للصيدليــة وســرقة ســيارة مــن‬\n‫نــوع (‪ ).....‬مــن الشــارع العــام ويشــاركه يف جميــع تلــك الســرقات احلــدث‬\n‫‪ ).....( /‬وســرقة أســاك كهربائيــة مــن عمــارة أحــد املواطنــن‬\n‫ومبشــاركة مــن املدعــى عليــه الثانــي واحلــدث ‪ ).....( /‬وســرقة ثــاث‬\n‫أنبوبــات غــاز ومــواد غذائيــة مــن داخــل مدرســة بال ـ ــ(‪ ).....‬وذلــك بالقفــز‬\n‫علــى ســور املدرســة ويشــاركه يف ذلــك املدعــى عليــه الثانــي واحلــدث‬\n‫(‪ ).....‬وسرقة جهازين جوال من إسكانات عمال بال ـ ـ ــ(‪ ).....‬ويشاركه‬\n‫يف ذلــك املدعــى عليــه الثانــي واحلــدث (‪ ).....‬وبســماع أقــوال الثانــي‬\n‫أنكــر جرميــة الســرقة وبســماع أقــوال احلــدث‪ ).....( /‬أنكــر جرميــة‬\n‫الســرقة وباســتجواب املدعــى عليــه األول ومواجهتــه بالتهمــة املنســوبة‬\n‫إليــه اقــر بســرقة مركــز (‪ ).....‬وكيابــل كهربائيــة مــن منــزل أحــد‬\n‫املواطنــن بال ـ ــ(‪ ).....‬وســرقة ســيارة مــن نــوع (‪ ).....‬وســرقة مدرســة‬\n\n\n                                                                                       ‫‪402‬‬\n\f      ‫بال ـ ــ(‪ ).....‬االبتدائية واملتوســطة وصيدلية (‪ ).....‬بالـ ــ(‪ ).....‬وســرقة مبالغ‬\n      ‫ماليــة مــن إســكان عمالــه وتهديــد مواطــن بالقتــل وباســتجواب املدعــى‬\n      ‫عليــه الثانــي ومواجهتــه بالتهمــة املنســوبة إليــه أنكــر مشــاركته يف‬\n      ‫الســرقات وأقــر بانحــراف ســيارته علــى مواطــن وهــو يقودهــا مــرار ًا‬\n      ‫بــدون قصــد منــه لكونهــا عطالنــه وبإعــادة اســتجوابه ومواجهتــه‬\n      ‫بتقريــر األدلــة اجلنائيــة املطابــق لألمنــاط الوراثيــة لــه واملرفــوع مــن مســرح‬\n      ‫اجلرميــة أصــر علــى إنــكاره الســابق وباملواجهــة بــن املدعــى عليــه األول‬\n      ‫والثانــي ظهــر علــى األول الهــدوء وعــدم االرتبــاك وظهــر علــى الثانــي‬\n      ‫االنفعــال وباملواجهــة بــن املدعــى عليــه األول والثانــي واحلــدث ‪).....( /‬‬\n      ‫أصــر كل منهــم علــى أقوالــه الســابقة وقــد ظهــر علــى املدعــى عليــه‬\n      ‫األول اخلــوف وعلــل ذلــك بأنــه يخشــى مــن ضربــه مــن قبــل املدعــى عليــه‬\n      ‫الثانــي و(‪ ).....‬وظهــر مــن املدعــى عليــه الثالــث رفــع الصــوت واالنفعــال‬\n      ‫مــن املدعــى عليــه األول وظهــر علــى ‪ ).....( /‬البــكاء وعلــل ذلك بخشــيته‬\n      ‫علــى مســتقبله ووالدتــه وبســماع شــهادة املواطــن ‪ ).....( /‬مــن أهالــي‬\n      ‫(‪ ).....‬يبلــغ مــن العمــر ‪ 19‬عام ـ ًا جــاء فيهــا ( انــه عنــد الســاعة ‪11.25‬‬\n      ‫مســاء تقابــل مــع املدعــى عليــه األول وطلــب منــه قــادح ( والعــة ) وســأله‬\n      ‫عــن ‪().....( /‬املبلــغ )وقــال لــه ملــاذا يتكلــم علــى أمه وأقســم بــاهلل ليذبحه‬\n      ‫باملســدس يربيــه وطلبــه رقــم جــوال ‪ ).....( /‬وأعطــاه إيــاه وعنــد مقابلــة‬\n      ‫الشــاهد ‪ ).....( /‬ظهــر لــه أنــه هاتفــه املدعــى عليــه األول علــى اجلــوال‬\n      ‫وباالطــاع علــى جهــاز جــوال املواطــن ‪ ).....( /‬تبــن أنــه مــن نــوع (‪).....‬‬\n      ‫وبــه مكاملــة لــم يــرد عليهــا مــن الرقــم (‪ ).....‬بتاريــخ (‪2011/7/12‬م)‬\n      ‫ـاء ومكاملــة مســتلمه مــن نفــس الرقــم بتاريــخ‬        ‫الوقــت ‪ 11.49‬مسـ ً‬\n      ‫ـاء مــدة املكاملــة ‪ 1.15‬دقيقــة وقــد‬   ‫‪2011/7/12‬م الوقــت ‪ 11.50‬مسـ ً‬\n\n‫‪403‬‬\n\f‫أثبــت التقريــر رقــم (‪ /533‬فحــوص وراثية‪1433/‬ه ـ أن عينــة الــدم‬\n‫القياســية للمتهــم األول تطابــق األمنــاط الوراثيــة املرفوعــة مــن مســرح‬\n‫جرميــة ســرقة مركــز الباحــة مــول وقــد أثبــت التقريــر رقــم ‪/576‬‬\n‫فحــوص وراثيــة ‪1433/‬ه ـ أن عينــة الــدم القياســية للمتهــم الثانــي تطابــق‬\n‫األمنــاط الوراثيــة املرفوعــة مــن مســرح جرميــة ســرقة مركــز (‪( ).....‬وقــد‬\n‫صــدر للحــدث‪ ).....( /‬أمــر حفــظ دعــوى اســتنادا للمــادة (‪ )124‬من نظام‬\n‫اإلجــراءات اجلزائيــة حيــال جرميــة ســرقة محــات جتاريــة ) وقــد انتهــى‬\n‫التحقيــق إلــى توجيــه االتهــام لــكل مــن ‪ ).....( -2 ).....( -1:‬باالشــتراك‬\n‫يف جرميــة ســرقة صيدليتــي (‪ ).....‬ومحتويــات كهربائيــة مــن عمــارة‬\n‫مواطــن حتــت اإلنشــاء ومحتويــات مقصــف مدرســة بنــن ب ـ (‪).....‬‬\n‫ومركــز (‪ ).....‬ومبالــغ ماليــة و(‪ )3‬ثــاث أجهــزة جــوال من مقر إســكان‬\n‫العمــال وتهديــد األول ملواطــن بالقتــل وســرقة ســيارة مــن نــوع (‪).....‬‬\n‫ومضايقــة الثانــي بســيارته ملواطــن بالطريــق العــام وإخافتــه يف ســاعة‬\n‫متأخــرة مــن الليــل وبرفقتــه عائلتــه وتعاطــي احلبــوب احملظــورة وذلــك‬\n‫لألدلــة والقرائــن التاليــة‪ -1:‬اعتــراف األول املنــوه عنــه املــدون (ص ‪)3-1‬‬\n‫مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪ )133‬وص (‪2‬ـ‪ )5‬مــن دفتــر ملــف‬\n‫إجــراءات االســتدالل لفــة(‪ -2 .)111‬اعتــراف الثانــي املنــوه عنــه املــدون‬\n‫(ص ‪ )13-12‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪( )251‬ص‪ )5-4‬لفــة‬\n‫(‪ )133‬و(ص‪ )4-3‬لفــة (‪-3 )134‬التقريــر رقــم (‪ /533‬فحــوص وراثيــة‬\n‫‪1433‬هــ) للمتهــم األول املنــوه عنــه املرفــق لفــة رقــم (‪-4 )361-357‬‬\n‫التقريــر رقــم (‪/576‬فحــوص وراثيــة ‪1433 /‬هــ) للمتهــم الثانــي املنــوه‬\n‫عنــه املرفــق لفــة رقــم (‪ -5 )347-343‬محضــر تنفيــذ مهمــة رقــم (‪)374‬‬\n‫املنــوه عنــه املرفــق لفــة رقــم (‪ -6 )12‬التقريــر اجلنائــي املصــور رقــم‬\n\n\n                                                                                   ‫‪404‬‬\n\f      ‫(‪1428/37‬هــ) لفــة رقــم (‪-7 )2‬محضــر االنتقــال واملعاينــة املنــوه عنــه‬\n      ‫املــدون (ص‪ )2‬مــن دفتــر تنظيــم محاضــر التحقيــق اجلنائــي لفــة رقــم (‪)1‬‬\n      ‫‪-8‬التقريــر الســري املنــوه عنــه املرفــق لفــة (‪ -9 )48‬محضــر تنفيــذ مهمــة‬\n      ‫رقــم (‪ )2134‬املنــوه عنــه املرفــق لفــة رقــم (‪-10 )58‬التقريــر اجلنائــي‬\n      ‫املصــور رقــم ‪1429/115‬ه ـ املرفــق لفــة رقــم (‪ -11 )52-50‬محضــر‬\n      ‫االنتقــال واملعاينــة ملدرســة بالـ ــ(‪ ).....‬املنــوه عنــه املــدون (ص‪ )5‬مــن دفتــر‬\n      ‫تقريــر املــوال املنيــة املوحــد لفــة رقــم (‪ -12 )55‬محضــر تنفيــذ مهمــة رقــم‬\n      ‫(‪ )854‬املنــوه عنــه املرفــق لفــة رقــم (‪ -13 )73‬محضــر االنتقــال واملعاينــة‬\n      ‫ملبنــى املواطــن حتــت اإلنشــاء واملــدون (ص‪ )3-2‬من دفتــر تقرير األحوال‬\n      ‫األمنيــة املوحــد لفــة رقــم (‪ -14 )72‬التقريــر اجلنائــي املصــور رقــم‬\n      ‫‪ 1433/96‬املرفــق لفــة رقــم (‪ -15 )80-74‬محضــر تنفيــذ مهمــة رقــم‬\n      ‫(‪ )959‬واملنــوه عنــه املرفــق لفــة رقــم (‪ -16)90‬التقريــر اجلنائــي املصــور‬\n      ‫رقــم ‪1433/81‬ه ـ املرفــق لفــة (‪-17 )95-91‬محضــر االنتقــال واملعاينــة‬\n      ‫للســيارة مــن نــوع (‪ ).....‬لفــة رقــم (‪ -18 )96‬محضــر تنفيــذ املهمــة رقــم‬\n      ‫(‪ )975‬املنــوه عنــه املرفــق لفــة رقــم (‪ -19 )101‬التقريــر اجلنائــي املصــور‬\n      ‫رقــم ‪1433/8‬ه ـ املرفــق لفــة رقــم (‪ -20)194-187‬محضــر تنفيــذ مهمــة‬\n      ‫رقــم (‪ )32 ، 36‬املنــوه عنــه املرفــق لفــة رقــم (‪ -21 )144‬محضر االنتقال‬\n      ‫واملعاينــة لصيدليــة (‪ ).....‬واملدونــة (ص‪ )3-2‬لفــه(‪ -22)141‬التقريــر‬\n      ‫اجلنائــي املصــور رقــم ‪1432/275‬ه ـ املرفــق لفــة رقــم (‪-23 )153-148‬‬\n      ‫التقريــر اجلنائــي املصــور رقــم ‪1432/98‬ه ـ املرفــق لفــة رقــم (‪)201-197‬‬\n      ‫‪ -24‬محضــر تنفيــذ مهمــة رقــم (‪ )1209‬املنــوه عنــه املرفــق لفــة رقــم‬\n      ‫(‪ -25 )114‬محضــر الداللــة علــى مــكان املســروقات ( الكيابــل‬\n      ‫الكهربائيــة ) املــدون (ص‪ )8‬مــن دفتــر ملــف اجــراءات االســتدالل لفــة‬\n\n\n‫‪405‬‬\n\f‫رقــم (‪ -26 )112‬محضــر البــاغ عــن تهديــد مواطــن املنــوه عنــه املــدون‬\n‫(ص‪ )1‬مــن دفتــر ملــف إجــراءات االســتدالل رقــم (‪ -27 )224‬محضــر‬\n‫تفريــغ ســجل جهــاز جــوال ملكاملــات واردة واملــدون ص(‪ )5‬مــن دفتــر‬\n‫ملــف إجــراءات االســتدالل رقــم (‪ -28 )224‬محضــر املواجهــة واملــدون‬\n‫ص (‪ )6‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪ )133‬وص (‪ )5‬مــن دفتــر‬\n‫التحقيــق املرفــق لفــه رقــم (‪ )134‬و(ص‪ )7‬لفــه (‪ )112‬وبالبحــث عــن‬\n‫ســوابقهما لــم يعثــر لهمــا علــى ســوابق وحيــث إن مــا اقــدم عليــه‬\n‫املذكــوران وهمــا بكامــل أهليتهمــا املعتبــر شــرع ًا فعــل محــرم ومعاقب‬\n‫عليــه شــرعا ونظام ـ ًا وهــو ســرقة أمــوال محترمــة مــن حرزهــا بعــد‬\n‫هتكهــا تزيــد عــن النصــاب ال شــبهة لهمــا فيهــا ولكــون اجلانيــان‬\n‫مكلفــان غيــر مكرهــان ممــا يتعــن معــه إحالتهمــا للمحكمــة العامــة‬\n‫اســتناد ًا للمادتــن ( ‪ )129-126‬مــن نظــام اإلجــراءات اجلزائيــة إلثبــات‬\n‫مــا أســند إليهمــا واحلكــم عليهمــا بحــد الســرقة الــوارد يف اآليــة‬\n‫الكرميــة رقــم (‪ )38‬مــن ســورة املائــدة واحلكــم علــى األول بعقوبــة‬\n‫تعزيريــة لقــاء تهديــده ملواطــن بالقتــل وعلــى الثانــي بعقوبــة تعزيريــة لقــاء‬\n‫مضايقتــه ملواطــن بســيارته مــرار ًا وإخافتــه وبرفقتــه عائلتــه وال زال احلــق‬\n‫اخلــاص قائــم جلميــع املدعــن مــا عــدا املدعــي مبضايقــة ســيارة املدعــى‬\n‫عليــه الثانــي لــه فقــد تنــازل عــن حقــه اخلــاص وبــاهلل التوفيــق هكــذا‬\n‫ادعــى وبعــرض مــا جــاء يف دعــوى املدعــي العــام علــى املدعــى عليهمــا‬\n‫أجــاب املدعــي عليــه األول (‪ ).....‬قائــا مــا ذكــره املدعــي العــام مــن‬\n‫اتهامــي باالشــتراك يف ســرقة صيدليتــي (‪ ).....‬ومحتويــات كهربائيــة‬\n‫مــن عمــارة مواطــن حتــت اإلنشــاء ومحتويــات مقصــف مدرســة بنــن‬\n‫بـ ـ ــ(‪ ).....‬ومركــز (‪ ).....‬ومبالــغ ماليــة و(‪ )3‬ثــاث أجهــزة جــوال مــن مقــر‬\n\n\n                                                                                        ‫‪406‬‬\n\f      ‫إســكان العمــال وتهديــد مواطــن بالقتــل وســرقة ســيارة مــن نــوع (‪).....‬‬\n      ‫كلــه غيــر صحيــح عــدا ســرقة الســيارة فأنــا لــم أســرقها وإمنــا اتصلــت‬\n      ‫بــي والدتــي وهــي مريضــة بالقلــب وكنــت علــى الشــارع العــام عنــد‬\n      ‫مطعــم (‪ ).....‬وليــس معــي ســيارة فوجــدت ســيارة مــن نــوع (‪ ).....‬موديــل‬\n      ‫عــام (‪).....‬م مفتوحــة وعليهــا املفتــاح فأخذتهــا وأوصلــت أمــي ملستشــفى‬\n      ‫(‪ ).....‬وأمــا التهديــد بالقتــل للمدعــو (‪ ).....‬فغيــر صحيــح وإمنــا تلفظــت‬\n      ‫عليــه بألفــاظ نابيــة ألنــه تلفــظ علــي وقــد انتهــت القضيــة بيننــا بالتنــازل‬\n      ‫هــذه إجابتــي و أجــاب املدعــى عليــه الثانــي (‪ ).....‬قائــا مــا ذكــره‬\n      ‫املدعــي العــام مــن اتهامــي باالشــتراك يف ســرقة صيدليتــي (‪).....‬‬\n      ‫ومحتويــات كهربائيــة مــن عمــارة مواطــن حتــت اإلنشــاء ومحتويــات‬\n      ‫مقصــف مدرســة بنــن بـ ـ ــ(‪ ).....‬ومركــز (‪ ).....‬ومبالــغ ماليــة و(‪ )3‬ثــاث‬\n      ‫أجهــزة جــوال مــن مقــر إســكان العمــال ومضايقــة مواطــن بســيارتي يف‬\n      ‫الطريــق العــام يف ســاعة متأخــرة مــن الليــل وتعاطــي احلبــوب احملظــورة‬\n      ‫كلــه غيــر صحيــح أمــا مــا ذكــره مــن أننــي قمــت مبضايقــة أحــد‬\n      ‫األشــخاص بســيارتي فهــذا كان بســبب أن ســيارتي كانــت غيــر‬\n      ‫موزونــة األذرعــة وانحرفــت باخلطــأ إلــى هــذا الشــخص وقــد تنــازل عــن‬\n      ‫دعــواه بالشــرطة هكــذا أجــاب وبســؤال املدعــي العــام هــل لديــك بينــة‬\n      ‫علــى مــا جــاء بالدعــوى أجــاب قائــا لــدي مــا يف أوراق املعاملــة أطلــب‬\n      ‫الرجــوع إليهــا هكــذا أجــاب ثــم رفعــت اجللســة للرجــوع إلــى أوراق‬\n      ‫املعاملــة واالطــاع عليهــا إلــى يــوم االثنــن املوافــق ‪1433/8/19‬ه ـ‬\n      ‫الســاعة العاشــرة ويف املوعــد احملــدد افتتحــت اجللســة وفيهــا حضــر‬\n      ‫املدعــي العــام (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪).....‬‬\n      ‫مبوجــب خطــاب التكليــف الــوارد إلينــا مــن رئيــس فــرع هيئــة التحقيــق‬\n\n\n‫‪407‬‬\n\f‫بالباحــة برقــم ه ـ ب ‪ 5830/2/1‬يف ‪1433/8/11‬ه ـ وأحضــر املدعــى‬\n‫عليهمــا ‪ ،‬هــذا وقــد وردنــا خطــاب احملقــق أول (‪ ).....‬املقيــد باحملكمــة‬\n‫برقــم ‪ 33/1510647‬يف ‪1433/8/11‬ه ـ املتضمــن أن املدعــي العــام‬\n‫(‪ ).....‬قــد قــام بتعديــل الئحــة الدعــوى للمدعــى عليهمــا يف هــذه الدعــوى‬\n‫وذلــك بتوجيــه االتهــام بتعاطــي احلبــوب احملظــورة للمدعــى عليــه األول‬\n‫وتعديــل الطلبــات بنــاء علــى ذلــك انتهــى مضمونــه وأرفــق بــه الئحــة‬\n‫الدعــوى املعدلــة كاملــة وبعــرض اخلطــاب والالئحــة املرفقــة بــه علــى‬\n‫املدعــي العــام احلاضــر صــادق علــى صحــة ذلــك وطلــب تعديــل الدعــوى ‪،‬‬\n‫وبنــاء علــى املــادة الســتون بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة قررنا‬\n‫اإلذن للمدعــي العــام بتعديــل دعــواه ‪ ،‬وبالطــاع علــى الالئحــة املعدلــة‬\n‫وجدناهــا تضمنــت تعديــل االتهــام املوجــه للمدعــى عليهمــا مبــا نصــه «‬\n‫أقــرر اتهــام كل مــن‪ ).....( -2 ).....(-1 :‬باالشــتراك يف جرميــة ســرقة‬\n‫صيدليتــي (‪ ).....‬ومحتويــات كهربائيــة مــن عمارة مواطن حتت اإلنشــاء‬\n‫ومحتويــات مقصــف مدرســة بنــن ب ـ ـ ــ(‪ ).....‬ومركــز (‪ ).....‬ومبالــغ ماليــة‬\n‫و(‪ )3‬ثــاث أجهــزة جــوال مــن مقــر إســكان العمــال وتهديــد األول‬\n‫ملواطــن بالقتــل وســرقة ســيارة مــن نــوع (‪ ).....‬وتعاطــي احلبــوب احملظــورة‬\n‫ومضايقــة الثانــي بســيارته ملواطــن بالطريــق العــام وإخافتــه يف ســاعة‬\n‫متأخــرة مــن الليــل وبرفقتــه عائلتــه « كمــا تضمــن يف الطلبــات مــا نصه‪:‬‬\n‫«احلكــم عليهمــا بحــد الســرقة الــوارد يف اآليــة الكرميــة رقــم (‪ )38‬مــن‬\n‫ســورة املائــدة واحلكــم علــى األول بعقوبــة تعزيريــة لقــاء تهديــده ملواطــن‬\n‫بالقتــل وبالســجن وفق ـ ًا للفقــرة (األولــى) مــن املــادة (احلاديــة واألربعــن)‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء تعاطيــه للحبــوب‬\n‫احملضــورة وعلــى الثانــي بعقوبــة تعزيريــة لقــاء مضايقتــه ملواطن بســيارته‬\n\n\n                                                                                          ‫‪408‬‬\n\f      ‫مــرار ًا وإخافتــه وبرفقتــه عائلتــه « انتهــى نصــه ‪ ،‬ثــم جــرى عــرض مــا‬\n      ‫جــاء يف الدعــوى العامــة بعــد تعديلهــا علــى املدعــى عليــه األول(‪).....‬‬\n      ‫وجــرى إفهامــه بأنــه مت توجيــه تهمــة تعاطــي احلبــوب احملظــورة إليــه‬\n      ‫فأجــاب قائــا مــا ذكــره املدعــي العــام مــن اتهامــي بتعاطــي احلبــوب‬\n      ‫احملظــورة غيــر صحيــح فلــم أتعاطــى احلبــوب احملظــورة وال غيرهــا‬\n      ‫هكــذا أجــاب وبســؤال املدعــي العــام عــن بيناتــه أجــاب قائــا ليــس‬\n      ‫لــدي ســوى مــا يف أوراق املعاملــة هكــذا أجــاب ثــم جــرى منــا الرجــوع‬\n      ‫إلــى أوراق املعاملــة لالطــاع عليهــا فوجدنــا بــن طياتهــا وعلــى الصفحــة‬\n      ‫رقــم ‪ 3-1‬مــن ملــف التحقيــق املرفــق رقــم ‪ 133‬محضــر اســتجواب‬\n      ‫للمدعــى عليــه األول (‪ ).....‬تضمــن إجابتــه مبــا نصــه « قمــت مبشــاركة‬\n      ‫ال مــن (‪ ).....‬و(‪ ).....‬بســرقة مركــز (‪ ).....‬بعــد كســر زجــاج احملــل‬   ‫ك ً‬\n      ‫اخلارجــي وقــد قمــت بأخــذ ثــاث جاكيتــات مــن احملــل وأمــا الكاشــير‬\n      ‫واملــال الــذي كان بــه فالــذي قــام بســرقته (‪ ).....‬و(‪ ).....‬وأنــا كان دوري‬\n      ‫املراقبــة اخلارجيــة بعــد مــا أخــذت اجلاكيتــات والعطــور ومالبــس داخليــة‬\n      ‫« انتهــى نصــه كمــا تضمــن أن جميــع املســروقات قــام بســرقتها‬\n      ‫باملشــاركة مــع (‪ ).....‬و (‪ ).....‬مــا عــدا ســرقة صيدليــة (‪ ).....‬فــكان معــه‬\n      ‫(‪ ).....‬فقــط كمــا تضمــن إقــراره بتعاطــي احلبوب احملظورة منذ شــهرين‬\n      ‫انتهــى مضمونــه وبعرضــه علــى املدعــى عليــه األول (‪ ).....‬صــادق علــى‬\n      ‫صــدوره منــه وعلــى وضــع بصمــة إبهامــه عليــه ثــم قــرر قائــا‪ :‬مــا جــاء‬\n      ‫فيــه غيــر صحيــح وذلــك ألننــي أجبــرت علــى اإلقــرار بذلــك هكــذا‬\n      ‫أجــاب فســألناه عــن ماهيــة اإلجبــار الــذي يدعيــه فأجــاب قائــا لقــد‬\n      ‫طلــب منــي احملقــق أن أقــر وأوقــع علــى اإلقــرار وأننــي ســأخرج مــن‬\n      ‫القضيــة هكــذا أجــاب ونظــرا النتهــاء وقــت اجللســة قررنــا رفــع اجللســة‬\n\n\n‫‪409‬‬\n\f‫الســتكمال االطــاع علــى أوراق املعاملــة إلــى يــوم األربعــاء املوافــق‬\n‫‪1433/8/28‬ه ـ الســاعة احلاديــة عشــرة ويف املوعــد احملــدد افتتحــت‬\n‫اجللســة وفيهــا حضــر املدعــي العــام واملدعــى عليهمــا ثــم جــرى منــا‬\n‫االطــاع علــى محضــر ســماع أقــوال املدعــى عليــه األول (‪ ).....‬املــدون‬\n‫علــى الصحيفــة رقــم ‪ 5-2‬مــن ملــف التحقيــق املرفــق باملعاملــة لفــة رقــم‬\n‫‪ 111‬فوجدنــاه تضمــن إقــراره بقيامــه بعــدة ســرقات وهــي كالتالــي ‪-1‬‬\n‫ســرقة محافــظ « حقيبــة جيــب « لعمالــة أجنبيــة مــن غــرف خاصــة بهــم‬\n‫وأن املبلــغ الــذي كان باحملفظــة الــذي أخذهــا قــدره خمســة آالف ريــال‬\n‫‪ -2‬ســرقة مبلــغ ثالثــة آالف ريــال مــن صيدليــة (‪ ).....‬الواقعــة قبــل إشــارة‬\n‫املستشــفى بال ـ ــ(‪ ).....‬باملشــاركة مــع املدعــو (‪ ).....‬وذلــك عــن طريــق‬\n‫الدخــول إلــى الصيدليــة مــن الشــباك الصغيــر الــذي كان مفتوح ـ ًا ‪-3‬‬\n‫ســرقة ســيارة مــن نــوع (‪ ).....‬كانــت متوقفــة علــى الشــارع العــام أمــام‬\n‫صيدليــة (‪ ).....‬ثــم التفحيــط عليهــا حتــى تعطلــت وتوقفــت علــى طريــق‬\n‫(‪ ).....‬وقــام بعدهــا بغســل الســيارة ومســحها مبــاء وصابــون حتــى يتــم‬\n‫إخفــاء البصمــات ‪ -4‬مشــاركته (‪ ).....‬و (‪ ).....‬يف ســرقة منــزل يف‬\n‫بالـ ـ ــ(‪ ).....‬وكان دوره املراقبــة ‪ -5‬مشــاركته للمدعــو (‪ ).....‬يف ســرقة‬\n‫مدرســة بال ـ ـ ــ(‪ ).....‬االبتدائيــة واملتوســطة مرتــن ‪ ،‬يف األولى قام بســرقة‬\n‫اســطوانات غــاز ومــواد غذائيــة يف املقصــف وأمــا الثانيــة فقــام بســرقة‬\n‫مواد غذائية فقط ‪ -6‬مشــاركته (‪ ).....‬و(‪ ).....‬يف ســرقة ســكن عمال‬\n‫بالـ ـ ــ(‪ ).....‬وكانــت املســروقات جهــاز جــوال (‪ ).....‬وجهــاز (‪ ).....‬ومبلــغ‬\n‫أربعمائــة ريــال «انتهــى مضمونــه وبعرضــه علــى املدعــى عليــه األول‬\n‫أنكــر صــدوره منــه وقــرر بقولــه لقــد مت تبصيمــي علــى هــذا اإلقــرار‬\n‫بالقــوة حيــث أمرنــي احملقــق بــأن أضــع بصمــة إبهامــي عليــه لكــي‬\n\n\n                                                                                     ‫‪410‬‬\n\f      ‫أخــرج مــن التوقيــف هكــذا قــرر ‪ ،‬كمــا جــرى االطالع على اســتجواب‬\n      ‫املدعــى عليــه الثانــي املــدون علــى الصحيفــة رقــم ‪ 5-4‬مــن ملــف التحقيق‬\n      ‫املرفــق باملعاملــة لفــة رقــم ‪ 133‬ومحضــر اســتجوابه املــدون علــى‬\n      ‫الصحيفــة رقــم ‪ 4-2‬مــن ملــف التحقيــق املرفــق باملعاملــة لفــة رقــم ‪134‬‬\n      ‫فوجدناهــا تضمنــت إنــكاره الســرقة انتهــى مضمونهــا كمــا جــرى‬\n      ‫االطــاع علــى ً التقريــر رقــم ‪ /533‬فحــوص وراثيــة ‪1433/‬ه ـ املرفــق‬\n      ‫باملعاملــة لفــة رقــم ‪ 361-357‬فوجدنــاه تضمــن تطابــق األمنــاط الوراثيــة‬\n      ‫لعينــة الــدم املأخــوذة مــن املدعــى عليــه (‪ ).....‬مــع األمنــاط الوراثيــة خلمــس‬\n      ‫عينــات لديهــم ممــا يثبــت أنــه هــو مصــدر تلــك اآلثــار احليويــة انتهــى‬\n      ‫مضمونــه وبعرضــه علــى املدعــى عليــه األول أجــاب قائــل مــا جــاء فيــه‬\n      ‫غيــر صحيــح هكــذا أجــاب كمــا جــرى االطــاع علــى التقريــر رقــم‬\n      ‫‪ /576‬فحــوص وراثيــة ‪1433/‬ه ـ املرفــق باملعاملــة لفــة رقــم ‪346-343‬‬\n      ‫فوجدنــاه تضمــن تطابــق األمنــاط الوراثيــة لعينــة الــدم املأخــوذة مــن‬\n      ‫املدعــى عليــه (‪ ).....‬مــع األمنــاط الوراثيــة لتســع عينــات لديهــم ممــا يثبــت‬\n      ‫أنــه هــو مصــدر تلــك اآلثــار وأن احتمــال وجــود شــخص آخــر لــه نفــس‬\n      ‫منــط هــذه املورثــات هــو ‪ 1‬إلــى ‪ 470‬ألــف تلريــون انتهــى مضمونه وبعرضه‬\n      ‫ا مــا جــاء يف التقريــر غيــر‬‫علــى املدعــى عليــه الثانــي (‪ ).....‬أجــاب قائ ـ ً‬\n      ‫صحيــح هكــذا أجــاب كمــا جــرى االطــاع علــى محضــر تنفيــذ مهمــة‬\n      ‫املرفــق باملعاملــة لفــة رقــم ‪ 12‬فوجدنــاه تضمــن الشــخوص للصيدليــة‬\n      ‫ووجــد املبلــغ عــن الســرقة فيهــا ولــم يوجــد أي آثــار عنــف أو تكســير‬\n      ‫علــى الزجــاج اخلارجــي وأن الكيلــون التابــع للزجــاج اخلارجــي مقفــل‬\n      ‫خــارج إطــار مجــراه انتهــى مضمونــه كمــا جــرى االطــاع علــى التقريــر‬\n      ‫اجلنائــي املصــور املرفــق باملعاملــة لفــة رقــم ‪ 2‬كمــا جــرى االطــاع علــى‬\n\n\n‫‪411‬‬\n\f‫محضــر االنتقــال واملعاينــة املــدون علــى الصحيفــة رقــم ‪ 2‬مــن امللــف رقــم‬\n‫‪ 1‬فوجدنــاه تضمــن معاينــة الصيدليــة وأن البــاب الزجاجــي الصغيــر‬\n‫مفتوح ـ ًا ولســان القفــل خــارج وأن طاولــة احملاســب مبعثــرة ولــم تكــن‬\n‫مقفلــة ولــم يعثــر علــى الــدرج األوســط انتهــى مضمونــه ثــم رفعــت اجللســة‬\n‫النتهــاء وقتهــا إلــى يــوم األثنــن املوافــق ‪1433/9/11‬ه ـ الســاعة احلاديــة‬\n‫عشــرة ويف املوعــد احملــدد افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫العــام‪ ......‬واملدعــى عليهمــا ويف هــذه اجللســة جــرى اســتكمال االطــاع‬\n‫علــى أوراق املعاملــة فجــرى منــا االطــاع علــى محضــر الداللــة علــى‬\n‫املســروقات املــؤرخ يف ‪1433/3/10‬ه ـ واملــدون علــى الصحيفــة رقــم ‪8‬‬\n‫مــن ملــف التحقيــق املرفــق باملعاملــة لفــة رقــم ‪ 112‬فوجدنــاه تضمــن أنــه‬\n‫بنــاء علــى اعتــراف املتهــم (‪ ).....‬بقيامــه بســرقة كيابــل كهربائيــة مــن‬\n‫منــزل (‪).....‬بـ ـ ــ(‪ ).....‬وأنهــم قامــوا بوضــع تلــك الكيابــل بجــوار منــزل‬\n‫(‪ ).....‬املذكــور بعــد تغطيتهــا بــاألوراق وقــام املتهــم بالداللــة علــى موقــع‬\n‫الكيابــل وباالنتقــال وتفتيــش املوقــع لــم يتــم العثــور علــى شــيء مــن‬\n‫املســروقات ووجــد بكرتــن ســوداء اللــون عائــدة ألســاك كهربائيــة‬\n‫وجــدت خاويــة انتهــى مضمونــه وبعرضــه علــى املدعــى عليــه األول أجــاب‬\n‫ا مــا جــاء يف احملضــر غيــر صحيــح فلــم أقــم بالداللــة علــى هــذا‬      ‫قائ ـ ً‬\n‫املوقــع وال غيــره وإمنــا خــرج احملقــق بــي إلــى هــذا املــكان وال أعلــم عنــه‬\n‫شــيئا هكــذا أجــاب ثــم جــرى االطــاع علــى صحيفــة ســوابق للمدعــى‬\n‫عليــه األول املرفــق باملعاملــة لفــة رقــم ‪ 283-281‬وعلــى اللفــة رقــم ‪-219‬‬\n‫‪ 221‬فوجدناهــا تضمنــت تســجيل ســابقة ســرقة محــات جتاريــة‬\n‫واحلكــم عليــه بالســجن ســنتني واجللــد مائتــي جلــدة ا‪.‬ه ـ وبعرضــه علــى‬\n‫املدعــى عليــه األول صــادق علــى صحــة الســابقة وأنــه قــد أخــذ‬\n\n\n                                                                                        ‫‪412‬‬\n\f      ‫محكوميتــه عليهــا وأضــاف قائــا إنــه حكــم علــي بالتهمــة ولــم تثبــت‬\n      ‫علــي الســرقة هكــذا قــرر وبالبحــث عــن صحيفــة ســوابق املدعــى عليــه‬\n      ‫الثانــي لــم جندهــا مرفقــة باملعاملــة ‪ ،‬وبســؤال املدعــى عليــه الثانــي عــن‬\n      ‫ســوابقه أجــاب بقولــه ليــس علــي ســوابق وقــد اتهمــت يف القضيــة التــي‬\n      ‫حكــم علــى املدعــى عليــه األول فيهــا ولكــن مت تبرئتــي ولــم يحكــم‬\n      ‫علــي بشــيء هكــذا أجــاب ‪ ،‬ثــم رفعــت اجللســة النتهــاء وقتهــا ويف يــوم‬\n      ‫االثنــن املوافــق ‪1433/12/27‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n      ‫العــام (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬مبوجب‬\n      ‫خطــاب التكليــف الــوارد إلينــا مــن رئيــس فــرع هيئــة التحقيــق بالباحــة‬\n      ‫برقــم ه ـ ب‪ 8399/2/1‬يف ‪1433/12/5‬ه ـ وحضــر املدعــى عليهمــا‬\n      ‫املفــرج عنهمــا بخطــاب فضيلــة رئيــس احملكمــة رقــم ‪ 332034198‬يف‬\n      ‫‪1433/11/16‬ه ـ ويف هــذه اجللســة جــرى اطــاع احلاضريــن علــى مــا‬\n      ‫ســبق ضبطــه وصادقــوا عليــه ‪ ،‬ثــم جــرى ســؤال املدعــي العــام واملدعــى‬\n      ‫عليهمــا إن كان لــدى أي منهــم إضافــة علــى مــا ســبق ضبطــه فقــرروا‬\n      ‫بقولهــم ليــس لدينــا ســوى مــا ســبق ضبطــه هكــذا قــرروا فقفلنــا بــاب‬\n      ‫املرافعــة وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى‬\n      ‫عليــه األول (‪ ).....‬أقــر بقيامــه بســرقة الســيارة املوصوفــة بالدعــوى مــن‬\n      ‫غيــر حرزهــا وأقــر بتلفظــه بألفــاظ نابيــة علــى أحــد األشــخاص وأنكــر‬\n      ‫مــا عــدا ذلــك ممــا جــاء يف دعــوى املدعــى العــام مــن الســرقات والتهديــد‬\n      ‫بالقتــل وتعاطــي احلبــوب احملظــورة ومبــا أن املدعــى عليــه الثانــي أنكــر‬\n      ‫جميــع مــا نســبه إليــه املدعــي العــام وأقــر مبضايقتــة بســيارته ألحــد‬\n      ‫األشــخاص ليــا مدعيــا أن ذلــك بســبب عطــل يف ســيارته ونظــرا إلــى أن‬\n      ‫مــا قدمــه املدعــي العــام مــن بينــات تعــد قرائــن تقــوي التهمة بحــق املدعى‬\n\n\n‫‪413‬‬\n\f‫عليهمــا مبــا نســب إليهمــا يف الســرقات وملــا جــاء يف إقــرار املدعــى عليــه‬\n‫األول لــدى جهــات التحقيــق واملــدون مضمونــه أعــاه واملتضمــن إقــراره‬\n‫بالســرقات الــواردة يف دعــوى املدعــى العــام إقــراره بتعاطــي احلبــوب‬\n‫احملظــورة وحيــث ال بينــة لــه علــى مــا ادعــاه مــن اإلكــراه عليهمــا ‪ ،‬وملــا‬\n‫قــرره أهــل العلــم ـ وحكــوه إجماعــا ـ مــن اشــتراط إخــراج الســارق‬\n‫املســروق مــن حــرز مثلــه إلقامــة احلــد عليــه اســتنادا لقولــه عليــه الصــاة‬\n‫والســام يف احلديــث الــذي رواه أبــو داود يف ســننه عــن عبــد اهلل بــن‬\n‫عمــرو بــن العــاص رضــي اهلل عنــه أن رســول اهلل صلــى اهلل عليــه وســلم‬\n‫ســئل عــن الثمــر فقــال ((مــن أصــاب بفيــه مــن ذي حاجــة ‪ ،‬غيــر متخــذ‬\n‫خبنــة ‪ ،‬فــا شــيء عليــه ‪ ،‬ومــن خــرج بشــيء منــه فعليــه غرامــة مثليــه‬\n‫والعقوبــة ‪ ،‬ومــن ســرق منــه شــيئا بعــد أن يؤويــه اجلريــن فبلــغ ثمــن املجــن‬\n‫فعليــه القطــع )) ‪ ،‬ونظــرا إلــى أن مــا توجهــت التهمــة بــه إلــى املدعــى‬\n‫عليهمــا عمــل محــرم شــرعا ومــن االعتــداء علــى األمــوال بغيــر حــق‬\n‫وإيــذاء للمســلمني‪ ،‬وقــد قــال عليــه الصــاة والســام ‪ ( :‬كل املســلم‬\n‫علــى املســلم حــرام دمــه ومالــه وعرضــه ) ‪ ،‬وقــال عليــه الصــاة والســام‬\n‫(( املســلم مــن ســلم املســلمون مــن لســانه ويــده )) ونظــرا إلــى أن املدعــى‬\n‫عليهمــا يســتحقان العقوبــة طبقــا للقواعــد الشــرعية ونظــرا إلــى أن‬\n‫تفــاوت األفعــال توجــب تفــاوت األحــكام ونظــرا لوجــود ســابقه للمدعــى‬\n‫عليــه األول يف جرميــة ســرقة األمــر الــذي يؤخــذ يف االعتبــار عنــد تقديــر‬\n‫العقوبــة ‪ ،‬ولــكل مــا تقــدم فقــد ثبــت لدينــا إدانــة املدعــى عليــه األول‬\n‫(‪ ).....‬بســرقته للســيارة املوصوفــة بالدعــوى مــن غيــر حرزهــا وإدانتــه‬\n‫بالتلفــظ بألفــاظ نابيــة علــى أحــد األشــخاص وتوجيــه التهمــة القويــة إليه‬\n‫باالشــتراك يف ســرقة احملــات املشــار إليهــا بدعــوى املدعــي العــام‬\n\n\n                                                                                       ‫‪414‬‬\n\f      ‫وتوجيــه التهمــة إليــه بتعاطــي احلبــوب احملظــورة كمــا توجهــت التهمــة‬\n      ‫للمدعــى عليــه الثانــي (‪ ).....‬باالشــتراك يف ســرقة احملــات املشــار إليهــا‬\n      ‫بالدعــوى ومضايقتــه ألحــد األشــخاص بواســطة ســيارته وحكمنــا مبــا‬\n      ‫يلــي‪ :‬أوال ‪ /‬درء إقامــة حــد الســرقة علــى املدعــى عليــه األول لعــدم‬\n      ‫اكتمــال شــروط إقامــة حــد الســرقة عليــه ‪ ،‬وصــرف النظــر عــن إقامــة‬\n      ‫حــد الســرقة علــى املدعــى عليــه الثانــي لعــدم ثبــوت موجبــه‪ .‬ثانيــا ‪/‬‬\n      ‫تعزيــر املدعــى عليــه األول (‪ ).....‬لقــاء إدانتــه بالســرقة مــن غيــر حــرز‬\n      ‫ولقــاء مــا توجهــت التهمــة إليــه وذلــك بســجنه مــدة ســنتني يحتســب منهــا‬\n      ‫مــدة إيقافــه بســبب هــذه القضيــة وجلــده أربعمائــة جلــدة مفرقــة علــى‬\n      ‫ثمــان دفعــات قــدر كل دفعــة خمســون جلــدة وبــن كل دفعــة وأخــرى‬\n      ‫عشــرة أيــام‪ .‬ثالثــا‪ /‬تعزيــر املدعــى عليــه الثانــي (‪ ).....‬لقــاء التهمة املوجهة‬\n      ‫إليــه وذلــك بســجنه مــدة تســعة أشــهر يحتســب منهــا مــدة إيقافــه بســبب‬\n      ‫هــذه القضيــة وجلــده مائتــي جلــدة مفرقــه علــى أربــع دفعــات قــدر كل‬\n      ‫دفعــة خمســون جلــدة وبــن كل دفعــة وأخــرى عشــرة أيــام وبعــرض‬\n      ‫احلكــم علــى املدعــي العــام واملدعــى عليهما قرر املدعــي العام اعتراضه‬\n      ‫علــى احلكــم مســتعدا بتقــدمي الئحــة اعتراضيــة وقــرر املدعــى عليهمــا‬\n      ‫اعتراضهمــا عليــه مســتعدين بتقــدمي لوائــح اعتراضيــة فأفهمــوا بأنــه‬\n      ‫ســيتم تســليمهما نســخة مــن صــك احلكــم هــذا اليــوم ولهمــا تقــدمي‬\n      ‫اعتراضهمــا عليــه خــال ثالثــن يومــا مــن تاريــخ هــذا اليــوم وإذا لــم‬\n      ‫يتقــدم أي منهمــا باعتراضــه خاللهــا فســيتم رفــع املعاملــة حملكمــة‬\n      ‫االســتئناف بــدون الئحتــه االعتراضيــة ففهمــوا ذلــك وختمــت اجللســة‬\n          ‫الساعة الثانية عشرة وصلى اهلل عليه وسلم ‪ .‬حرر ‪1433/12/27‬هـ‬\n               ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده ‪ ،‬وبعد ‪-:‬‬\n\n\n‫‪415‬‬\n\f‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائية اخلماســية األولــى مبحكمة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة بالباحــة برقــم وتاريــخ ‪1434/3/22‬ه ـ‬\n‫املرفــق بهــا القــرار رقــم وتاريــخ ‪1433/12/27‬ه ـ الصــادر مــن أصحــاب‬\n‫الفضيلــة القضــاة باحملكمــة العامــة بالباحــة الشــيخ (‪ ).....‬والشــيخ‬\n‫(‪ ).....‬والشــيخ (‪ ).....‬املتضمــن دعــوى املدعــي العــام ضــد (‪ ).....‬ورفيقــه‬\n‫املتهمــن يف ســرقة ‪ ،‬احملكــوم فيــه مبــا دون باطنــه‪ .‬املالحــظ عليــه‬\n   ‫بقــرار محكمــة االســتئناف رقــم ‪ 3450520‬وتاريــخ ‪1434/2/30‬ه ـ‬\n‫وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                 ‫وصحبه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪416‬‬\n\f                      ‫كشاف املوضوعات‬\n\n‫الصفحة‬                    ‫املوضوع‬                       ‫التصنيف‬        ‫م‬\n\n\n  ‫‪5‬‬         ‫محاولة انتحار وإيذاء النفس بآلة حادة‬       ‫محاولة انتحار‬   ‫‪1‬‬\n\n\n          ‫التستر على هارب وهروب من رجال البحث‬           ‫تستر على‬\n  ‫‪11‬‬                                                                   ‫‪2‬‬\n                        ‫اجلنائي‬                           ‫جاني‬\n\n\n                                                        ‫تستر على‬\n  ‫‪18‬‬     ‫إقرار املدعى عليه بالتستر على مطلوب أمني ًا‬                   ‫‪3‬‬\n                                                          ‫قاتل‬\n\n\n                                                         ‫تخلف عن‬\n  ‫‪33‬‬        ‫تخلف عن صالة اجلماعة من غير عذر‬                            ‫‪4‬‬\n                                                       ‫صالة اجلماعة‬\n\n\n                                                       ‫ترويج أجهزة‬\n  ‫‪39‬‬          ‫بيع أجهزة استقبال قنوات إباحية‬                           ‫‪5‬‬\n                                                         ‫ممنوعة‬\n\n\n           ‫سرقة سيارة بوضع التشغيل وسرقة بعض‬\n  ‫‪47‬‬               