ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة‬\n     ‫(‪ ).........‬لكســر الزجاجــة األماميــة مــن اجلهــة اليســرى ولــم يســرق منهــا‬\n     ‫شــي وبعثــرة مــا بداخلهــا أثنــاء وقوفهــا أمــام منزلــه بالقــرب مــن ‪..........‬‬\n     ‫وباســتجواب املدعى عليه األول أقر أنه يف حوالي الســاعة الثانية صباح‬\n     ‫يــوم البــاغ اجتــه رفق زمالئــه‪ ........./‬و‪ ........./‬واحلدث‪ ......... /‬واحلدث‪/‬‬\n     ‫‪ .........‬علــى دراجاتهــم الناريــة إلــى حــي ‪.........‬وكســر الزجاجــة األماميــة‬\n     ‫مــن اجلهــة اليســرى أثنــاء وقوفهــا أمــام منزلــه بحــي ‪ ..........‬وباســتجواب‬\n     ‫املدعــى عليــه الثانــي أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال‬\n     ‫زميلــه املذكــور مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬وباســتجواب‬\n     ‫املدعــى عليــه الثالــث أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال‬\n     ‫زميليــه املذكــوران مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪:‬‬\n     ‫مت مواجهــة كال مــن املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء‬\n     ‫يف اعترافــه حيــث أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن‬\n           ‫اتهــام وباســتمرار مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪.‬‬\n     ‫البــاغ اخلامــس والثالثــون ‪ :‬ـ بــاغ املواطن‪........./‬عــن تعــرض ســيارته‬\n     ‫التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقم اللوحة ‪ .........‬لكســر الزجاجة‬\n     ‫األماميــة مــن اجلهــة اليســرى أثنــاء وقوفهــا أمــام منزلــه بالقــرب ‪..........‬‬\n     ‫املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح أنهــا‬\n     ‫تقــع بحــي ‪.........‬شــوهدت الســيارة املذكــورة واقفــة أمــام منــزل املبلــغ‪،‬‬\n     ‫وشــوهدت الزجاجــة األماميــة مــن جهــة اليســرى متعرضــة للكســر‬\n     ‫حيــث شــوهد بعثــره باحملتويــات الداخليــة للســيارة ‪ .‬وبضبــط أقــوال‬\n     ‫املبلــغ ‪ ......... :‬عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪)....‬‬\n\n\n‫‪51‬‬\n\f‫رقــم اللوحــة ‪.........‬لكســر الزجاجــة األماميــة مــن اجلهــة اليســرى أثنــاء‬\n‫وقوفهــا أمــام منزلــه بالقــرب مــن ‪ ..........‬وباســتجواب املدعــى عليــه‬\n‫األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه رفــق‬\n‫زمالئه‪ ........./‬و‪ ........./‬واحلدث‪ ......... /‬واحلدث‪ ......... /‬على دراجاتهم‬\n‫الناريــة إلــى حــي ‪.........‬وكســر الزجاجــة األماميــة مــن اجلهــة اليســرى‬\n‫أثنــاء وقوفهــا أمــام منزلــه بحــي ‪..........‬وباســتجواب املدعــى عليــه الثانــي‬\n‫أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن‬\n‫حيــث الوصــف والوقــت والكيفيــة وباســتجواب املدعــى عليــه الثالــث‬\n‫أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران‬\n‫مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال‬\n‫مــن املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث‬\n‫أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن اتهــام وباســتمرار‬\n‫مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪ .‬البــاغ الســادس‬\n‫والثالثــون ‪ :‬ـ بــاغ املواطــن‪ ................../‬عــن تعــرض ســيارته التــي (‪)....‬‬\n‫م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة ‪ .........‬لكســر الزجاجــة األماميــة مــن‬\n‫اجلهــة اليســرى وســرقة مبلــغ وقــدره ثالثمائــة وخمســون ريــال وبطاقــات‬\n‫صــراف بنكيــة أثنــاء وقوفهــا أمــام منزلــه بالقــرب مــن ‪ ..........‬املعاينـ ــة ‪:‬‬\n‫مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح أنهــا تقــع بحــي‬\n‫‪ .........‬شــوهدت الســيارة املذكــورة واقفــة أمــام منزل املبلغ ‪ ،‬وشــوهدت‬\n‫الزجاجــة األماميــة مــن جهــة اليســرى متعرضــة للكســر حيــث شــوهد‬\n‫بعثــرة باحملتويــات الداخليــة للســيارة ‪ .‬وبضبــط أقــوال املبلــغ ‪......... :‬‬\n‫أفــاد عــن تعــرض ســيارته (‪ )....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة (‪).........‬‬\n‫لكســر الزجاجــة األماميــة مــن اجلهــة اليســرى وســرقة مبلــغ وقــدرة‬\n\n\n                                                                                         ‫‪52‬‬\n\f     ‫ثالثمائــة وخمســون ريــال وبطاقــات صــراف بنكيــة أثنــاء وقوفهــا أمــام‬\n     ‫منزلــه بالقــرب مــن ‪ ..........‬وباســتجواب املتهــم األول أقــر أنــه يف حوالــي‬\n     ‫الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه رفــق زمالئــه‪ ........./‬و‪........./‬‬\n     ‫واحلــدث‪ ......... /‬واحلــدث‪ ......... /‬علــى دراجاتهــم الناريــة إلــى حــي ‪.........‬‬\n     ‫وكســر الزجاجــة األماميــة مــن اجلهــة اليســرى وســرقة مبلــغ مالــي‬\n     ‫حوالــي ثالثمائــة ريــال أثنــاء وقوفهــا أمــام منزلــه بحــي (‪ .)....‬وباســتجواب‬\n     ‫املدعــى عليــه الثانــي أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال‬\n     ‫زميلــه املذكــور مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬وباســتجواب‬\n     ‫املدعــى عليــه الثالــث أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال‬\n     ‫زميليــه املذكــوران مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪:‬‬\n     ‫مت مواجهــة كال مــن املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء‬\n     ‫يف اعترافــه حيــث أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن‬\n         ‫اتهــام وباســتمرار مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪.‬‬\n     ‫البــاغ الســابع والثالثــون ‪ :‬ـ بــاغ املواطن‪........./‬عــن تعــرض ســيارته‬\n     ‫التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة‪ .........‬لكســر الزجاجة‬\n     ‫اخللفيــة مــن اجلهــة اليمنــى وبعثــرة مــا بداخلهــا أثنــاء وقوفهــا أمــام منزلــه‬\n     ‫بالقــرب مــن ‪..........‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة‬\n     ‫حيــث اتضــح أنهــا تقــع بحــي ‪ .........‬شــوهدت الســيارة املذكــورة واقفــة‬\n     ‫أمــام منــزل املبلــغ ‪ ،‬وشــوهدت الزجاجــة اخللفيــة مــن جهــة اليمنــى‬\n     ‫متعرضــة للكســر حيــث شــوهد بعثــره باحملتويــات الداخليــة للســيارة ‪.‬‬\n     ‫وبضبــط أقــوال املبلــغ ‪......... :‬عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬‬\n     ‫م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة ‪ .........‬لكســر الزجاجــة اخللفيــة مــن‬\n     ‫اجلهــة اليمنــى وبعثــرة مــا بداخلهــا أثنــاء وقوفهــا أمــام منزلــه بالقــرب‬\n\n\n‫‪53‬‬\n\f‫مــن ‪.........‬وباســتجواب املدعــى عليــه األول أقــر أنــه يف حوالــي الســاعة‬\n‫الثانيــة صبــاح يــوم البــاغ اجتــه رفــق زمالئــه‪ ........./‬و‪ ........./‬واحلــدث‪/‬‬\n‫‪ .........‬واحلــدث‪ ......... /‬علــى دراجاتهــم الناريــة إلــى حــي ‪.........‬وكســر‬\n‫الزجاجــة اخللفيــة مــن اجلهــة اليمنــى ريــال أثنــاء وقوفهــا أمــام منزلــه بحــي‬\n‫‪ ...............‬وباســتجواب املدعــى عليــه الثانــي أقــر مبــا نســب إليــه وجــاءت‬\n‫أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن حيــث الوصــف والوقــت‬\n‫والكيفيــة‪ .‬وباســتجواب املدعــى عليــه الثالــث أقــر مبــا نســب إليــه‬\n‫وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران مــن حيــث الوصــف‬\n‫والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال مــن املدعــى عليــه األول‬\n‫بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث أنكــر املذكــوران يف‬\n‫البدايــة مــا نســب إليهمــا مــن اتهــام وباســتمرار مواجهتهمــا بزميلهمــا‬\n‫املذكــور اعترفــا بالقضيــة‪ .‬محاضــر اإلرشــاد يف القضية ‪ -:‬مت اإلرشــاد‬\n‫مــن قبــل املدعــى عليهــم يف القضيــة علــى مواقــع الســيارات التــي قامــوا‬\n‫بتكســير زجاجهــا والســرقة منهــا بحــي ‪ .........‬وقريــة ‪.........‬وحــي‪.........‬‬\n                                  ‫و‪.........‬و‪ : .........‬وكانــت علــى النحــو اآلتــي‪:‬‬\n‫األول ‪ :‬أرشــد املدعــى عليهــم علــى املوقــع األول والــذي اتضــح أنــه‬\n‫مجموعــة الســيارات التــي مت تكســيرها بحــي ‪ .........‬حيــث ذكــروا‬\n‫أنهــم قدمــوا إلــى احلــي مــن اجلهــة الشــمالية عبــر طريــق فرعــي مســاحته‬\n‫مــا يقــارب (‪20‬م) ميتــد إلــى داخــل احلــي وشــاهدوا مجموعــة ســيارات مــا‬\n‫يقــارب إحــدى عشــرة ســيارة بجــوار بعــض ‪ ،‬فأقدمــوا علــى تكســير‬\n                                              ‫زجاجهــا وتفتيشــها والســرقة منهــا‪.‬‬\n‫الثانــي ‪ :‬أرشــد املدعــى عليهمــا األول والثانــي علــى املوقــع الثانــي والــذي‬\n‫اتضــح أنــه مجموعــة الســيارات التــي مت تكســيرها بقريــة ‪.........‬حيــث‬\n\n\n                                                                                          ‫‪54‬‬\n\f     ‫ذكــر املدعــى عليهمــا أنهمــا قدمــا إلــى قريــة ‪.........‬مــن اجلهــة الشــرقية‬\n     ‫عبــر الطريــق الرئيســي وبالوصــول إلــى منتصــف القريــة مت الدخــول إلــى‬\n     ‫اجلهــة الشــمالية منهــا عبــر طريــق فرعــي مســاحته مــا يقــارب ( ‪15‬م )‬\n              ‫ميتــد إلــى داخــل اجلهــة الشــمالية منهــا وشــاهدا مجموعــة ســيارات‬\n     ‫مــا يقــارب ثمــان ســيارات فأقدمــا علــى تكســير زجاجهــا وتفتيشــها‬\n                                                                           ‫والســرقة منهــا‪.‬‬\n     ‫الثالــث ‪ :‬أرشــد املدعــى عليهــم علــى املوقــع الثالــث والــذي يتكــون مــن‬\n                                                        ‫ثالثــة مواقــع علــى النحــو اآلتــي‪:‬‬\n     ‫أ) اتضــح أن املوقــع يعــود ملجموعــة الســيارات التــي مت تكســيرها بحــي‬\n     ‫‪ .........‬حيــث ذكــر املدعــى عليهــم أنهــم قدمــوا إلــى احلــي مــن اجلهــة‬\n     ‫الشــمالية عبــر الطريــق الرئيســي القــادم مــن مدينــة ‪ ..............‬ومــن ثــم‬\n     ‫إلــى طريــق فرعــي مــن اجلهــة الشــمالية منهــا حيــث أقدموا على تكســير‬\n                              ‫مــا يقــارب أربــع ســيارات يف أنحــاء متفرقــة مــن احلــي‪.‬‬\n     ‫ب) اتضــح أن املوقــع يعــود ملجموعــة الســيارات التــي مت تكســيرها‬\n     ‫بحــي ‪.........‬حيــث ذكــر املدعــى عليهــم أنهــم قدمــوا إلــى احلــي مــن اجلهــة‬\n     ‫الشــمالية عبــر الطريــق الرئيســي القــادم مــن مدينــة (‪ )....‬إلــى (‪)....‬‬\n     ‫ومــن ثــم إلــى طريــق فرعــي مــن اجلهــة الغربيــة منهــا حيــث أقدمــوا علــى‬\n            ‫تكســير مــا يقــارب خمــس ســيارات يف أنحــاء متفرقــة مــن احلــي‪.‬‬\n     ‫ج) اتضــح أن املوقــع يعــود ملجموعــة الســيارات التــي مت تكســيرها بحــي‬\n     ‫‪ .........‬حيــث ذكــر املدعــى عليهــم أنهــم قدمــوا إلــى احلــي مــن اجلهــة‬\n     ‫الشــمالية الغربيــة عبــر الطريــق الرئيســي القــادم مــن مدينــة‪..............‬‬\n     ‫ومــن ثــم إلــى طريــق فرعــي مــن اجلهــة الغربيــة منهــا حيــث أقدمــوا علــى‬\n              ‫تكســير مــا يقــارب ثالثــة ســيارات يف أنحــاء متفرقــة مــن احلــي‪.‬‬\n\n\n‫‪55‬‬\n\f                            ‫( مت فرز أوراق مستقلة للحدثني ‪ .........‬و‪.) .........‬‬\n‫وقــد أســفر التحقيــق معهــم عــن توجيــه االتهــام لهــم بتكويــن عصابــة‬\n‫لســرقة الســيارات وقيامهــم بالســرقة مــن عــدة ســيارات بعــد كســر‬\n                                  ‫زجاجهــا‪ ،‬وذلــك لألدلــة والقرائــن األتيــة‪-:‬‬\n‫‪ .1‬مــا جــاء يف إقراراتهــم املصدقــة شــرع ًا واملنــوه عنهــا‪ ،‬املــدون علــى‬\n‫الصفحــة رقــم (‪ )7،9‬مــن دفتــر التحقيــق رقــم (‪ ،)2‬والصفحــة رقــم (‪،6‬‬\n                                ‫‪ )14 ، 11 ، 8‬مــن دفتــر التحقيــق رقــم ( ‪.) 1‬‬\n‫‪ .2‬مــا ورد يف بالغــات املواطنــن واملقيمــن املذكوريــن عــن تعــرض‬\n‫ســيارتهم لتكســير زجاجهــا والســرقة منهــا وتطابــق ذلــك مــع إقــرارات‬\n‫املدعــى عليهــم ‪.3.‬مــا جــاء يف محاضــر املعاينــة املنــوه عنهــا ‪ ،‬واملدونــة‬\n‫علــى الصفحــة رقــم (‪ 2‬ـ ‪ )3‬مــن دفاتــر التحقيــق املرفقــة ( ‪) 30 ، 6‬‬\n‫‪ .4‬تطابــق األســلوب اإلجرامــي يف ارتــكاب هــذه الســرقات التــي ثبــت‬\n            ‫تورطهــم بهــا يدعــم توجيــه االتهــام ضدهــم بتلــك الســرقات ‪.‬‬\n‫‪ .5‬محاضــر اإلرشــاد املنــوه عنهــا واملدونــة علــى الصفحــة رقــم (‪)13 ، 11‬‬\n‫مــن دفتــر التحقيــق رقم(‪.)2‬وبالبحــث عمــا إذا كان لهــم ســوابق عثــر‬\n‫لــأول علــى ســابقتي ســرقة ‪ ،‬وعثــر للثانــي علــى ســابقة ســرقة‪ ،‬ولــم‬\n                    ‫يعثــر للثالــث علــى ســوابق مســجلة عليــه حتــى تاريخــه‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــورون ـ وهــم بكامــل قواهــم العقليــة‬\n‫املعتبــرة شــرع ًا ـ فعــل محــرم ومعاقــب عليــه شــرعا ‪ ،‬لــذا أطلــب إثبــات‬\n‫مــا أســند إليهــم واحلكــم عليهــم بعقوبــة تعزيريــة لقــاء مــا أســند إليهــم‬\n‫والتشــديد عليهــم لقــاء كثــرة وقــوع جرائــم ســرقة الســيارات يف الوقــت‬\n‫الراهــن ولكــون فعلهــم انطــوى علــى تكويــن عصابــي يف الســرقة ممــا‬\n                       ‫يســتلزم معــه التشــديد عليهــم يف العقوبــة لقــاء ذلــك‪.‬‬\n\n\n                                                                                     ‫‪56‬‬\n\f     ‫هكــذا ا َّدعــى ؛ عليــه فقــد حضــر املدعــى عليهــم وبعــد التأكــد مــن‬\n     ‫هوياتهــم جــرى عــرض دعــوى املدعــي العــام عليهــم فأجــاب املدعــى عليــه‬\n     ‫األول ‪.........‬قائ ًــا ‪ :‬ماذكــره املدعــي العــام مــن اتهامــي بتكوين عصابة‬\n     ‫لســرقة الســيارات املدعــى عليهمــا الثانــي والثالــث وقيامــي معهمــا‬\n     ‫بالســرقة مــن عــدة ســيارات بعــد كســر زجاجهــا فغيــر صحيــح وال‬\n     ‫ـأي ســرقة مــن هــذه الســرقات وصحيــح نســبة الســابقتني لــي‬           ‫عالقــة لــي بـ ِّ‬\n     ‫وقــد أخــذت محكوميتهمــا هكــذا أجــاب كمــا أجــاب املدعــى عليــه‬\n     ‫ا ‪ :‬ماذكــره املدعــي العــام مــن اتهامــي بتكويــن‬            ‫الثانــي ‪.........‬قائ ـ ً‬\n     ‫عصابــة لســرقة الســيارات مــع املدعــى عليهمــا األول و الثالــث وقيامــي‬\n     ‫معهمــا بالســرقة مــن عــدة ســيارات بعــد كســر زجاجهــا فغيــر صحيــح‬\n     ‫ـأي ســرقة مــن هــذه الســرقات وصحيــح نســبة الســابقة‬           ‫وال عالقــة لــي بـ ِّ‬\n     ‫لــي وقــد أخــذت محكوميتهــا هكــذا أجــاب كمــا أجــاب املدعــى عليــه‬\n     ‫ا ‪ :‬مــا ذكــره املدعــي العــام مــن اتهامــي بتكويــن‬       ‫الثالــث ‪ .........‬قائ ـ ً‬\n     ‫عصابــة لســرقة الســيارات مــع املدعــى عليهمــا الثانــي والثالــث وقيامــي‬\n     ‫معهمــا بالســرقة مــن عــدة ســيارات بعــد كســر زجاجهــا فغيــر صحيــح‬\n     ‫ـأي ســرقة مــن هــذه الســرقات هكــذا أجــاب وبطلــب‬            ‫وال عالقــة لــي بـ ِّ‬\n     ‫ـدي ســوى مــا يف أوراق‬‫البينــة مــن املدعــي العــام علــى دعــواه قــال ‪ :‬ليــس لـ َّ‬\n     ‫املعاملــة وأطلــب الرجــوع إليهــا هكــذا أجــاب ثــم جــرى االطــاع علــى‬\n     ‫جميــع أوراق املعاملــة ومنهــا إقــرار املدعــى عليه األول ‪ ..............‬املصادق‬\n     ‫عليــه شــرع ًا املوجــود علــى الصحيفــة ‪7 -6‬مــن ملــف التحقيــق لفــة(‪)1‬‬\n     ‫َصــه ‪« :‬نعــم أنــا املدعــو ‪.........‬ســعودي اجلنســية هويــة رقــم‬   ‫املتضمــن مان ُّ‬\n     ‫(‪ ).........‬أقـ ُّـر وأنــا بكامــل قــواي املعتبــرة أوصافهــا شــرع ًا وبطوعــي‬\n     ‫واختيــاري وبــدون إكــراه مــن أحــدٍ أو إجبــار إ َّنــه يف حوالــي الســاعة‬\n\n\n‫‪57‬‬\n\f‫الثانيــة صباح ـ ًا مــن يــوم األحــد املوافــق ‪1433/3/13‬ه ـ اجتهــت رفــق‬\n‫زمالئــي كل مــن املدعــو ‪.........‬واملدعــو ‪ .........‬واملدعــو ‪ .........‬واملدعــو‬\n‫‪ .........‬علــى دراجاتنــا الناريــة إلــى حــي ‪ .........‬حــي ‪ .........‬لغرض الســرقة‬\n‫وحينمــا وصلنــا إلــى احلــي حتديــد ًا بداخــل احلــي شــاهدنا ســيارات األولــى‬\n‫‪ :‬مــن نــوع (‪ )....()....‬م اللــون (‪ )....‬والثانيــة ‪ )....( :‬اللــون (‪ )....‬موديــل (‪)....‬‬\n‫م والثالثــة ‪)....( :‬اللــون (‪)....‬موديــل (‪)....‬م والرابعــة ‪)....( :‬موديــل (‪)....‬م‬\n‫اللــون (‪)....‬اخلامســة ‪)....( :‬اللــون (‪)....‬موديــل (‪)....‬م السادســة ‪)....( :‬‬\n‫اللــون (‪)....‬موديــل (‪)....‬والســابعة (‪)....‬املوديــل (‪)....‬م اللــون (‪)....‬الثامنــة ‪:‬‬\n‫(‪)....‬اللــون (‪)....‬موديــل (‪)....‬التاســعة ‪)....( :‬اللــون (‪)....‬موديــل (‪)....‬‬\n‫العاشــرة ‪)....()....( :‬م اللــون (‪)....‬احلاديــة عشــر ‪ :‬نــوع (‪)....()....‬م اللــون‬\n‫(‪)....‬الثانيــة عشــر ‪)....()....( :‬م اللــون (‪)....‬الثالثــة عشــر ‪ )....( :‬اللــون‬\n‫(‪)....‬موديــل (‪)....‬م الرابعــة عشــر ‪)....( :‬اللــون (‪)....()....‬م اخلامســة عشــر‬\n‫‪)....( :‬م (‪)....‬اللون (‪ )....‬السادســة عشــر ‪)....( :‬اللون (‪)....()....‬م الســابعة‬\n‫عشــر ‪)....()....( :‬م اللــون (‪ )....‬الثامنــة عشــر ‪)....( :‬اللــون (‪)....‬موديــل‬\n‫(‪ )....‬التاســعة عشــر ‪ )....()....( :‬م اللــون(‪ )....‬العشــرون ‪)....()....( :‬م‬\n‫اللــون(‪ )....‬الواحــدة والعشــرون ‪)....()....( :‬م اللــون (‪ )....‬والتــي كانــت‬\n‫واقفــة بنفــس احلــي بعضهــا بجــوار بعــض حيــث قمنــا بتكســير زجاجهــا‬\n‫مــن جهــة نافــذة الســائق وأخــرى مــن جهــة الراكــب وذلــك بــأداة حديديــة‬\n‫كانــت بحوزتنــا كل واحــد م َّنــا قــام بكســر زجــاج حوالــي ثالثــة إلــى‬\n‫أربــع ســيارات والســرقة مــن داخلهــا مبالــغ ماليــه مــا يقــارب خمســمائة‬\n‫ريــال وتقاســمهما فيمــا بيننــا كمــا إنــه يف حوالــي الســاعة الثانيــة مــن‬\n‫فجــر يــوم األحــد املوافــق ‪1433/3/20‬ه ـ قمــت أنا وزمالئــي املذكورين‬\n‫باالجتــاه أيض ـ ًا إلــى قريــة ‪.........‬وشــاهدنا مجموعــة ســيارات واقفــة‬\n\n\n                                                                                               ‫‪58‬‬\n\f     ‫بداخــل احلــي وقمنــا بتكســيرها بــأداة حديديــة وهــي مايقــارب ثمانيــة‬\n     ‫ســيارات وقمنــا بالســرقة مــن داخلهــا مبالــغ ماليــة وقدرهــا مــا يقــارب‬\n     ‫خمســمائة ريــال تقاســمانها فيمــا بيننــا وهــذا إقــرار منــي لذلــك وعليــه‬\n     ‫مت التوقيــع ‪ ..........‬كمــا جــرى االطــاع علــى إقــراره املصــادق عليــه‬               ‫َّ‬\n     ‫حتقيقـ ًا املوجــود علــى الصحيفــة‪ 5-4‬مــن ملــف التحقيــق لفــة‪ 2‬املتضمــن‬\n     ‫مانصــه ‪ :‬أنــا املدعــو ‪.........‬ســعودي اجلنســية هويــة رقــم (‪ ).........‬أقـ ُّـر وأنــا‬\n                                                                                             ‫ُّ‬\n     ‫بكامــل قــواي العقليــة املعتبــرة أوصافهــا شــرعها وبطوعــي واختيــار‬\n     ‫وبــدون إكــراه منــي أو إجبــار بأنــي يف حوالــي الســاعة الثانيــة مــن فجــر‬\n     ‫ال مــن‬‫يــوم الثالثــاء املوافــق ‪1433/3/15‬ه ـ اجتهــت رفــق زمالئــي ك ً‬\n     ‫املدعو ‪ .........‬واملدعو ‪ .........‬واملدعو ‪ .........‬واملدعو ‪.........‬على دراجاتنا‬\n     ‫الناريــة مــن قريــة ‪.........‬إلــى حــي ‪.........‬و‪.........‬و‪.........‬وقمنــا بتكســير‬\n     ‫زجــاج مــا يقــارب عــدد عشــر ســيارات األولــى مــن نــوع (‪)....‬اللــون (‪)....‬‬\n     ‫موديــل (‪ )....‬ب‪.........‬بــأداة حديديــة كانــت بحوزتنــا وقمنــا بفتحهــا‬\n     ‫والســرقة مــن داخلهــا والثانيــة (‪ )....‬اللــون (‪ )....‬بحــي ‪.........‬قمنــا‬\n     ‫بتكســير زجــاج النافــذة والســرقة مــن داخلهــا وأيضــا ســيارة مــن نــوع‬\n     ‫(‪)....()....‬م اللــون (‪ )....‬ب‪.........‬والســرقة مــن داخلهــا وأيضــا ســيارة مــن‬\n     ‫نــوع (‪ )....‬اللــون (‪)....()....‬م والســرقة مــن داخلهــا وســيارة مــن نــوع (‪)....‬‬\n     ‫اللــون (‪)....()....‬م والســرقة مــن داخلهــا وســيارة مــن نــوع (‪)....()....‬م يف‬\n     ‫‪.........‬والســرقة مــن داخلهــا وســيارة مــن نــوع (‪)....‬اللــون (‪)....()....‬م‬\n     ‫والســرقة مــن داخلهــا ‪.........‬وســيارة مــن نــوع (‪)....‬اللــون (‪)....()....‬م حــي‬\n     ‫‪.........‬والســرقة مــن داخلهــا وســيارة نــوع (‪)....‬اللــون (‪)....()....‬م حي ‪.........‬‬\n     ‫والســرقة مــن داخلهــا وســيارة نــوع (‪ )....‬اللــون (‪)....()....‬م والســرقة مــن‬\n     ‫داخلهــا حــي ‪ .........‬ومــن ضمــن املســروقات أغــراض شــخصية ألصحاب‬\n\n\n‫‪59‬‬\n\f‫الســيارات ومبالــغ ماليــة تصــل إلــى ســبعمائة ريــال تقريب ـ ًا ومســجل‬\n‫ســيارة منهــا مــا تقاســمناه فيمــا بيننــا وقمنــا بتصريفــه أمــا املســجل‬\n‫اعتقــد أنــه لــدى زميلــي ‪ .........‬مبنــزل ذويــه يف قريــة ‪ .........‬وهــذا إقــرار‬\n‫منــي بذلــك وعليــه أوقــع ‪ .‬املقـ ُّـر مبــا فيــه وبصمتــه وبعــرض هذيــن‬\n‫اإلقراريــن علــى املدعــى عليــه األول قــال صحيح صدور هذيــن اإلقرارين‬\n‫ـررت بســبب الضــرب الــذي القيتــه عنــد جهــة التحقيــق‬         ‫منــي ولكننــي أقـ ُ‬\n‫هكــذا قــرر فجــرى ســؤاله هــل لديــه بينــة علــى ذلــك فقــال ‪ :‬ال بينــة لــي‬\n‫علــى ذلــك هكــذا أجــاب كمــا جــرى االطــاع علــى إقــرار املدعــى عليــه‬\n‫الثانــي ‪ .........‬املصــادق عليــه شــرع ًا املوجــود علــى الصحيفــة ‪9 -6‬مــن‬\n‫َصــه ‪ « :‬نعــم أنا املدعــو ‪..................‬‬\n                                             ‫ملــف التحقيــق لفــة (‪ )2‬املتضمــن مــا ن ُّ‬\n‫ســعودي اجلنســية هويــة رقــم (‪ ).........‬أقـ َّـر وأنــا بكامــل قــواي املعتبــرة‬\n‫أوصافهــا شــرع ًا وبطوعــي واختيــاري وبــدون إكــراه مــن أحــد أو أجبــار‬\n‫بأنــي يف حوالــي الســاعة الثانيــة فجــر ًا مــن يــوم األحــد املوافــق‬\n‫‪1433/3/13‬ه ـ اجتهــت رفــق زمالئــي كل مــن املدعــو ‪.........‬واملدعــو‬\n‫‪ .........‬واملدعــو ‪ .........‬واملدعــو ‪ .........‬مســتقلني دراجاتنــا الناريــة مــن‬\n‫قريــة ‪ .........‬إلــى حــي ‪ .........‬حتديــد ًا بداخــل احلــي الســكني حيــث‬\n‫قمنــا بتكســير زجــاج واحــد وعشــرون ســيارة متوقفــة والســرقة مــن‬\n‫داخلهمــا هــي كالتالــي األولــى (‪)....()....‬م اللون(‪)....‬الثانيــة (‪)....()....‬م‬\n‫اللون(‪)....‬الثالثــة (‪)....()....‬م اللــون (‪ )....‬الرابعــة (‪ )....()....‬م اللــون(‪)....‬‬\n‫اخلامســة (‪)....()....‬م اللــون(‪ )....‬السادســة (‪)....()....‬م اللــون(‪ )....‬الســابعة‬\n‫(‪)....()....‬م اللــون(‪ )....‬الثامنــة (‪)....()....‬م اللــون (‪)....‬التاســعة (‪)....()....‬م‬\n‫اللــون (‪ )....‬العاشــرة (‪)....()....‬م احلاديــة عشــر (‪)....()....‬م اللــون(‪)....‬‬\n‫الثانيــة عشــر (‪)....()....‬م اللــون(‪ )....‬الثالثــة عشــر (‪)....‬اللــون(‪)....()....‬م‬\n\n\n                                                                                             ‫‪60‬‬\n\f     ‫الرابعــة عشــر (‪)....()....‬م اللــون (‪ )....‬اخلامســة عشــر (‪)....‬اللــون(‪)....()....‬‬\n     ‫م السادســة عشــر (‪)....()....‬م اللــون(‪ )....‬الســابعة عشــر (‪)....()....‬م‬\n     ‫اللــون(‪ )....‬الثامنــة عشــر (‪)....()....‬م اللــون التاســعة عشــر (‪)....()....‬م‬\n     ‫العشــرون (‪)....()....‬مــا للــون (‪ )....‬واحــد عشــرون (‪)....()....‬م اللــون(‪)....‬‬\n     ‫حيــث قمنــا بتكســير زجــاج نوافذهــا بــأداة حديديــة وباحلجــارة كل‬\n     ‫منــا قــام بكســر مــا يقــارب أربــع ســيارات وســرقة مبالــغ ماليــة وأغــراض‬\n     ‫شــخصية عثــر عليهــا بداخــل الســيارات حيــث أن املبالــغ تقاســمناها‬\n     ‫فيمــا بيننــا ويف يــوم الثالثــاء املوافــق ‪1433/3/15‬ه ـ يف حوالــي الســاعة‬\n     ‫الثانيــة فجــر ًا اجتهنــا نحــن اخلمســة أيضــا مــن قريــة ‪ .........‬على دراجاتنا‬\n     ‫الناريــة وقمنــا بســرقات متفرقــة مــن ســيارات كالتالــي األولــى مــن نــوع‬\n     ‫(‪)....‬اللــون(‪)....()....‬م بحــي (‪ )....‬والثانيــة (‪)....‬اللــون(‪ )....()....‬م بحــي‬\n     ‫‪ .........‬والثالثــة (‪)....‬اللــون(‪)....()....‬م ب‪.........‬والرابعــة (‪)....()....‬م حــي‬\n     ‫‪ .........‬واخلامســة (‪)....‬اللــون(‪)....()....‬م ب‪.........‬والسادســة (‪ )....()....‬م‬\n     ‫بحــي ‪.........‬الســابعة (‪)....‬اللــون(‪)....()....‬م ب ــ(‪ )....‬الثامنــة (‪)....‬اللــون(‪)....‬‬\n     ‫موديــل (‪)....‬م والتاســعة (‪)....‬اللــون(‪)....()....‬م بحــي ‪ .........‬والعاشــرة‬\n     ‫(‪)....‬اللون(‪)....‬املوديــل (‪ )....‬بحــي ‪ .........‬حيــث قمنــا بتكســير نوافذهــا‬\n     ‫بــأداة حديديــة وباحلجــارة كانــت بحوزتنــا كل واحــد منا قام بتكســير‬\n     ‫ســيارتني وســرقة مــن داخلهمــا مبالــغ ماليــة وأغــراض شــخصية ومســجل‬\n     ‫إحــدى الســيارات فيمــا تقاســمنا املبالــغ وقمنــا ببيــع املســجل ويف حوالــي‬\n     ‫الســاعة الثانيــة مــن فجــر يــوم األحــد املوافــق ‪1433/3/20‬ه ـ اجتهــت‬\n     ‫ورفقائــي املذكوريــن أيض ـ ًا علــى دراجتنــا الناريــة واجتهنــا إلــى قريــة‬\n     ‫‪.........‬وقمنا بتكســير عدد زجاج ثمانية ســيارات بواســطة أداة حديدية‬\n     ‫وحجــارة وقمنــا بســرقة منهــا مبالغ مالية وأغراض شــخصية تقاســمناها‬\n\n\n‫‪61‬‬\n\f‫فيمــا بيننــا وهــذا إقــرار منــي بذلــك وعليــه مت التوقيــع ‪ .‬املقــر مبــا فيــه‬\n‫‪ .........‬وبصمتــه وبعــر ض هــذا اإلقــرار علــى املدعــى عليــه أجــاب قائـاً‪:‬‬\n‫صحيــح صــدور منــي ولكـ َّـن مــا فيــه غيــر صحيــح وقــد أخــذ منــي‬\n‫باإلكــراه هكــذا قــرر فجــرى ســؤاله هــل لديــه بينــة علــى ذلــك فقــال ال‬\n‫بينــة لــدي علــى ذلــك هكــذا أجــاب كمــا جــرى االطــاع علــى إقــرار‬\n‫املدعــى عليــه الثالــث ‪ .........‬املصــادق عليــه شــرع ًا املوجــود علــى‬\n‫َصــه ‪ « :‬نعــم‬\n              ‫الصحيفــة ‪14 -11‬مــن ملــف التحقيــق لفــة (‪ )2‬املتضمــن مــا ن ُّ‬\n‫أنــا املدعــو ‪.........‬ســعودي اجلنســية هويــة رقــم ( ‪ ).........‬أقــر وأنــا بكامــل‬\n‫قــواي العقليــة املعتبــرة أوصافهــا شــرع ًا بطوعــي واختيــاري وبــدون أي‬\n‫إكــراه أو أجبــار مــن أحــد إ َّنــه يف حوالــي الســاعة الثانيــة مــن صبــاح‬\n‫كل مــن زمالئــي‬    ‫اليــوم األحــد املوافــق ‪1433/3/13‬ه ـ اجتهــت رفــق ٍ‬\n‫‪ .........‬و‪.........‬و‪ .........‬و‪ .........‬علــى دراجتنــا الناريــة مــن قريــة ‪ .........‬إلــى‬\n‫حــي ‪ .........‬حتديــد ًا ( حــي ‪ ).........‬بداخــل احلــي الســكني وقمنــا‬\n‫بتكســير الزجــاج عــدد واحــد وعشــرون ســيارة والســرقة منهــا وهــي‬\n‫كالتالــي األولــى ‪ -:‬مــن نــوع (‪)....()....‬م اللــون (‪ )....‬والثانيــة (‪)....‬اللــون‬\n‫(‪)....()....‬م والثالثــة (‪)....‬اللــون (‪)....()....‬م والرابعــة ‪)....( :‬موديــل (‪)....‬م‬\n‫واخلامســة (‪)....‬اللــون (‪)....‬موديــل (‪)....‬م والسادســة (‪ )....‬اللــون (‪)....‬‬\n‫موديــل (‪)....‬م والســابعة (‪ )....‬موديــل (‪)....‬م اللــون (‪)....‬والثامنــة (‪)....‬‬\n‫اللــون (‪)....‬موديــل (‪)....‬م والتاســعة ‪)....( -:‬اللــون (‪)....‬موديــل (‪)....‬‬\n‫العاشــرة ‪)....()....( -:‬م اللــون (‪)....‬احلاديــة عشــر (‪)....()....‬م اللــون (‪)....‬‬\n‫الثانيــة عشــر‪)....()....( -:‬م اللــون(‪ )....‬الثالثــة عشــر ‪)....( -:‬اللــون (‪)....‬‬\n‫(‪ )....‬م والرابعــة عشــر (‪)....‬اللــون(‪)....()....‬م اخلامســة عشــر ‪)....()....( -:‬‬\n‫م اللــون(‪ )....‬والسادســة عشــر ‪)....( :‬اللــون(‪)....()....‬م والســابعة عشــر‬\n\n\n                                                                                                  ‫‪62‬‬\n\f     ‫(‪)....()....‬م اللــون(‪ )....‬الثامنــة عشــر (‪)....‬اللــون (‪)....‬موديــل (‪ )....‬التاســعة‬\n     ‫عشــر (‪ )....‬موديــل (‪)....‬م اللــون(‪ )....‬العشــرون (‪)....()....‬م اللــون(‪)....‬‬\n     ‫حيــث قمنــا بســرقة مبالــغ ماليــة بقيمــة خمســمائة ريــال وبطاقــات‬\n     ‫صــراف ومســجالت مــن حوالــي ســيارتني أمــا املبالــغ تقاســمناها فيمــا‬\n     ‫بيننــا واملســجالت قمنــا ببيعهــا وبطاقــات الصــراف قمنــا برميهــا هــذا‬\n     ‫كمــا أقــر إنــه يف حوالــي الســاعة الثانيــة فجــر يــوم الثالثــاء املوافــق‬\n     ‫‪1433/3/15‬ه ـ قمــت أنــا وزمالئــي ‪ .........‬و‪.........‬و‪ .........‬و‪.........‬‬\n     ‫باالجتــاه للمــرة الثانيــة إلــى حــي ‪ .........‬و‪.........‬وحــي ‪.........‬وقمنــا‬\n     ‫بتكســير زجــاج الســيارات مــا يقــارب عشــر ســيارات يف أنحــاء متفرقــة‬\n     ‫مــن تلــك األحيــاء وقمنــا بســرقة مبالــغ ماليــة منهــا بقيمــة مــا يقــارب‬\n     ‫خمســمائة ريــال ومســجالت بعــدد مــا يقــارب ســيارتني وقمنــا بتقســيم‬\n     ‫املبالــغ فيمــا بيننــا كمــا مت بيــع املســجالت والتصــرف بقيمتهــا‬\n     ‫والســيارات األولــى نــوع (‪)....‬اللــون(‪ )....()....‬م والثانيــة نــوع (‪)....‬لــون‬\n     ‫(‪)....‬حــي ‪ .........‬والثالثــة مــن نــوع (‪)....()....‬م اللــون (‪)....‬ب‪..................‬‬\n     ‫والرابعــة مــن نــوع (‪)....‬اللــون (‪)....()....‬م ب ـ ــ‪ ..............‬واخلامســة (‪)....‬‬\n     ‫اللــون(‪)....()....‬م ب‪.........‬والسادســة مــن نــوع (‪ )....‬موديــل (‪)....‬م بحــي‬\n     ‫‪.........‬والســابعة نوع (‪ )....‬اللون (‪)....‬موديل (‪)....‬م ب‪......... .........‬والثامنة‬\n     ‫(‪)....‬اللــون(‪)....()....‬م والتاســعة (‪)....‬اللــون(‪ )....‬موديــل (‪ )....‬حــي ‪.........‬‬\n     ‫وســيارة نــوع (‪)....‬اللــون(‪)....()....‬م هــذا كمــا أقـ َّـر إ َّنــه بحوالــي الســاعة‬\n     ‫الثانيــة مــن صبــاح يــوم األحــد املوافــق ‪1433/3/20‬ه ـ اجتهــت أيض ـ ًا‬\n        ‫رفــق زمالئــي املذكوريــن إلــى قريــة ‪.........‬وقمنــا بعــدة ســرقات مــن ثمانِ‬\n     ‫ســيارات مــن داخــل احلــي الســكني األولــى مــن نــوع (‪)....‬اللــون(‪)....‬‬\n     ‫موديــل (‪)....‬م الثانيــة (‪)....‬اللــون(‪)....()....‬م الثالثــة (‪)....()....‬م اللــون (‪)....‬‬\n\n\n‫‪63‬‬\n\f‫الرابعــة (‪)....()....‬م اللــون(‪ )....‬اخلامســة (‪)....()....‬م السادســة (‪)....‬‬\n‫اللــون(‪)....()....‬م الســابعة (‪)....()....‬مــا للــون(‪ )....‬حيــث إن أســلوبنا‬\n‫اإلجرامــي يف ارتكابنــا لتلــك الســرقات هــو أن نقــوم بتكســير زجــاج‬\n‫تلــك الســيارات بــأدوات حديديــة وباحلجــارة ومــن ثــم نقــوم بفتحهــا‬\n‫وتفتيشــها وســرقة مــا بداخلهــا وهــذا إقــرار منــي بذلــك وعليــه مت التوقيع‬\n‫ا ‪ :‬صحيــح‬   ‫وبعــرض هــذا اإلقــرار علــى املدعــى عليــه الثالــث أجــاب قائـ ً‬\n‫ـررت بســبب الضــرب عنــد جهــة‬     ‫صــدور هــذا اإلقــرار منــي ولكننــي أقـ ُ‬\n‫التحقيــق وال بينــة لــدي علــى ذلــك كمــا إ َّننــي يف تاريــخ ســرقة ‪.........‬‬\n‫كنـ ُـت موقوفـ ًا يف شــرطة ‪ ..............‬وأطلــب الكتابــة لهــم للتأكــد مــن‬\n‫ذلــك هكــذا قــرر وقــد جــرت الكتابــة لشــرطة املبــرز للتأكــد مــن‬\n‫إيقــاف املدعــى عليــه الثالــث مــن عدمــه يف تاريــخ ســرقة ‪.........‬مبوجــب‬\n‫خطابنــا رقم‪331447609‬وتاريخ‪1433/08/04‬ه ـ فوردنــا خطابهــم‬\n‫أن املدعــى عليــه الثالــث‬  ‫رقم‪.........‬وتاريــخ ‪1433/08/06‬ه ـ املتضمــن َّ‬\n‫أوقــف لديهــم مــن تاريخ‪1433/03/19‬ه ـ إلــى تاريخ‪1433/03/21‬ه ـ‬\n‫كمــا جــرى االطــاع علــى كــروت ســوابق املدعــى عليهــم املتضمنــة‬\n‫وجــود ســابقتي ســرقة علــى املدعــى عليــه األول ووجــود ســابقة ســرقة‬\n‫علــى الثانــي وعــدم وجــود ســوابق علــى املدعــى عليــه الثالــث كمــا جــرى‬\n‫االطــاع علــى مذكــرات إيقــاف املدعــى عليهــم املتضمنــة أن األول‬\n‫أوقــف بتاريخ‪1433/04/08‬ه ـ وأن الثانــي والثالــث أوقفــا بتاريــخ‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد النظــر‬\n                                                          ‫‪1433/04/6‬ه ـ فبنـ ً‬\n‫أن املدعــى عليهــم‬ ‫يف حــال املدعــى عليهــم والتأكــد مــن أهليتهــم ومبــا َّ‬\n‫أنكــروا دعــوى املدعــي العــام باتهامهــم بتكويــن عصابــة لســرقة‬\n‫الســيارات وقيامهــم بالســرقة مــن عــدة ســيارات بعــد كســر زجاجهــا وال‬\n\n\n                                                                                     ‫‪64‬‬\n\f     ‫بينــة للمدعــي العــام علــى مــا نفــاه املدعــى عليهــم ســوى إقراراتهــم‬\n     ‫املصــادق عليهــا شــرع ًا وقــد رجعــوا عنهــا وا َّدعــوا اإلكــراه عليهــا ومبــا‬\n     ‫أ َّنهــم يتهمــون بذلــك ويــدلُّ عليــه إقراراتهــم املصــادق عليهــا شــرع ًا ومبــا‬\n     ‫ض‬        ‫{و َل ُت ْف ِسـ ُـدوا ِف ْ َ‬\n         ‫ال ْر ِ‬                              ‫أن مــا يتهمــون بــه مــن احملــرم شــرع ًا قال تعالى ‪َ :‬‬             ‫َّ‬\n                                          ‫{وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n     ‫الل ال ُي ِحـ ُّـب ْال ُْع َتدِ يـ َـن }‬                           ‫َب ْعـ َـد ِإ ْص َلحِ َهــا } وقــال تعالــى ‪َ :‬‬\n     ‫دم ـ ُه‬\n           ‫ـرام ُ‬\n                ‫وقــال صلــى اهلل عليــه وســلم ‪(( :‬كلُّ املســلم علــى املســلم حـ ٌ‬\n     ‫وعرضــه)) ممــا يســتوجب تعزيرهــم ويتوجــه أن يكــون املدعــى‬                                ‫ُ‬        ‫وما ُل ـ ُه‬\n     ‫عليــه الثالــث أقلهــم عقوبــة ألنــه ال ســوابق لــه ولعــدم توجــه التهمــة عليــه‬\n     ‫ا يف الســرقات التــي متــت يف قريــة ‪.........‬كونــه موقوف ـ ًا يف تاريــخ‬                            ‫أص ـ ً‬\n     ‫حدوثهــا لــذا كلــه وألجــل احلــق العــام حكمـ ُـت علــى املدعــى عليهــم مبــا‬\n     ‫ـدي إدانــة املدعــى عليهــم بتكوين عصابة لســرقة‬                            ‫يلــي ‪ :‬أو ًال ‪ /‬لــم يثبــت لـ َّ‬\n     ‫الســيارات وقيامهــم بالســرقة مــن عــدة ســيارات بعــد كســر زجاجهــا‬\n     ‫ـررت ر َّد عــوى املدعــي العــام بإثبــات ذلــك ‪.‬ثاني ًا ‪ /‬يعــزر املدعى عليهما‬                      ‫وقـ ُ‬\n       ‫األول ‪.........‬والثانــي ‪ .........‬ألجــل التهمــة القويــة بســجن كل واحــدٍ‬\n     ‫منهمــا ملــدة ســنتني وبجلــده ثالثمائــة جلــده مفرقــة علــى ســت دفعــات‬\n     ‫كل دفعــة خمســون جلــدة وبــن كل دفعــة وأخــرى مــدة ال تقــل عــن‬\n     ‫عشــرة أيــام‪ .‬ثالثـ ًا ‪ /‬يعــزر املدعــى عليــه الثالــث ‪ .........‬بســجنه ملــدة ســنة‬\n     ‫وســتة أشــهر مــن تاريــخ إيقافــه علــى ذمــة القضيــة وبجلــده مائتــي جلــدة‬\n     ‫مفرقــة علــى أربــع دفعــات كل دفعــة خمســون جلــدة وبــن كل دفعــة‬\n     ‫وأخــرى مــدة ال تقــل عــن عشــرة أيــام ‪.‬رابعـ ًا ‪ /‬يؤخــذ عليهــم التعهــد بعــدم‬\n     ‫العــودة ملثــل مــا يتهمــون بــه وبتــاوة احلكــم علــى الطرفني وإفهــام املدعى‬\n     ‫عليهمــا بحقهــم يف متييــز احلكــم قــرروا القناعــة بــه وطلــب املدعــي العــام‬\n     ‫رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم دون‬\n\n\n‫‪65‬‬\n\f‫الئحـ ٍة اعتراضيــة مكتفيـ ًا مبــا ورد يف الئحــة الدعــوى وأقفلــت اجللســة‬\n‫الســاعة الواحــدة ظهــر ًا وصلــى اهلل وسـلَّم علــى نبينــا محمــد وعلــى آلــه‬\n                                    ‫وصحبه أجمعني‪ُ .‬ح ِر َر يف ‪1433/08/12‬هـ‪.‬‬\n‫احلمــدهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي يــوم‬\n‫الثالثاء‪1433/12/21‬ه ـ فتحــت اجللســة الرابعــة الســاعة احلاديــة عشــر‬\n‫ـادت املعاملــة مــن محكمــة‬   ‫والنصــف وفيهــا حضــر الطرفــان وقــد عـ ْ‬\n‫االســتئناف باملنطقــة الشــرقية مبوجــب خطــاب فضيلــة رئيســها رقــم‬\n‫‪331614732‬وتاريخ‪1433/11/28‬ه ـ مرفقـ ًا بــه قــرار الدائــرة اجلزائيــة‬\n‫الثالثيــة األولــى رقم‪33452989‬وتاريخ‪1433/11/14‬ه ـ املتضمــن‬\n‫أن‬\n ‫مانصــه ‪ « :‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ َّ‬    ‫ُّ‬\n‫ماحكــم بــه فضيلتــه علــى املدعــى عليهــم قليــل جــد ًا وذلــك لشــناعة‬\n‫مــا أقـ َّـر بــه املدعــى عليهــم يف اعترافاتهــم وجرأتهــم علــى أمــوال النــاس‬\n‫إتالف ًا وأخذا وانتشــار هذه الظاهرة يف أوســاط الشــباب ووجود ســوابق‬\n‫علــى املدعــى عليهمــا األول والثانــي ممــا يســتوجب تعزيرهــم بتعزيــر بليــغ‬\n‫ملالحظــة ذلــك وإكمــال الــازم ومــن ثــم إعــادة املعاملــة واهلل املوفق» ا‪.‬هـ‬\n‫عليــه ُأ ِج ْيـ ُـب مشــايخي نفعنــي اهلل بعلمهــم وقــدم ســابقتهم يف القضــاء‪:‬‬\n‫ـإن احملكمــة ارتــأت هــذا احلكــم بعــد دراســة متأنيــة لهــذه القضيــة‬       ‫فـ َّ‬\n‫ونظــرت إلــى جوانـ َـب عــدة يف ذلــك ومنهــا حــال املدعــى عليهــم وصغــر‬\n‫وأن إقــرار املدعــى‬‫ســنهم واحتمــال صدقهــم فيمــا دفعــوا بــه الســيما َّ‬\n‫عليــه الثالــث غيــر قــوي إذ هــو مخالــف للواقــع يف بعــض أجزائــه ممــا‬\n‫قــد يجعــل إقــرار املدعــى عليهمــا األول والثانــي فيــه شــيء مــن الضعــف‬\n‫ولكــن بعــد تأمــل مــا ســبق ورجوعـ ًا إلــى قــول مشــايخي وهــم أعلــم منــي‬\n‫عمــا حكمــت بــه علــى املدعــى عليهم‬      ‫وأفقــه وأصــوب نظــرة فقــد رجعــت َّ‬\n\n                                                                                         ‫‪66‬‬\n\f     ‫يف الفقرتــن الثانيــة والثالثــة وقــررت تعزيــر املدعــى عليهمــا األول ‪.........‬‬\n     ‫والثانــي ‪ .........‬بســجن كل واحــد منهمــا ملــدة ســنتني وثمانيــة أشــهر مــن‬\n     ‫تاريــخ إيقافــه علــى ذمــة القضيــة وبجلــد كل واحــد منهمــا خمســمائة‬\n     ‫جلــدة مفرقــة علــى عشــر دفعــات كل دفعــة خمســون جلــدة وبــن كل‬\n     ‫دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام ويعــزر املدعــى عليــه الثالــث‬\n     ‫‪ .........‬بســجنه ملــدة ســنتني وثالثــة أشــهر تاريــخ إيقافــه علــى ذمــة القضيــة‬\n     ‫وبجلــده ثالثمائــة وخمســون جلــدة مفرقــة علــى ســبع دفعــات كل دفعــة‬\n     ‫خمســون جلــدة وبــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام‬\n     ‫وبذلــك حكمــت وبعــرض احلكــم عليهمــا قنــع بــه املدعــى عليهــم وأمــا‬\n     ‫ـرت بالتهميــش‬    ‫املدعــي العــام فهــو علــى مــا كان عليــه ســابقاً‪ .‬وأمـ ُ‬\n     ‫علــى قــرار احلكــم مبــا طــرأ عليــه ومــن ثـ ّـم إعــادة املعاملــة حملكمــة‬\n     ‫االســتئناف باملنطقــة الشــرقية لتدقيــق احلكــم وأقفلــت اجللســة الســاعة‬\n     ‫الثانيــة ظهــر ًا وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                   ‫أجمعــن ُحـ ِـر َر يف‪1433/12/21‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء برقــم‬\n     ‫‪ 332152654‬وتاريــخ ‪1434/1/6‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n     ‫‪/34/63136‬ج‪ 1‬وتاريــخ ‪1434/1/10‬ه ـ املرفــق بهــا القــرار الصادر من‬\n     ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪.........‬املســجل برقــم ‪33376865‬‬\n     ‫وتاريــخ ‪1433/8/12‬ه ـ اخلــاص بدعوى‪/‬املدعــي العام ضــد‪-......... -1/‬‬\n     ‫‪......... -.........‬يف قضيــة ســرقه وقــد تضمــن القــرار حكــم فضيلتــه مبــا‬\n     ‫هــو مــدون ومفصــل فيــه ‪ .‬حيــث ســبق دراســة القــرار وصــورة ضبطــه‬\n\n\n‫‪67‬‬\n\f‫وأوراق املعاملــة واالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه‬\n‫بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا رقــم ‪/33452989‬ج‪/1‬ب يف‬\n‫‪1433/11/14‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد االجــراء االخيــر‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                 ‫حــرر يف ‪1434/2/17‬هــ‪.‬‬\n\n\n\n\n                                                                               ‫‪68‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":14,"source_page_end":68,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5d396e226f2bef573076860505fd8f71d32e268ca859ba3a4b607759c0a62266","normalized_text_hash":"950d95cdf4e9037c577be17b53b8b76176c34a060f5f695b32e7ad3d1a14f5cd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p14-33376865"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

