                     ‫رجال األمن‬\n\f‫الصفحة‬                     ‫املوضوع‬                       ‫التصنيف‬       ‫م‬\n\n\n         ‫نشل وسرقة مبلغ مالي من شخص والقبض على‬\n ‫‪215‬‬       ‫السارق وصرف النظر عن حد السرقة لعدم‬          ‫نشل وسرقة‬      ‫‪19‬‬\n                        ‫وجود موجبها‬\n\n\n            ‫سرقة بعض محتويات غرفة بداخل فندق‬\n ‫‪223‬‬                                                       ‫سرقة‬        ‫‪20‬‬\n         ‫واملطالبة بإقامة حد السرقة وانتفاء شرط احلرز‬\n\n\n         ‫سرقة مزرعة وأغنام واشتراك يف السرقة وبيع‬\n ‫‪239‬‬                                                       ‫سرقة‬        ‫‪21‬‬\n                         ‫املسروقات‬\n\n\n         ‫انتهاك حرمة عدة منازل وسرقتها وسرقة مبالغ‬      ‫سرقة وانتهاك‬\n ‫‪273‬‬                                                                   ‫‪22‬‬\n                   ‫مالية وترويع الساكنني‬                 ‫حرمة منزل‬\n\n\n         ‫انتهاك حرمة منزل وسرقة جواالت واشتراك يف‬         ‫سرقة من‬\n ‫‪291‬‬                                                                   ‫‪23‬‬\n                          ‫السرقة‬                           ‫منزل‬\n\n\n           ‫انتهاك حرمة منزل وسرقة بعض محتوياته‬\n                                                          ‫سرقة من‬\n ‫‪306‬‬       ‫والرجوع عن إقرار مصدق شرع ًا ودرء حد‬                        ‫‪24‬‬\n                                                           ‫منزل‬\n                ‫السرقة والتعزير بالسجن واجللد‬\n\n\n ‫‪324‬‬              ‫خطف مبلغ مالي من مقيم‬                 ‫سرقة وخطف‬      ‫‪25‬‬\n\n\n         ‫سرقة حرز بعد هتكه وبيع املسروقات وسقوط‬\n ‫‪331‬‬                                                    ‫سرقة من حرز‬    ‫‪26‬‬\n          ‫حد السرقة لعدم توفر كامل شروط السرقة‬\n\n\n         ‫تخطيط للسرقة وتكسير عدد من السيارات‬\n ‫‪341‬‬                                                       ‫سرقة‬        ‫‪27‬‬\n          ‫وسرقة ما بداخلها من مبالغ مالية وعينية‬\n\f‫الصفحة‬                     ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n            ‫سرقة مجوهرات من حرز من داخل املنزل‬            ‫سرقة من‬\n ‫‪351‬‬                                                                ‫‪28‬‬\n          ‫ومقاومة الفرقة القابضة ومحاولة الهرب منها‬        ‫منزل‬\n\n\n          ‫سرقة مبالغ مالية وأسطوانات غار من املطعم‬\n                                                          ‫سرقة من‬\n ‫‪363‬‬      ‫واإلقرار حتقيق ًا ومن ثم الرجوع ومت درء حد‬                ‫‪29‬‬\n                                                           ‫مطعم‬\n                ‫السرقة والتعزير بالسجن واجللد‬\n\n\n         ‫سرقة بعض محتويات املنزل ومبلغ مالي والرجوع‬\n                                                          ‫سرقة من‬\n ‫‪375‬‬     ‫عن اإلقرار وادعاء اإلكراه بانتزاع اإلقرار ودرء‬             ‫‪30‬‬\n                                                           ‫منزل‬\n              ‫حد السرقة والتعزير بالسجن واجللد‬\n\n\n         ‫انتهاك حرمة عدة منازل وسرقة بعض محتوياتها‬        ‫سرقة من‬\n ‫‪381‬‬                                                                ‫‪31‬‬\n                    ‫وسرقة من بيت اجلار‬                     ‫منازل‬\n\n\n           ‫اشتراك يف سرقة وتعاطي احلبوب احملظورة‬\n ‫‪394‬‬                                                       ‫سرقة‬     ‫‪32‬‬\n            ‫وتهديد الغير بالقتل ومضايقتهم بالسيارة‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":394,"source_page_end":420,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"105b765a7ffc0707d31e336c4f9989acb6e5feeb3eacb24fe5cf8c4ecae01cb1","normalized_text_hash":"a8edf05f16933cb7951cba7361544c2d23dec47601015df36e88e662a7011a9a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p394-33480442"},{"id":"bbcc628e-5363-54f0-9e43-56f48e13f482","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -خلع مكينة صراف آلي -إحداث تلفيات -تستر على اجلناة- إقرار قصاص األثر -القرينة الظاهرة القوية -تعزير بالسجن","document_number":"33448617","case_number":"33484613","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/9","year":"1434","subject":"سرقة -خلع مكينة صراف آلي -إحداث تلفيات -تستر على اجلناة- إقرار قصاص األثر -القرينة الظاهرة القوية -تعزير بالسجن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33448617:‬تاريخه ‪1433/11/9:‬هـ‬\n                       ‫رقم الدعوى ‪33484613:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‬\n                 ‫‪ 3423879:‬تاريخه ‪1434/1/26:‬ه‬\n\n\n\n    ‫ســرقة‪ -‬خلــع مكينــة صــراف آلــي ‪ -‬إحــداث تلفيات‪ -‬تســتر علــى اجلناة‪-‬‬\n    ‫إقــرار قصــاص األثــر ‪ -‬القرينــة الظاهــرة القويــة ‪ -‬تعزيــر بالســجن‬\n                                                                     ‫واجللــد‪.‬‬\n\n\n\n\n    ‫مــا ذكــره ابــن القيــم ‪ -‬رحمــه اهلل‪ -‬يف الطــرق احلكيمــة ( ص ‪ 8‬ومــا‬\n    ‫بعدهــا ) «أن احلكــم بالقرينــة القويــة معمــول بــه عنــد أهــل العلــم»‪.‬‬\n\n\n\n\n    ‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا األول والثانــي بخلــع ماكينــة‬\n    ‫صــراف آلــي وســحبها بواســطة ســيارة ومحاولــة ســرقة مــا بداخلهــا‬\n    ‫وإحــداث تلفيــات بهــا وتســتر املدعــى عليــه الثالــث علــى املدعــى عليــه‬\n    ‫األول والثانــي‪ ،‬حيــث ســمع «األفــراد املســتلمني» مبخفر الشــرطة صوت‬\n    ‫جــرس اإلنــذار اخلــاص بجهــاز الصــراف اآللــي ‪ ،‬وعنــد خــروج الدوريــة‬\n    ‫للموقــع شــوهدت ســيارة تقــوم بســحب جهــاز الصــراف‪ ،‬وقامــت الدوريــة‬\n    ‫مبطاردتــه ‪ ،‬ويف أثنــاء املطــاردة انفصــل الســلك املعدنــي املســتخدم يف‬\n    ‫الربــط بــن جهــاز الصــراف والســيارة ‪ ،‬وهربــت الســيارة‪ ،‬فتــم التعميــم‬\n    ‫عليهــا‪ ،‬وقبــض علــى صاحبهــا فاعتــرف أن األول والثانــي همــا اللذيــن‬\n    ‫قامــا بذلــك‪ ،‬وطلــب املدعــي العــام تعزيرهم ألجــل ذلك‪ ،‬أنكر املدعى‬\n\n‫‪5‬‬\n\f‫عليهــم مــا جــاء بدعــوى املدعــى العــام‪ ،‬طلــب مــن املدعــى العــام بينتــه‬\n‫علــى دعــواه ‪ ،‬فوجــد إقــرار مصــدق شــرع ًا مــن املدعــى عليــه الثالــث‬\n‫يتضمــن طبــق مــا جــاء بدعــوى املدعــي العــام ‪ ،‬وبعرضــه علــى املدعــى‬\n‫عليــه الثالــث صــادق علــى إقــراره ‪ ،‬ودفــع أن ذلــك كان باإلكــراه ‪،‬‬\n‫ولــم يســتطيع إثبــات مــا يدعيــه مــن اإلكــراه ‪ ،‬ثــم جــرى االطــاع علــى‬\n‫كافــة أوراق املعاملــة فوجــد مــن ضمنهــا قــرار قصــاص األثــر املتضمــن‬\n‫انطبــاق آثــار املدعــى عليهمــا األول والثانــي علــى اآلثــار املوجــودة عنــد‬\n‫موقــع الصرافة‪،‬احلكــم علــى املدعــى عليهمــا األول والثانــي بالســجن‬\n‫واجللــد واحلكــم باجللــد علــى املدعــى عليــه الثالــث ‪ ،‬قــرر املدعــى عليهــم‬\n‫االعتــراض علــى احلكــم بالئحــة اعتراضيــة بينمــا املدعــي العــام قــرر‬\n   ‫االعتــراض بــدون الئحــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة بينبــع‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمة العامــة بينبع‬\n‫املســاعد برقــم ‪ ....‬وتاريــخ ‪1433/07/23‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ ....‬وتاريــخ ‪ 1433/07/21‬ه ـ ففــي يــوم األحــد املوافق‪1433/09/10‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 12 : 15‬وفيهــا حضــر املدعــي العــام ‪....‬‬\n‫ســعودي اجلنســية بالســجل املدنــي رقــم (‪ )...‬املفــوض لــه إقامــة الدعــوى‬\n‫بالتفويــض رقــم ه ـ د ‪ 1433/2/2‬وتاريــخ ‪1426/12/22‬ه ـ كمــا‬\n‫حضــر املدعــى عليهــم وقــرر املدعــي العــام قائــا بصفتــي مدعيــا عامــا‬\n‫بدائــرة االدعــاء العــام ادعــى علــي كال مــن ‪ 33... -1‬عام ـ ًا ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬متســبب قبــض عليــه بتاريــخ‬\n                                                                                      ‫‪6‬‬\n\f    ‫‪1433/4/24‬ه ـ وأودع ســجن ينبــع مبوجــب أمــر متديــد التوقيــف رقــم‬\n    ‫‪ 1560‬يف ‪1433/5/25‬هــ‪ 29... -2-‬عام ـ ًا ســعودي اجلنســية مبوجــب‬\n    ‫الســجل املدنــي رقــم (‪ ، )....‬متســبب قبــض عليــه بتاريــخ ‪1433/5/3‬ه ـ‬\n    ‫وأودع ســجن ينبــع مبوجــب أمــر متديــد التوقيــف رقــم ‪ 1561‬يف‬\n    ‫‪1433/5/25‬هــ‪ 26 ... -3-‬عام ـ ًا ســعودي اجلنســية مبوجــب الســجل‬\n    ‫املدنــي رقــم (‪ )....‬متســبب قبــض عليــه بتاريــخ ‪1433/4/17‬ه ـ وأفــرج‬\n    ‫عنــه بالكفالــة احلضوريــة بتاريــخ ‪1433/5/26‬ه ـ حيــث إنــه بتاريــخ‬\n    ‫‪1433/3/28‬هـ ســمع اإلفراد املســتلمني مبخفر شــرطة ‪ ....‬صوت جرس‬\n    ‫اإلنــذار اخلــاص بجهــاز الصــراف اآللــي اخلــاص ببنــك ‪ ...‬بجــوار محطــة‬\n    ‫القاضــي وعنــد خــروج الدوريــة إلــى املوقــع شــوهد ســيارة مــن نــوع ‪.......‬‬\n    ‫يقــوم بســحب جهــاز الصــراف اآللــي بعــد أن مت قلعــه مــن مكانــه وقامت‬\n    ‫الدوريــة مبطاردتــه وأثنــاء ذلــك انفصــل (الوايــر) الــذي مت ربطــه بجهــاز‬\n    ‫الصــراف ووقــع جهــاز الصــراف علــى األرض والذوا بالفــرار وقــد مت‬\n    ‫التعميــم عــن الســيارة ‪.‬وقــدرت تلفيــات إصــاح اجلهــاز (‪)136،643‬مائــة‬\n    ‫وســتة وثالثــون آلــف وأربعمائــة وثالثــة وســتون ريال ‪.‬وجــرى معاينة املوقع‬\n    ‫الــذي ســحب منــه جهــاز الصــراف اآللــي اخلــاص ببنــك ‪ ...‬واتضــح أنــه يقع‬\n    ‫بقريــة ‪ ......‬علــى الطريــق العــام املــؤدي للــ‪ .....‬وأمــام محطــة الوقــود وان‬\n    ‫جهــاز الصــراف مت خلعــه مــن مكانــه حيــث أنــه مثبــت بأربعــة مســامير‬\n    ‫علــى صبــة خراســانية ولــم يتبقــى ســوى اجلــزء اخلــاص باإلضــاءة ووجــد‬\n    ‫باملوقــع قطعــة (وايــر بطــول أربعــة أمتــار) وسلســلة حديديــة بطــول متريــن‬\n    ‫ومت حتريزهــا ووجــد باملوقــع اثــر شــخصني واثــر ســيارة ‪ .....‬وكذلــك‬\n    ‫اثــر ســحب جهــاز الصــراف مــن موقعــه األصلــي واالجتــاه بــه عبــر‬\n    ‫الطريــق العــام اإلســفلتي مبســافة (‪700‬متــر) تقريب ـ ًا باجتــاه مدخــل ‪....‬‬\n\n\n‫‪7‬‬\n\f‫وقامــوا باالنحــراف مــع طريــق صحــراوي يســار وأثنــاء ذلــك ســقط جهــاز‬\n‫الصــراف وعــدد (‪ )9‬طلقــات رشــاش حيــة (فصلــت لهــا أوراق مســتقلة‬\n‫باخلطــاب رقــم ‪ 2/13/277/22‬وتاريــخ ‪1433/7/13‬ه ـ )‪ .‬وبالبحــث‬\n‫التحــري مت القبــض علــى املدعــى عليــه الثالــث بتاريــخ ‪1433/4/17‬ه ـ‬\n‫وباســتجوابه أفــاد انــه عندمــا كان ذاهبـ ًا ألخيــه مبنطقــة ‪.....‬تقابــل مــع‬\n‫املدعــى عليهمــا األول والثانــي وكان الثانــي يقــود ســيارة مــن نــوع ‪......‬‬\n‫وذكــرا لــه أنهمــا متجهــن لســرقة الصــراف اآللــي اخلــاص ببنــك ‪...‬‬\n‫ولــم يقــوم باإلبــاغ عنهمــا خوف ـ ًا علــى نفســه‪ .‬وبتاريــخ ‪1433/4/24‬ه ـ‬\n‫مت القبــض علــى املدعــى عليهمــا األول والثانــي بعــد البحــث والتحــري‬\n‫وباســتجوابهما أنكــرا مــا نســب إليهمــا وأفــاد األول انــه لــم يســبق أن‬\n‫اتصــل عليــه الثانــي وال يعــرف رقــم جوالــه وان معرفتهمــا ببعــض معرفــة‬\n‫ســطحية ‪.‬وبالبحــث عــن املكاملــات الصــادرة والــواردة علــى جــوال األول‬\n‫والثانــي اتضــح وجــود مكاملــة صــادره مــن جــوال الثانــي ‪ ...‬رقــم (‪)...‬‬\n‫إلــى جــوال األول ‪ ...‬رقــم (‪ )...‬وكذلــك مكاملــات صــادره مــن جــوال‬\n‫األول ‪ ...‬إلــى جــوال الثانــي ‪ ..‬وقــد اثبــت قصــاص األثــر تطابــق األثــر‬\n‫الــذي عثــر عليــه عنــد الصــراف وكذلــك األثــر املوجــود مبوقــع ســقوط‬\n‫الصــراف هــو نفــس اثــر املدعــى عليــه األول والثانــي وقــد اثبــت قصــاص‬\n‫األثــر انطبــاق اآلثــار املوجــودة مبوقــع الصــراف اآللــي علــى أثــار إطــارات‬\n‫‪ .....‬رقــم اللوحــة (‪ )... ...‬والعائــد لوالــد املدعــى عليــه الثانــي وقــد انتهــى‬\n‫التحقيــق بتوجيــه االتهــام لــأول والثانــي بخلــع مكينــة صــراف آلــي‬\n‫وســحبها بواســطة ســيارة ومحاولــة ســرقة مــا بداخلهــا وإحــداث تلفيــات‬\n‫بهــا وتســتر الثالــث عليهمــا وذلــك لألدلــة والقرائــن التاليــة ‪ -1-:‬مــا جــاء‬\n‫باعتــراف الثالــث واملصــدق عليــه شــرع ًا املدونــة علــى ص (‪ )5-4‬لفــه‬\n\n\n                                                                                          ‫‪8‬‬\n\f    ‫(‪ )5‬وعلــى ص(‪ )3‬لفــه (‪ -2- )4‬مــا جــاء بتناقــض أقــوال املدعــى عليهمــا‬\n    ‫األول والثانــي مــن أنهمــا ال يعرفــان بعــض ولــم يحصــل بينهمــا اتصــاالت‬\n    ‫هاتفيــة ‪ - 3-‬مــا جــاء باالطــاع علــى املكاملــات الــواردة والصــادرة مــن‬\n    ‫جــوال املدعــى عليهمــا األول والثانــي ‪ -4-‬مــا ورد بقصــاص األثــر املــدون‬\n    ‫علــى لفــة (‪ )1‬وبالبحــث عــن ســوابقهم عثــر للثانــي علــى ســابقتني ســرقة‬\n    ‫وحيــازة واســتعمال مخــدرات ولــم يعثــر لــأول والثالــث علــى ســوابق‬\n    ‫مســجلة عليهمــا وحيــث أن مــا أقــدم عليــه املذكــورون فعــل محــرم‬\n    ‫ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات مــا أســند إليهــم واحلكــم عليهــم‬\n    ‫بعقوبــة تعزيريــة علمــا بــأن احلــق اخلــاص ال يــزال قائمـ ًا واهلل املوفق انتهى‪.‬‬\n    ‫ثــم جــرى ســؤال املدعــى عليهــم الثالثــة عمــا جــاء يف دعــوى املدعــي العــام‬\n    ‫فأنكــروا جميعــا مــا جــاء يف دعــوى املدعــي العــام وبســؤال املدعي العام‬\n    ‫عــن بينتــه أجــاب قائــا بينتــي مــا جــاء باملعاملــة ممــا ذكرتــه يف دعــواي‬\n    ‫مــن األدلــة والقرائــن هكــذا أجــاب وألجــل قــرب وقــت صــاة الظهــر‬\n    ‫وألجــل الرجــوع إلــى املعاملــة وقراءتهــا رفعــت اجللســة ويف يــوم الثالثــاء‬\n    ‫املوافــق ‪1433/10/17‬ه ـ افتتحــت اجللســة الســاعة ‪ 11.00‬وفيهــا حضر‬\n    ‫املدعــي العــام واملدعــى عليهــم ثــم جــرى الرجــوع إلــى املعاملــة ووجــد بهــا‬\n    ‫وعلــى ملــف التحقيــق لفــة رقــم (‪ )4‬ص (‪ )3‬إقــرار مــن املدعــى عليــه‬\n    ‫الثالــث بتاريــخ ‪1433/4/23‬ه ـ ومصــادق عليــه شــرعا مــن احملكمــة‬\n    ‫العامــة ‪ .....‬ونصــه‪« :‬أقــر أنــا املواطــن ‪ ...‬ســعودي اجلنســية مبوجــب‬\n    ‫الســجل املدنــي رقــم ‪ ....‬وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا ال‬\n    ‫مجبــر وال مكــره وأنــه يف مســاء يــوم األحــد املوافــق ‪1433/3/27‬ه ـ‬\n    ‫ويف متــام الســاعة الثانيــة صباحــا ذهبــت بســيارتي ‪ .....‬مــن منزلنــا‬\n    ‫الواقــع بالــ‪ ...‬متجه ـ ًا إلــى حظيــرة أغنــام والــدي بقصــد املبيــت عندهــا‬\n\n\n‫‪9‬‬\n\f‫حتــى الصبــاح حيــث تقــع يف غــرب ‪ ......‬وأثنــاء مــروري مــع االزفلــت‬\n‫وبالتحديــد أمــام عمــارة الشــيخ ‪ ....‬قابلتنــي ســيارة مــن نــوع ‪......‬حيــث‬\n‫إننــي لســت متأكــد ًا مــن موديلــه وأشــروا لــي بالنــور ووقفــت بجانبهــم‬\n‫واتضــح أن الســيارة بقيــادة املواطــن ‪ ...‬وبجانبــه ‪ ....‬وشــخص ثالــث ال‬\n‫أعرفــه ولــم أتأكــد مــن أوصافــه وبادرتهــم بالســؤال مــاذا تريــدون فــرد‬\n‫علــي ‪ ...‬املذكــور بقولــه نريــد أن نســرق صرافــة بنــك ‪ ...‬وإذا شــفت‬\n‫أو شــاهدت أي شــخص أبلغنــا وقلــت لهــم خــاص موافــق علــى ذلــك‬\n‫وذهبــا مــن عنــدي وبعــد ذلــك ذهبــت مــن املوقــع خوفــا أن يحصــل شــيء‬\n‫وأكــون أنــا ضحيتــه أو أن يســيء إلــي املذكــورون بــأي شــيء جتاهــي‬\n‫فذهبــت إلــى حظيــرة أغنــام والــدي وواصلــت طريقــي بعــد ذلــك ملدينــة‬\n‫‪ ......‬ووصلــت إلــى مدينــة ‪ ......‬يف متــام الســاعة اخلامســة والنصــف صباحــا‬\n‫مــن يــوم االثنــن املوافــق ‪1433/2/28‬ه ـ هــذا مــا حصــل بالتفصيــل وأن‬\n‫ســبب إخفائــي لهــذه املعلومــات مــن بدايــة التحقيــق معــي هــو خــويف مــن‬\n‫املذكوريــن أن يقومــوا بقتلــي كمــا أوكــد علــى نفســي بــأن جميــع مــا‬\n‫ذكــر أعــاه هــو الصحيــح وأن الذيــن قابلونــي هــم كال مــن املواطــن ‪....‬‬\n‫قائــد الســيارة ومعــه املواطــن ‪ ....‬وشــخص ثالــث ال أعرفــه وال أســتطيع‬\n‫التعــرف عليــه وإننــي متأكــد منهــم متام ـ ًا ومســتعد بتصديــق اعتــرايف‬\n                                              ‫هــذا شــرع ًا وعليــه أوقــع» انتهــى‪.‬‬\n‫ا هــذا اإلقــرار‬ ‫وبســؤال املدعــى عليــه الثالــث عــن اإلقــرار أجــاب قائ ـ ً‬\n‫أخــذ منــي حتــت اإلكــراه هكــذا أجــاب وبســؤاله عــن البينــة أجــاب‬\n‫ا ال بينــة لــدي ثــم جــرى ســؤال املدعــى عليــه األول والثانــي عــن مــا‬  ‫قائـ ً‬\n‫ذكــره املدعــي العــام يف دعــواه مــن أنهمــا قــد ذكــرا أنهمــا ال يعرفــا‬\n‫بعضهــم البعــض ولــم يحصــل بينهــم اتصــاالت هاتفية فأجــاب كل واحد‬\n\n\n                                                                                        ‫‪10‬‬\n\f     ‫ا لــم نذكــر أننــا ال يعــرف بعضنــا البعــض وكل‬             ‫منهمــا مبفــرده قائ ـ ً‬\n     ‫مــا ذكرنــاه أنــه لــم يقــم أحدنــا باالتصــال علــى األخــر وأرقــام اجلــواالت‬\n     ‫التــي ذكرهــا املدعــي العــام يف دعــواه هــي عائــدة إلينــا وبيــان األمــر أن‬\n     ‫والــد املدعــى عليــه الثانــي تاجــر كبيــر معــروف عندنــا باملنطقــة والنــاس‬\n     ‫تتصــل علــى جــوال ابنــه ألنــه ال يحمــل جــوال فهــو كبيــر يف الســن ولرمبا‬\n     ‫أخــذ بعــض النــاس جــوال املدعــى عليــه األول واتصــل علــى جــوال املدعــى‬\n     ‫عليــه الثانــي ليكلــم أبــاه يف أمــور بيــع وشــراء هكــذا أجابــا كمــا وجــد‬\n     ‫باملعاملــة وعلــى ملــف التحقيــق املرفــق لفــة رقــم (‪ )1‬ص (‪)16‬إقــرار‬\n     ‫قصــاص األثــر املــؤرخ بتاريــخ ‪1433/5/5‬ه ـ ونصــه كالتالــي‪« :‬أقــر أنــا‬\n     ‫قصــاص األثــر مبركــز ‪ ......‬واملوقــع اســمي أدنــاه بأنــه وبنــاء ملعاينــة‬\n     ‫اآلثــار املوجــودة عنــد ســرقة صــراف ‪ ...... ...‬وبنــاء حملضــري املــدون علــى‬\n     ‫ص (‪ )7‬مــن هــذا امللــف فعليــه إقــر بأنــه مت معاينــة اآلثــار املوجــودة باملوقع‬\n     ‫علــى أثــار املتهمــن كال مــن املواطــن ‪ .... /‬واملواطــن ‪ .... /‬واملواطــن ‪....‬‬\n     ‫واتضــح لــي مــن املعاينــة بــأن األثــار املوجــودة عنــد موقــع الصرافــة التــي‬\n     ‫بجانــب احملطــة هــي أثــار املواطــن ‪ ....‬حيــث انطبقــت متامــا علــى آثــاره أمــا‬\n     ‫بالنســبة لآلثــار املوجــودة خلــف مركــز التفتيــش مــن جهــة الشــرق وهــي‬\n     ‫أثــار لشــخصني عندمــا قامــا يف محاولــة ربــط الصرافــة عنــد وقوعهــا‬\n     ‫وقــد انطبقــت اآلثــار املوجــودة عندهــا علــى آثــار كل مــن املواطــن‬\n     ‫‪ ....‬واملواطــن ‪ ....‬حيــث أنهــا نفــس اآلثــار وبنــاء لذلــك مت إعــداد هــذا‬\n     ‫احملضــر وعليــه جــرى التوقيــع املقــر مبــا فيــه ‪ ....‬انتهــى ‪ .‬ثــم جــرى ســؤال‬\n     ‫املدعــى عليــه الثانــي عــن الســابقتني املذكورتــن يف دعــوى املدعــي‬\n     ‫العــام أحدهمــا ســرقة واألخــرى حيــازة واســتعمال مخــدرات فصــادق‬\n     ‫عليهــا هــذا وألجــل دراســة القضيــة رفعــت اجللســة ويف يــوم االثنــن‬\n\n\n‫‪11‬‬\n\f‫املوافــق‪ 1433/11/01‬ه ـ افتتحــت اجللســة الســاعة ‪ 10.30‬وفيهــا حضر‬\n‫املدعــي العــام واملدعــى عليهــم هــذا وألجــل مــا جــاء يف الدعــوى واإلجابــة‬\n‫وملــا جــاء يف اعتــراف املدعــى عليــه الثالــث املصــدق شــرعا والــذي رجــع‬\n‫عنــه ولوجــود االتصــاالت بــن املدعــى عليــه األول واملدعــى عليــه الثانــي‬\n‫وملــا جــاء يف قــرار قصــاص األثــر املذكــور وألن املدعــى عليــه الثانــي‬\n‫عليــه ســابقتان إحداهمــا ســرقة وألن احلكــم بالقرينــة الظاهــرة القويــة‬\n‫معمــول بــه عنــد أهــل العلــم ( الطــرق احلكميــة ألبــن القيــم ص ‪ 8‬ومــا‬\n‫بعــده) فقــد ثبــت لــدي القرينــة القويــة علــى املدعــى عليهــم الثالثــة مبــا‬\n‫نســب إليهــم يف دعــوى املدعــي العــام وقــررت تعزيرهــم مبــا يلــي أوال‪:‬‬\n‫احلكــم علــى املدعــى عليــه األول ‪ ....‬بالســجن ثالثــة ســنوات اعتبــار ًا مــن‬\n‫تاريــخ دخولــه الســجن يف ‪1433/5/25‬ه ـ وجلــده مائتــا جلــدة مفرقــة‬\n‫علــى أربــع دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى‬\n‫أســبوع ثانيــا‪ :‬احلكــم علــى املدعــى عليــه الثانــي ‪ ...‬بالســجن ملــدة أربــع‬\n‫ســنوات اعتبــار ًا مــن تاريــخ دخولــه الســجن يف ‪1433/5/25‬ه ـ وجلــده‬\n‫ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات كل دفعــة خمســون جلــده بــن‬\n‫كل دفعــة وأخــرى أســبوع ثالثــا‪ :‬احلكــم علــى املدعــى عليــه الثالــث ‪....‬‬\n‫بجلــده خمســون جلــدة دفعــة واحــدة هــذا مــا حكمــت بــه ألجــل احلــق‬\n‫العــام وبعــرض احلكــم علــى املدعــي العــام قــرر اعتراضــه بــدون الئحــة‬\n‫وقــرر املدعــى عليهــم الثالثــة اعتراضهــم بالئحــة اعتراضيــة وأفهمــوا أن‬\n‫لهــم مــدة ثالثــن يومــا مــن اســتالم صــورة القــرار الشــرعي وإذا انتهــت‬\n‫املــدة ولــم يتقدمــوا باعتراضهــم فــإن القــرار ســيرفع إلــى محكمــة‬\n‫االســتئناف وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه وســلم حــرر يف ‪ 1433/11/01‬ه ـ‬\n\n\n                                                                                      ‫‪12‬‬\n\f              ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n     ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثانيــة يف محكمــة‬\n     ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة العامــة املســاعد بينبــع برقــم ‪331371556‬‬\n     ‫وتاريــخ ‪1434/1/17‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n     ‫الشــيخ‪ .....‬القاضــي باحملكمــة العامــة بينبــع برقــم ‪ 33448617‬وتاريــخ‬\n     ‫‪1433/11/9‬ه ـ ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪ ... /‬ورفقــاه ‪،‬‬\n     ‫املتهمــن يف قضيــة ســرقة ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة‬\n     ‫القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق‬\n                   ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪13‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":5,"source_page_end":13,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"73a712a5ad2adc321d7e6c932c10ace63cd2f04e9b1e4369820093a726f5dd89","normalized_text_hash":"49b8b3fe8d0a2024d29fa843a2e249711374f06b80e1152de7fc6635237c9112","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p5-33448617"},{"id":"d2c1e956-c907-530c-90d7-a70025f41681","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -كسر زجاج سيارة وسرقة محتوياتها -محاضر اإلرشاد - طلب التشديد يف العقوبة -التعزير ألجل الشبهة القوية -تشكيل عصابي -تشديد العقوبة -رجوع عن اإلقرار بدعوى اإلكراه - التعزير بالسجن واجللد وأخذ التعهد.","document_number":"33376865","case_number":"33491322","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/08/12","year":"1434","subject":"سرقة -كسر زجاج سيارة وسرقة محتوياتها -محاضر اإلرشاد - طلب التشديد يف العقوبة -التعزير ألجل الشبهة القوية -تشكيل عصابي -تشديد العقوبة -رجوع عن اإلقرار بدعوى اإلكراه - التعزير بالسجن واجللد وأخذ التعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33376865 :‬تاريخه ‪1433/08/12 :‬هـ‬\n                   ‫رقم الدعوى ‪33491322 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 3441032‬تاريخه‪1434/2/19:‬هـ‬\n\n\n\n‫ســرقة ‪ -‬كســر زجــاج ســيارة وســرقة محتوياتهــا‪ -‬محاضــر اإلرشــاد ‪-‬‬\n‫طلــب التشــديد يف العقوبــة ‪ -‬التعزيــر ألجــل الشــبهة القويــة‪ -‬تشــكيل‬\n‫عصابــي ‪ -‬تشــديد العقوبــة‪ -‬رجــوع عــن اإلقــرار بدعــوى اإلكــراه ‪-‬‬\n                              ‫التعزيــر بالســجن واجللــد وأخــذ التعهــد‪.‬‬\n\n\n\n\n                  ‫‪-1‬قول اهلل تعالى‪َ ( :‬وال ُت ْف ِس ُدوا ِف األرض َب ْعد َ ِإ ْص ِ‬\n             ‫الح َها)‬\n                                                  ‫‪-2‬قوله تعالى‪َ ( :‬و َال َت ْع َت ُدو ْا ِإ َّن ّ َ‬\n                     ‫الل َال ُي ِح ِّب ْالُ ْع َتدِ َ‬\n                   ‫ين)‬\n‫‪-3‬قولــه صلــى اهلل عليــه وســلم (كل املســلم علــى املســلم حــرام دمــه‬\n                                                                                    ‫ومالــه وعرضــه)‬\n\n\n\n\n‫توجيه االتهام للمدعى عليهم الثالثة بتكوين عصابة لسرقة السيارات‬\n‫وقيامهــم بالســرقة مــن عــدة ســيارات بعــد كســر زجاجها‪،‬حيــث وردت‬\n‫عــدة بالغــات ملركــز الشــرطة عــن تعــرض ســيارات املبلغــن لكســر‬\n‫الزجــاج و ســرقة مــا بداخــل الســيارة و بعثــرة محتوياتهــا ‪ ،‬بعــد البحــث‬\n‫والتحــري مت القبــض علــى املدعــى عليهــم و اعترفــوا مبــا نســب إليهــم و‬\n‫قامــوا باإلرشــاد علــى مواقــع الســيارات التــي قامــوا بتكســير زجاجهــا‬\n‫والســرقة منهــا‪ ،‬طلــب املدعــي إثبــات مــا أســند إليهــم و احلكــم عليهــم‬\n\n                                                                                                       ‫‪14‬‬\n\f     ‫بعقوبــة تعزيريــة و التشــديد عليهــم لقــاء كثــرة وقــوع جرائــم ســرقة‬\n     ‫الســيارات يف الوقــت الراهــن و لكــون فعلهــم انطــوى علــى تكويــن‬\n     ‫عصابــي يف الســرقة‪ ،‬أنكــر املدعــى عليهــم مــا نســب إليهــم ‪ ،‬اســتند‬\n     ‫املدعــي العــام يف دعــواه علــى اعترافاتهــم املصدقــة شــرعاً‪ ،‬رجــع املدعى‬\n     ‫عليهــم عــن اعترافاتهــم ودفعهــم بأنهــا صــدرت حتــت اإلكــراه‪ ،‬وصــدر‬\n     ‫احلكــم بعــدم ثبــوت إدانــة املدعــى عليهــم بتكويــن عصابــة لســرقة‬\n     ‫الســيارات و كســر زجاجهــا و ســرقة مــا بداخلهــا تعزيرهــم لتوجــه‬\n     ‫التهمــة القويــة بالســجن واجللــد وأخــذ التعهــد ‪ ،‬صــدق احلكــم مــن‬\n                                                         ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n     ‫ـدي أنــا‬\n            ‫احلمــدهلل وحــده والصــاة والســام علــى َمــنْ النبــي بعــده وبعــد فلـ َّ‬\n     ‫ـاء علــى املعاملــة الــواردة‬\n                                  ‫(‪ )....‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n     ‫إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء برقــم هـ ف‬\n     ‫‪ 8371/2/2‬وتاريخ‪1433/07/27‬ه ـ واملقيــدة بهــذه احملكمــة‬\n     ‫برقم‪331419157‬وتاريخ‪1433/07/28‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n     ‫الرئيــس برقم‪33491322‬وتاريخ‪1433/07/28‬ه ـ فتحت اجللســة األولى‬\n     ‫يــوم االربعــاء ‪1433/07/30‬ه ـ الســاعة احلاديــة عشــرة والنصــف وفيهــا‬\n     ‫حضــر املدعــي العــام (‪ )....‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا‬\n     ‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة‬\n     ‫ا‪:‬‬  ‫األحســاء ذي الرقــم (‪ )....‬والتاريــخ ‪1431/1/5‬ه ـ وقـ ّـرر دعــواه قائـ ً‬\n     ‫بصفتــي مدعيـ ًا عامـ ًا يف دائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي‬\n     ‫علــى كل مــن ‪ ، )....(- 1 :‬البالــغ مــن العمــر (‪ )23‬عامـاً‪ ،‬غيــر محصــن‬\n\n‫‪15‬‬\n\f‫‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب الســجل املدنــي رقــم (‪ ، )....‬متســبب ‪،‬‬\n‫أوقــف بتاريــخ ‪1433/4/8‬ه ـ وأحيــل لشــعبة ســجن محافظــة األحســاء‬\n‫ا لديهــم برقــم (‪ )....‬مبوجــب املــادة (‪ )112‬مــن نظــام‬             ‫وســجل نزي ـ ً‬\n‫اإلجــراءات اجلزائيــة الفقــرة ( ‪ ) 5‬مــن القــرار الــوزاري ( ‪ ) 1900‬وتاريــخ‬\n‫‪1428/7/9‬ه ـ يســكن (‪ ، )....(-2.)....‬البالــغ مــن العمــر (‪ )22‬عامـ ًا ‪،‬‬\n‫غيــر محصــن ‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب الســجل املدنــي رقــم (‪، )....‬‬\n‫متســبب ‪ ،‬أوقــف بتاريــخ ‪1433/4/6‬ه ـ وأحيــل لشــعبة ســجن محافظــة‬\n‫ا لديهــم برقــم (‪ )....‬مبوجــب املــادة (‪ )112‬مــن‬       ‫األحســاء وســجل نزي ـ ً‬\n‫نظــام اإلجــراءات اجلزائيــة الفقــرة ( ‪ ) 5‬مــن القــرار الــوزاري ( ‪) 1900‬‬\n‫وتاريــخ ‪1428/7/9‬ه ـ يســكن (‪ ، )....( -3.)....‬البالــغ مــن العمــر (‪)22‬‬\n‫عامـ ًا ‪ ،‬غيــر محصــن ‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب الســجل املدنــي رقــم‬\n‫(‪ ، )....‬متســبب ‪ ،‬أوقــف بتاريــخ ‪1433/4/6‬ه ـ وأحيــل لشــعبة ســجن‬\n‫ا لديهــم برقــم (‪ )....‬مبوجــب املــادة‬   ‫محافظــة األحســاء وســجل نزي ـ ً‬\n‫(‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة الفقــرة ( ‪ ) 5‬مــن القــرار الــوزاري‬\n‫( ‪ ) 1900‬وتاريــخ ‪1428/7/9‬ه ـ يســكن (‪.)....‬وقائــع القضيــة ذات‬\n‫الرقــم (‪ : ) 3339700408‬البــاغ األول ‪ :‬بتاريــخ ‪1433/3/13‬ه ـ ورد‬\n‫تقريــر دوريــة األمــن رقــم (‪ )....‬املتضمــن بــاغ (‪ )....‬عــن تعــرض ســيارته‬\n‫التــي مــن نــوع (‪ )....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة (‪ )....‬لكســر الزجاجة‬\n‫األماميــة مــن اجلهــة اليســرى أثنــاء وقوفهــا أمــام منزلــه بحــي (‪ )....‬وســرقة‬\n‫منهــا جــوال مــن نــوع (‪ .)....‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع‬\n‫احلادثــة حيــث اتضــح أنهــا تقــع بحــي (‪ )....‬وشــوهدت الســيارة املذكــورة‬\n‫واقفــة أمــام منــزل املبلــغ املذكــور ‪ ،‬وشــوهدت الزجاجــة األماميــة جهــة‬\n‫اليســار لبــاب الســائق متعرضــة للكســر حيث شــوهد بعثــرة باحملتويات‬\n\n\n                                                                                           ‫‪16‬‬\n\f     ‫الداخليــة للســيارة ‪.‬املالحقــة والتحــري ‪1 :‬ـ مت مكاتبــة شــعبة التحريــات‬\n     ‫والبحــث اجلنائــي برقــم‪ .........‬يف ‪1433/3/13‬ه ـ للتحــري عــن القضيــة‬\n     ‫وكشــف اجلنــاة ‪2.‬ـ ورد كتــاب ســعادة مديــر إدارة شــؤون األمــن رقــم‬\n     ‫‪ 1524/9/21‬يف ‪1433/3/30‬ه ـ املتضمــن ورود معلومــات لديهــم تشــير‬\n     ‫كل من املدعو‪ )....( /‬و‪ )....( /‬و‪ )....( /‬وشــخصان‬         ‫إلى احتمالية تورط ٍ‬\n     ‫آخــران مجهــوالن بتلــك الســرقة ‪.‬وبضبــط أقــوال املدعــو ‪ )....( :‬أفــاد عــن‬\n     ‫تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة (‪)....‬‬\n     ‫لكســر الزجاجــة األماميــة مــن اجلهــة اليســرى أثنــاء وقوفهــا أمــام منزلــه‬\n     ‫بحــي (‪ )....‬وســرقة منهــا جــوال مــن نــوع (‪. )....‬وباســتجواب املدعــى عليــه‬\n     ‫األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه رفــق‬\n     ‫زمالئــه املدعــى عليهمــا واحلــدث‪ )....( /‬واحلــدث ‪ )....(/‬علــى دراجاتهــم‬\n     ‫الناريــة إلــى حــي (‪ )....‬وكســر الزجاجــة األماميــة مــن اجلهــة اليســرى‬\n     ‫لســيارة املبلــغ املذكــورة أثنــاء وقوفهــا أمــام منزلــه بحــي (‪ )....‬وســرقة‬\n     ‫منهــا جــوال مــن نــوع (‪.)....‬وباســتجواب املدعــى عليــه الثانــي أقــر مبــا‬\n     ‫نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه األول مــن حيــث‬\n     ‫الوصــف والوقــت والكيفية‪.‬وباســتجواب املدعــى عليــه الثالــث أقــر مبــا‬\n     ‫نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران مــن حيث‬\n     ‫الوصــف والوقــت والكيفية‪.‬املواجه ــة ‪ :‬مت مواجهــة كال مــن املدعــى‬\n     ‫عليــه األول بزميليــه الثانــي والثالــث مبــا جــاء يف اعترافــه حيــث أنكــر‬\n     ‫املذكــوران يف البدايــة مــا نســب إليهمــا مــن اتهــام ‪ ،‬وباســتمرار‬\n     ‫مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضية‪.‬وقائــع القضيــة ذات‬\n     ‫الرقــم (‪: )3339700417‬البــاغ الثانــي ‪ :‬بتاريــخ ‪1433/3/20‬ه ـ أبلــغ‬\n     ‫املواطــن‪ )....( /‬عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪)....‬‬\n\n\n‫‪17‬‬\n\f‫رقــم اللوحــة (‪ )....‬لكســر الزجاجــة األماميــة مــن اجلهة اليســرى وســرقة‬\n‫منهــا جوالــن نــوع (‪. )....‬املعاينـ ــة‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع‬\n‫احلادثــة حيــث اتضــح أنــه يقــع (‪ ، )....‬وشــوهدت الســيارة املذكــورة‬\n‫واقفــة أمــام منــزل املبلــغ املذكــور ‪ ،‬وشــوهدت الزجاجــة األماميــة جهــة‬\n‫اليســار لبــاب الســائق متعرضــة للكســر حيث شــوهد بعثــرة باحملتويات‬\n‫الداخلية للســيارة وبضبط أقوال املدعو ‪ )....( :‬أفاد عن تعرض ســيارته‬\n‫التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة (‪ )....‬لكســر الزجاجــة‬\n‫األمامية من اجلهة اليسرى وسرقة منها جوالني نوع (‪ . )....‬وباستجواب‬\n‫املدعــى عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ‬\n‫اجتــه رفــق زمالئــه املدعــى عليهمــا واحلــدث‪ )....( /‬واحلــدث‪ )....( /‬علــى‬\n‫دراجاتهــم الناريــة إلــى حــي (‪ )....‬وكســر الزجاجــة األماميــة مــن اجلهــة‬\n‫اليســرى لســيارة املبلــغ املذكــورة أثنــاء وقوفهــا أمــام منزلــه بحــي (‪)....‬‬\n‫وســرقة منهــا جوالــن مــن نــوع (‪. )....‬وباســتجواب املدعــى عليــه الثانــي‬\n‫أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن‬\n‫حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال مــن‬\n‫املدعــى عليــه األول بزميليــه الثانــي والثالــث مبــا جــاء يف اعترافــه حيــث‬\n‫أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن اتهــام وباســتمرار‬\n‫مواجهتهمــا بزميلهمــا املذكــور اعتــرف الثانــي بالقضيــة ‪( .‬هــذا ومبا أن‬\n‫األســلوب اإلجرامــي للقضيتــن الســابقتني متماثلــن مت التحقيــق مــع‬\n‫املدعــى عليهــم يف القضايــا املســجلة ضــد مجهــول وذات األســلوب‬\n‫اإلجرامــي املماثــل لألســلوب املنتهــج مــن قبلهــم والتــي قــد أثــارت الرعــب‬\n‫واخلــوف بــن املواطنــن وأصحــاب الســيارات املتعرضــة للتكســير‬\n‫والســرقة‪ ،‬وبعــون مــن اهلل تعالــى اعتــرف املذكــورون بعــدة قضايــا علــى‬\n\n\n                                                                                        ‫‪18‬‬\n\f     ‫النحــو التالي)‪:‬البــاغ األول ‪ :‬بــاغ املواطــن‪ )....(/‬يســكن حــي (‪)....‬‬\n     ‫عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة‬\n     ‫(‪ )....‬لكســر الزجاجــة األماميــة مــن اجلهــة اليســرى وســرقة منهــا مبلــغ‬\n     ‫وقــدرة ســتمائة ريــال أثنــاء وقوفهــا أمــام منزلــه بحــي (‪.)....‬املعاينـ ــة‪ :‬مت‬\n     ‫االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح أنهــا تقــع بحــي (‪)....‬‬\n     ‫‪ ،‬وشــوهدت الســيارة املذكــورة واقفــة أمــام منــزل املبلــغ املذكــور ‪،‬‬\n     ‫وشــوهدت الزجاجــة األماميــة جهــة اليســار لبــاب الســائق متعرضــة‬\n     ‫للكســر حيــث شــوهد بعثــرة باحملتويــات الداخليــة للســيارة ‪.‬وبضبــط‬\n     ‫أقــوال املدعــو ‪ )....( :‬أفــاد عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪)....‬‬\n     ‫اللــون (‪ )....‬رقــم اللوحــة (‪ )....‬لكســر الزجاجــة األماميــة مــن اجلهــة‬\n     ‫اليســرى وســرقة منهــا مبلــغ وقــدرة ســتمائة ريــال أثنــاء وقوفهــا أمــام‬\n     ‫منزلــه بحــي (‪.)....‬وباســتجواب املدعــى عليــه األول أقــر أنــه يف حوالــي‬\n     ‫الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه رفــق زمالئــه‪ )....(/‬و‪)....(/‬‬\n     ‫واحلــدث‪ )....( /‬واحلــدث‪ )....( /‬علــى دراجاتهــم الناريــة إلــى حــي (‪)....‬‬\n     ‫وقامــوا بكســر الزجاجــة األماميــة مــن اجلهــة اليســرى لســيارة املبلــغ‬\n     ‫املذكــورة أثنــاء وقوفهــا أمــام منزلــه بحــي (‪ )....‬وســرقة منهــا مبلــغ‬\n     ‫ســتمائة ريــال‪ .‬وباســتجواب املدعــى عليــه الثانــي أقــر مبــا نســب إليــه‬\n     ‫وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن حيــث الوصــف‬\n     ‫والوقــت والكيفيــة‪ .‬وباســتجواب املدعــى عليــه الثالــث أقــر مبــا نســب‬\n     ‫إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران مــن حيــث‬\n     ‫الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال مــن املدعــى‬\n     ‫عليــه األول بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث أنكــر‬\n     ‫املذكــوران يف البدايــة مــا نســب إليهما من اتهام وباســتمرار مواجهتهما‬\n\n\n‫‪19‬‬\n\f‫بزميلهمــا املذكــور اعترفــا بالقضيــة‪ .‬البــاغ الثانــي‪ -:‬بــاغ املواطــن‪/‬‬\n‫(‪ )....‬عــن تعــرض ســيارته التــي مــن نــوع (‪ )....‬اللــون (‪)....‬م(‪ )....‬رقــم‬\n‫اللوحــة (‪ )....‬لكســر الزجاجــة األماميــة مــن اجلهــة اليســرى وســرقة‬\n‫إثباتــات شــخصية للمبلــغ أثنــاء وقوفهــا أمــام منزلــه بحــي (‪. )....‬املعاينـ ــة‪:‬‬\n‫مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح أنهــا تقــع بحــي‬\n‫(‪ )....‬شــوهدت الســيارة املذكــورة واقفــة أمــام منــزل املبلــغ املذكــور‬\n‫وشــوهدت الزجاجــة األماميــة جهــة اليســار لبــاب الســائق متعرضــة‬\n‫للكســر حيــث شــوهد بعثــرة باحملتويــات الداخليــة للســيارة ‪.‬وبضبــط‬\n‫أقــوال املبلــغ ‪ )....( :‬أفــاد عــن تعــرض ســيارته التــي مــن نــوع (‪ )....‬اللــون‬\n‫(‪)....‬م(‪ )....‬رقــم اللوحــة (‪ )....‬لكســر الزجاجــة األماميــة مــن اجلهــة‬\n‫اليســرى وســرقة إثباتــات شــخصية للمبلــغ أثنــاء وقوفهــا أمــام منزلــه‬\n‫بحــي (‪.)....‬وباســتجواب املدعــى عليــه األول أقــر أنــه يف حوالــي الســاعة‬\n‫الثانيــة صبــاح يــوم البــاغ اجتــه رفــق زمالئــه‪ )....(/‬و‪ )....(/‬واحلــدث‪/‬‬\n‫(‪ )....‬واحلــدث‪ )....( /‬علــى دراجاتهــم الناريــة إلــى حــي (‪ )....‬وقامــوا‬\n‫بكســر الزجاجــة األماميــة مــن اجلهــة اليســرى لســيارة املبلــغ املذكــورة‬\n‫أثنــاء وقوفهــا أمــام منزلــه بحــي (‪ )....‬وســرقة محفظتــه ‪ ،‬وبعــد التأكــد‬\n‫مــن عــدم وجــود مبالــغ بداخلهــا مت رميهــا‪ .‬وباســتجواب املدعــى عليــه‬\n‫الثانــي أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه‬\n‫املذكــور مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬وباســتجواب املدعــى‬\n‫عليــه الثالــث أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه‬\n‫املذكــوران مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة‪ :‬مت‬\n‫مواجهــة كال مــن املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء يف‬\n‫اعترافــه حيــث أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن اتهام‬\n\n\n                                                                                         ‫‪20‬‬\n\f     ‫وباســتمرار مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪ .‬البــاغ‬\n     ‫الثالــث ‪- :‬بــاغ املواطــن‪ )....(/‬عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬‬\n     ‫م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة (‪ )....‬لكســر الزجاجــة األماميــة مــن‬\n     ‫اجلهــة اليمنــى وســرقة محفظتــه وبداخلهــا اإلثباتــات الشــخصية أثنــاء‬\n     ‫وقوفهــا أمــام منزلــه بحــي (‪.)....‬املعاينـ ــة‪ :‬مت االنتقــال فــور البــاغ إلــى‬\n     ‫موقــع احلادثــة حيــث اتضــح أنهــا تقــع بحــي (‪ )....‬وقــد شــوهدت الســيارة‬\n     ‫املذكــورة واقفــة أمــام منــزل املبلــغ املذكــور ‪ ،‬وشــوهدت الزجاجــة‬\n     ‫األماميــة جهــة اليمــن لبــاب الراكــب متعرضــة للكســر حيــث شــوهد‬\n     ‫بعثــرة باحملتويــات الداخليــة للســيارة ‪.‬وبضبــط أقــوال املبلــغ ‪ )....( :‬أفــاد‬\n     ‫أن ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة (‪)....‬‬\n     ‫تعرضــت لكســر الزجاجــة األماميــة مــن اجلهــة اليمنــى وســرقة محفظتــه‬\n     ‫وبداخلهــا اإلثباتــات الشــخصية أثنــاء وقوفهــا أمــام منزلــه بحــي‬\n     ‫(‪.)....‬وباســتجواب املدعــى عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة‬\n     ‫صبــاح يــوم البــاغ اجتــه رفــق زمالئــه‪ )....(/‬و‪ )....(/‬واحلــدث(‪ )....‬واحلدث‬\n     ‫‪ )....(/‬علــى دراجاتهــم الناريــة إلــى حــي (‪ )....‬وكســر الزجاجــة األماميــة‬\n     ‫مــن اجلهــة اليمنــى لســيارة املبلــغ املذكــورة أثنــاء وقوفهــا أمــام منزلــه‬\n     ‫بحــي (‪ )....‬وســرقة محفظتــه وبعــد التأكــد مــن عــدم وجــود مبالــغ‬\n     ‫بداخلهــا مت رميهــا‪ .‬وباســتجواب املدعــى عليــه الثانــي أقــر مبــا نســب إليــه‬\n     ‫وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن حيــث الوصــف‬\n     ‫والوقــت والكيفيــة‪ .‬وباســتجواب املدعــى عليــه الثالــث أقــر مبــا نســب‬\n     ‫إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران مــن حيــث‬\n     ‫الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة‪ :‬مت مواجهــة كال مــن املدعــى‬\n     ‫عليــه األول بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث أنكــر‬\n\n\n‫‪21‬‬\n\f‫املذكــوران يف البدايــة مــا نســب إليهما من اتهام وباســتمرار مواجهتهما‬\n‫بزميلهمــا املذكــور اعترفــا بالقضيــة‪ .‬البــاغ الرابــع ‪- :‬بــاغ املواطــن‪/‬‬\n‫(‪ )....‬عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم‬\n‫اللوحــة (‪ )....‬لكســر الزجاجــة اخللفيــة مــن اجلهــة اليمنــى وســرقة‬\n‫اإلثباتــات الشــخصية أثنــاء وقوفهــا بحــي (‪.)....‬املعاينـ ــة‪ :‬مت االنتقــال فــور‬\n‫البــاغ إلــى موقــع احلادثــة حيــث اتضــح أنهــا تقــع بحــي (‪ )....‬شــوهدت‬\n‫الســيارة املذكــورة واقفــة أمــام منــزل املبلــغ املذكــور ‪ ،‬وشــوهدت‬\n‫الزجاجــة اخللفيــة جهــة اليمــن لبــاب الراكــب متعرضــة للكســر حيــث‬\n‫شــوهد بعثــرة باحملتويــات الداخليــة للســيارة‪ .‬وبضبــط أقــوال املبلــغ ‪:‬‬\n‫(‪ )....‬أفــاد أن ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة‬\n‫(‪ )....‬تعرضــت لكســر الزجاجــة اخللفيــة مــن اجلهــة اليمنــى وســرقة‬\n‫اإلثباتــات الشــخصية أثنــاء وقوفهــا بحــي (‪ .)....‬وباســتجواب املدعــى‬\n‫عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه‬\n‫رفــق زمالئــه‪ )....(/‬و‪ )....(/‬واحلــدث‪ )....( /‬واحلــدث‪ )....( /‬على دراجاتهم‬\n‫الناريــة إلــى حــي (‪ )....‬وكســر الزجاجــة اخللفيــة مــن اجلهــة اليمنــى‬\n‫لســيارة املبلــغ املذكــورة أثنــاء وقوفهــا أمــام منزلــه بحــي (‪ )....‬وســرقة‬\n‫محفظتــه ‪ ،‬وبعــد التأكــد مــن عــدم وجــود أي مبالــغ بداخلهــا مت رميهــا‪.‬‬\n‫وباســتجواب املدعــى عليــه الثانــي أقــر مبــا نســب إليــه وجــاءت أقوالــه‬\n‫مطابقــة ألقــوال زميلــه املذكــور مــن حيــث الوصــف والوقــت والكيفية‪.‬‬\n‫وباســتجواب املدعــى عليــه الثالــث أقــر مبــا نســب إليــه وجــاءت أقوالــه‬\n‫مطابقــة ألقــوال زميليــه املذكــوران مــن حيــث الوصــف والوقــت‬\n‫والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال مــن املدعــى عليــه األول بزميليه‬\n‫املذكــوران مبــا جــاء يف اعترافــه حيــث أنكــر املذكــوران يف البدايــة‬\n\n\n                                                                                          ‫‪22‬‬\n\f     ‫مــا نســب إليهمــا مــن اتهــام وباســتمرار مواجهتهمــا بزميلهمــا املذكــور‬\n     ‫اعترفــا بالقضيــة‪ .‬البــاغ اخلامــس ‪ :‬بــاغ املواطــن‪ )....(/‬عــن تعــرض‬\n     ‫ســيارته التــي مــن نــوع (‪)....‬و(‪ )....‬اللــون (‪)....‬رقــم اللوحــة (‪ )....‬لكســر‬\n     ‫الزجاجــة األماميــة مــن جهــة الســائق وســرقة منهــا محفظتــه وبداخلهــا‬\n     ‫بطاقــة األحــوال اخلاصــة بــه ورخصــة القيــادة واســتمارة الســيارة أثنــاء‬\n     ‫وقوفهــا بحــي (‪.)....‬املعاينـ ــة‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة‬\n     ‫حيــث اتضــح أنهــا تقــع بحــي (‪ )....‬شــوهدت الســيارة املذكــورة واقفــة‬\n     ‫أمــام منــزل املبلــغ املذكــور وشــوهدت الزجاجــة األماميــة جهــة اليســار‬\n     ‫لبــاب الســائق متعرضــة للكســر حيــث شــوهد بعثــرة باحملتويــات‬\n     ‫الداخليــة للســيارة‪ .‬وبضبــط أقــوال املبلــغ (‪ )....‬أفــاد عــن تعــرض ســيارته‬\n     ‫التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة (‪ )....‬لكســر الزجاجــة‬\n     ‫األماميــة مــن جهــة الســائق وســرقة منهــا محفظتــه وبداخلهــا بطاقــة‬\n     ‫األحــوال اخلاصــة بــه ورخصــة القيــادة واســتمارة الســيارة أثنــاء وقوفهــا‬\n     ‫بحــي (‪.)....‬وباســتجواب املدعــى عليــه األول أقــر أنــه يف حوالــي الســاعة‬\n     ‫الثانيــة صبــاح يــوم البــاغ اجتــه رفــق زمالئــه‪ )....(/‬و‪ )....(/‬واحلــدث‪/‬‬\n     ‫(‪ )....‬واحلــدث‪ )....( /‬علــى دراجاتهــم الناريــة إلــى حــي (‪ )....‬وكســر‬\n     ‫الزجاجــة اخللفيــة مــن اجلهــة اليمنــى لســيارة املبلــغ املذكــورة أثنــاء‬\n     ‫وقوفهــا أمــام منزلــه بحــي (‪ )....‬وســرقة محفظتــه ‪ ،‬وبعــد التأكــد مــن‬\n     ‫عــدم وجــود أي مبالــغ بداخلهــا مت رميهــا‪ .‬وباســتجواب املدعــى عليــه‬\n     ‫الثانــي أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه‬\n     ‫املذكــور مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬وباســتجواب املدعــى‬\n     ‫عليــه الثالــث أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه‬\n     ‫املذكــوران مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة‪ :‬مت‬\n\n\n‫‪23‬‬\n\f‫مواجهــة كال مــن املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء يف‬\n‫اعترافــه حيــث أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن اتهام‬\n                ‫وباستمرار مواجهتهما بزميلهما املذكور اعترفا بالقضية‪.‬‬\n‫البــاغ الســادس‪ :‬ـ بــاغ املواطــن‪ )....(/‬عــن تعــرض ســيارته التــي مــن نــوع‬\n‫(‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة (‪ )....‬لكســر الزجاجــة اخللفيــة مــن‬\n‫اجلهــة اليمنــى وســرقة جهــاز كمبيوتــر (الب تــوب ) مــن نــوع (‪ )....‬اللــون‬\n‫(‪)....‬أثنــاء وقوفهــا أمــام منزلــه بحــي (‪ .)....‬املعاينـ ــة ‪ :‬مت االنتقــال فــور‬\n‫البــاغ إلــى موقــع احلادثــة حيــث اتضــح أنهــا تقــع بحــي (‪ )....‬شــوهدت‬\n‫الســيارة املذكــورة واقفــة أمــام منــزل املبلــغ املذكــور ‪ ،‬وشــوهدت‬\n‫الزجاجــة اخللفيــة جهــة اليمــن لبــاب الســائق متعرضــة للكســر ‪ ،‬حيــث‬\n‫شــوهد بعثــرة باحملتويــات الداخليــة للســيارة ‪.‬وبضبــط أقــوال املبلــغ ‪:‬‬\n‫(‪ )....‬والــذي أفــاد عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون‬\n‫(‪ )....‬رقــم اللوحــة (‪ )....‬لكســر الزجاجــة اخللفيــة مــن اجلهــة اليمنــى‬\n‫وســرقة جهــاز كمبيوتــر ( الب تــوب ) مــن نــوع (‪ )....‬اللــون (‪ )....‬أثنــاء‬\n‫وقوفهــا أمــام منزلــه بحــي (‪.)....‬وباســتجواب املدعــى عليــه األول أقــر‬\n‫أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه رفــق زمالئــه‪/‬‬\n‫(‪ )....‬و‪ )....(/‬واحلــدث‪ )....( /‬واحلــدث ‪ )....(/‬علــى دراجاتهــم الناريــة إلــى‬\n‫حــي (‪ )....‬وكســر الزجاجــة اخللفيــة مــن اجلهــة اليمنــى لســيارة املبلــغ‬\n‫املذكــورة أثنــاء وقوفهــا أمــام منزلــه بحــي (‪ )....‬وســرقة جهــاز كمبيوتر‬\n‫(الب تــوب) مــن نــوع (‪ )....‬اللــون (‪.)....‬وباســتجواب املدعــى عليــه الثانــي‬\n‫أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن‬\n‫حيــث الوصــف والوقــت والكيفيــة‪ .‬وباســتجواب املدعــى عليــه الثالــث‬\n‫أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران‬\n\n\n                                                                                         ‫‪24‬‬\n\f     ‫مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة‪ :‬مت مواجهــة كال مــن‬\n     ‫املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث‬\n     ‫أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن اتهــام وباســتمرار‬\n     ‫مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪ .‬البــاغ الســابع‪ :‬بــاغ‬\n     ‫املواطــن ‪ )....( /‬عــن تعــرض ســيارته التــي مــن نــوع (‪ )....‬م(‪)....‬اللــون (‪)....‬‬\n     ‫رقــم اللوحــة (‪ )....‬لكســر الزجاجــة األماميــة مــن اجلهــة اليمنــى وســرقة‬\n     ‫مبلــغ عــدد ثــاث جــواالت اثنــان مــن نــوع (‪ )....‬والثالــث مــن نــوع (‪)....‬‬\n     ‫وســرقة هاردســك خارجــي أثنــاء وقوفهــا أمــام منزله بحي (‪ )....‬املعاينـ ــة‪:‬‬\n     ‫مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح أنهــا تقــع بحــي‪،‬‬\n     ‫وشــوهدت الســيارة املذكــورة واقفــه أمــام منــزل املبلــغ املذكــور‬\n     ‫وشــوهدت الزجاجــة األماميــة جهــة اليمــن متعرضــة للكســر حيــث‬\n     ‫شــوهدت بعثــرة باحملتويــات الداخليــة للســيارة‪ .‬وبضبــط أقــوال املبلــغ ‪:‬‬\n     ‫(‪ )....‬أفــاد عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم‬\n     ‫اللوحــة (‪ )....‬لكســر الزجاجــة األماميــة مــن اجلهــة اليمنــى وســرقة مبلــغ‬\n     ‫عــدد ثــاث جــواالت اثنــان مــن نــوع (‪ )....‬والثالــث مــن نــوع (‪ )....‬وســرقة‬\n     ‫هاردســك خارجــي أثنــاء وقوفهــا أمــام منزلــه بحــي (‪.)....‬وباســتجواب‬\n     ‫املدعــى عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ‬\n     ‫أجتــه رفــق زمالئــه‪ )....(/‬و‪ )....(/‬واحلــدث‪ )....( /‬واحلــدث‪ )....(/‬علــى‬\n     ‫دراجاتهــم الناريــة إلــى حــي (‪ )....‬وكســر الزجاجــة األماميــة مــن اجلهــة‬\n     ‫األماميــة اليمنــى ‪ ،‬وســرقة ثــاث جــواالت اثنــان مــن نــوع (‪ )....‬والثالــث‬\n     ‫مــن نــوع (‪ )....‬وســرقة هاردســك خارجــي أثنــاء وقوفهــا أمــام منزلــه‬\n     ‫بحي(‪.)....‬وباســتجواب املدعــى عليــه الثانــي أقــر مبــا نســب إليــه وجــاءت‬\n     ‫أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن حيــث الوصــف والوقــت‬\n\n\n‫‪25‬‬\n\f‫والكيفيــة‪ .‬وباســتجواب املدعــى عليــه الثالــث أقــر مبــا نســب إليــه‬\n‫وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران مــن حيــث الوصــف‬\n‫والوقــت والكيفيــة‪ .‬املواجه ــة‪ :‬مت مواجهــة كال مــن املدعــى عليــه األول‬\n‫بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث أنكــر املذكــوران يف‬\n‫البدايــة مــا نســب إليهمــا مــن اتهــام ‪ ،‬وباســتمرار مواجهتهمــا بزميلهمــا‬\n‫املذكــور اعترفــا بالقضيــة‪ .‬البــاغ الثامــن‪ :‬بــاغ املواطــن ‪ )....(/‬عــن‬\n‫تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة(‪)....‬‬\n‫لكســر الزجاجــة األماميــة مــن جهــة الســائق وســرقة مبلــغ وقــدره مائتــا‬\n‫ريــال ومحفظتــه وبداخلهــا اإلثباتــات الشــخصية‪ .‬املعاينـ ــة ‪ :‬مت االنتقــال‬\n‫فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح أنهــا تقــع بحــي (‪ )....‬حيــث‬\n‫شــوهدت الســيارة املذكــورة واقفــة أمــام منــزل املبلــغ املذكــور ‪،‬‬\n‫وشــوهدت الزجاجــة األماميــة جهــة اليســار متعرضــة للكســر ‪ ،‬حيــث‬\n‫شــوهدت بعثــره باحملتويــات الداخليــة للســيارة ‪ .‬وبضبــط أقــوال املبلــغ‬\n‫‪)....( :‬أفــاد عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪)....‬‬\n‫رقــم اللوحــة (‪ )....‬لكســر الزجاجــة األماميــة مــن جهــة الســائق وســرقة‬\n‫مبلــغ وقــدره مائتــا ريــال ومحفظتــه وبداخلهــا اإلثباتــات الشــخصية‬\n‫‪.‬وباســتجواب املدعــى عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة‬\n‫صبــاح يــوم البــاغ اجتــه رفــق زمالئــه‪ )....(/‬و‪ )....(/‬واحلــدث‪)....( /‬‬\n‫واحلــدث ‪ )....( /‬علــى دراجاتهــم الناريــة إلــى حــي (‪ )....‬وكســر الزجاجــة‬\n‫األماميــة مــن جهــة الســائق وســرقة مبلــغ وقــدره مائتــا ريــال ومحفظتــه‬\n‫وبداخلهــا اإلثباتــات الشــخصية ورمــي احملفظــة بعــد التأكــد مــن عــدم‬\n‫وجــود أي مبالــغ ماليــة بداخلهــا ‪.‬وباســتجواب املدعــى عليــه الثانــي أقــر‬\n‫مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن‬\n\n\n                                                                                      ‫‪26‬‬\n\f     ‫حيــث الوصــف والوقــت والكيفيــة‪ .‬وباســتجواب املدعــى عليــه الثالــث‬\n     ‫أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران‬\n     ‫مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال‬\n     ‫مــن املدعــى عليــه األول بزميليــه املذكــوران مباجــاء يف اعترافــه حيــث‬\n     ‫أنكــر املذكــوران يف البدايــة مانســب إليهمــا مــن اتهــام وباســتمرار‬\n     ‫مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪ .‬البــاغ التاســع ‪:‬بــاغ‬\n     ‫املواطــن (‪)....‬عــن تعــرض ســيارته التــي مــن نــوع (‪ )....‬صنــع (‪ )....‬اللــون‬\n     ‫(‪ )....‬رقــم اللوحــة (‪ ).........‬لكســر الزجاجــة األماميــة مــن اجلهــة اليمنــى‬\n     ‫وســرقة محفظتــه وبداخلهــا اإلثباتــات الشــخصية أثنــاء وقوفهــا بحــي‬\n     ‫(‪.)....‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح‬\n     ‫أنهــا تقــع بحــي ‪ ،‬وقــد شــوهدت الســيارة املذكــورة واقفــة أمــام منــزل‬\n     ‫املبلــغ املذكــور ‪ ،‬وشــوهدت الزجاجــة األماميــة جهــة اليســار متعرضــة‬\n     ‫للكســر حيــث شــوهد بعثــره باحملتويــات الداخليــة للســيارة ‪.‬وبضبــط‬\n     ‫أقــوال املبلــغ ‪ )....( :‬أفــاد عــن تعــرض ســيارته التي من نوع (‪ )....‬صنع عام‬\n     ‫(‪ )....‬اللــون (‪)....‬رقــم اللوحــة (‪ )....‬لكســر الزجاجــة األماميــة مــن اجلهــة‬\n     ‫اليمنــى وســرقة محفظتــه وبداخلهــا اإلثباتــات الشــخصية‪ .‬وباســتجواب‬\n     ‫املدعــى عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ‬\n     ‫اجتــه رفــق زمالئــه‪ ........./‬و‪ ........./‬واحلــدث‪ ......... /‬واحلــدث ‪........./‬‬\n     ‫علــى دراجاتهــم الناريــة إلــى حــي (‪ )....‬وكســر الزجاجــة األماميــة‬\n     ‫مــن جهــة اليســار وســرقة محفظتــه وبداخلهــا اإلثباتــات الشــخصية‬\n     ‫ورمــي احملفظــة بعــد التأكــد مــن عــدم وجــود أي مبالــغ ماليــة بداخلهــا‬\n     ‫‪.‬وباســتجواب املدعــى عليــه الثانــي أقــر مبــا نســب إليــه وجــاءت أقوالــه‬\n     ‫مطابقــة ألقــوال زميلــه املذكــور مــن حيــث الوصــف والوقــت والكيفية‪.‬‬\n\n\n‫‪27‬‬\n\f‫وباســتجواب املدعــى عليــه الثالــث أقــر مبــا نســب إليــه وجــاءت أقوالــه‬\n‫مطابقــة ألقــوال زميليــه املذكــوران مــن حيــث الوصــف والوقــت‬\n‫والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال مــن املدعــى عليــه األول بزميليه‬\n‫املذكــوران مباجــاء يف اعترافــه حيــث أنكــر املذكــوران يف البدايــة‬\n‫مانســب إليهمــا مــن اتهــام وباســتمرار مواجهتهمــا بزميلهمــا املذكــور‬\n                                                                 ‫اعترفــا بالقضيــة‪.‬‬\n‫البــاغ العاشــر ‪ - :‬بــاغ املواطــن ‪........./‬عــن تعــرض ســيارته التــي‬\n‫مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة (‪ ).........‬لكســر الزجاجــة‬\n‫األماميــة مــن اجلهــة اليســرى أثنــاء وقوفهــا بحــي (‪ )....‬وبعثــرة محتوياتــه‬\n‫مــن الداخــل ‪.‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث‬\n‫اتضــح أنهــا تقــع بحــي (‪ ، )....‬وشــوهدت الســيارة املذكــورة واقفــه أمــام‬\n‫منــزل املبلــغ املذكــور ‪ ،‬وشــوهدت الزجاجــة األماميــة جهــة اليســار‬\n‫متعرضــة للكســر حيــث شــوهد بعثــرة باحملتويــات الداخليــة للســيارة‬\n‫‪.‬وبضبــط أقــوال املبلــغ ‪ )....( :‬أفــاد عــن تعــرض ســيارته التــي مــن نــوع‬\n‫(‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة (‪ )....‬لكســر الزجاجــة األماميــة‬\n‫مــن جهــة الســائق وســرقة مبلــغ وقــدره مائتــا ريــال ومحفظتــه وبداخلهــا‬\n‫اإلثباتات الشــخصية ‪.‬وباســتجواب املدعى عليه األول أقر أنه يف حوالي‬\n‫الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه رفــق زمالئــه‪ ........./‬و‪........./‬‬\n‫واحلــدث‪ ......... /‬واحلــدث ‪ ........./‬علــى دراجاتهــم الناريــة إلــى حــي ‪.........‬‬\n‫وكســر الزجاجــة األماميــة مــن جهــة الســائق وســرقة مبلــغ وقــدرة مائتــا‬\n‫ريــال ومحفظتــه وبداخلهــا اإلثباتــات الشــخصية ورمــي احملفظــة بعــد‬\n‫التأكــد مــن عــدم وجــود أي مبالــغ ماليــة بداخلهــا ‪.‬وباســتجواب املدعــى‬\n‫عليــه الثانــي أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه‬\n\n\n                                                                                          ‫‪28‬‬\n\f     ‫املذكــور مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬وباســتجواب املدعــى‬\n     ‫عليــه الثالــث أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه‬\n     ‫املذكــوران مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت‬\n     ‫مواجهــة كال مــن املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء يف‬\n     ‫اعترافــه حيــث أنكــر املذكــوران يف البدايــة مانســب إليهمــا مــن اتهــام‬\n     ‫وباســتمرار مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪ .‬البــاغ‬\n     ‫احلــادي عشــر ‪- :‬بــاغ املواطــن‪ ........./‬عــن تعــرض ســيارته التــي مــن نــوع‬\n     ‫(‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة ‪ .........‬لكســر الزجاجــة اخللفيــة مــن‬\n     ‫اجلهــة اليمنــى وســرقة اإلثباتــات الشــخصية أثنــاء وقوفهــا بحــي ‪.........‬‬\n     ‫‪.‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح‬\n     ‫أنهــا تقــع بحــي ‪ / .........‬وشــوهدت الســيارة املذكــورة واقفــة أمــام‬\n     ‫منــزل املبلــغ املذكــور وشــوهدت الزجاجــة اخللفيــة مــن اجلهــة اليمنــى‬\n     ‫متعرضــة للكســر حيــث شــوهد بعثــره باحملتويــات الداخليــة للســيارة‬\n     ‫‪.‬وبضبــط أقــوال املبلــغ ‪......... :‬أفــاد عــن تعــرض ســيارته التــي مــن نــوع‬\n     ‫(‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحة‪.........‬لكســر الزجاجــة اخللفيــة مــن‬\n     ‫اجلهــة اليمنــى وســرقة محفظتــه وبداخلهــا اإلثباتــات الشــخصية أثنــاء‬\n     ‫وقوفهــا بحــي ‪. .........‬وباســتجواب املدعــى عليــه األول‪ :‬أقــر أنــه يف‬\n     ‫حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه رفــق زمالئــه‪........./‬‬\n     ‫و‪ .........‬واحلــدث‪ .........‬واحلــدث‪ ........./‬علــى دراجاتهــم الناريــة إلــى حــي‬\n     ‫‪ .........‬وكســر الزجاجــة األماميــة مــن جهــة اليمــن وســرقة محفظتــه‬\n     ‫وبداخلهــا اإلثباتــات الشــخصية ‪ ،‬وبعــد التأكــد مــن عــدم وجــود أي‬\n     ‫مبالــغ ماليــه بداخلهــا قامــوا برميهــا‪ .‬وباســتجواب املدعــى عليــه الثانــي‬\n     ‫أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن‬\n\n\n‫‪29‬‬\n\f‫حيــث الوصــف والوقــت والكيفيــة‪ .‬باســتجواب املدعــى عليــه الثالــث‬\n‫أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران‬\n‫مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال‬\n‫مــن املدعــى عليــه األول بزميليــه املذكــوران مباجــاء يف اعترافــه حيــث‬\n‫أنكــر املذكــوران يف البدايــة مانســب إليهمــا مــن اتهــام وباســتمرار‬\n‫مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪ .‬البــاغ الثانــي عشــر‪:‬‬\n‫‪ -‬بــاغ املواطن‪................../‬عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬‬\n‫م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة‪ .........‬لكســر الزجاجــة اخللفيــة مــن اجلهــة‬\n‫اليمنــى وســرقة منــه (ام بــي ‪ ) 3‬وجــوال مــن نــوع (‪ )....‬أثنــاء وقوفهــا أمــام‬\n‫منزلــه بحــي ‪. .........‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة‬\n‫حيــث اتضــح أنهــا تقــع بحــي ‪ .........‬شــوهدت الســيارة املذكــورة واقفــة‬\n‫أمــام منــزل املبلــغ املذكــور وشــوهدت الزجاجــة اخللفية مــن اجلهة اليمنى‬\n‫متعرضــة للكســر حيــث شــوهد بعثــرة باحملتويــات الداخليــة للســيارة‬\n‫‪.‬وبضبــط أقــوال املبلــغ ‪......... :‬أفــاد عــن تعــرض ســيارته التــي مــن نــوع‬\n‫(‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة‪ .........‬لكســر الزجاجــة اخللفيــة مــن‬\n‫اجلهــة اليمنــى وســرقة منــه (ام بــي ‪ )3‬وجــوال مــن نــوع (‪ )....‬أثنــاء وقوفهــا‬\n‫أمــام منزلــه بحــي ‪ . .........‬وباســتجواب املدعــى عليــه األول أقــر أنــه‬\n‫يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه رفــق زمالئــه‪........./‬‬\n‫و‪ ........./‬واحلــدث‪ ......... /‬واحلــدث ‪ ........./‬علــى دراجاتهــم الناريــة إلــى‬\n‫حــي ‪ .........‬وكســر الزجاجــة اخللفيــة مــن جهــة اليمــن وســرقة منــه‬\n‫(ام بــي ‪ ) 3‬وجــوال مــن نــوع (‪. )....‬وباســتجواب املدعــى عليــه الثانــي‬\n‫أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن‬\n‫حيــث الوصــف والوقــت والكيفيــة‪ .‬وباســتجواب املدعــى عليــه الثالــث‬\n\n\n                                                                                             ‫‪30‬‬\n\f     ‫أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران‬\n     ‫مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال‬\n     ‫مــن املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث‬\n     ‫أنكــر املذكــوران يف البدايــة مــا ُنســب إليهمــا مــن اتهــام ‪ ،‬وباســتمرار‬\n                                ‫مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪.‬‬\n     ‫البــاغ الثالــث عشــر ‪ ، :‬بالغ‪.........‬عــن تعــرض ســيارته التــي مــن نــوع‬\n     ‫(‪)....‬م(‪ )....‬اللــون (‪)....‬رقــم اللوحــة ‪ .........‬لكســر الزجاجــة اخللفيــة مــن‬\n     ‫اجلهــة اليمنــى وســرقة منهــا عــدد جوالــن (‪ )....‬أثنــاء وقوفهــا بحــي ‪.........‬‬\n     ‫‪.‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح أنهــا‬\n     ‫تقــع بحــي ‪ ، .........‬وشــوهدت الســيارة املذكــورة واقفــة أمــام منــزل‬\n     ‫املبلــغ املذكــور وشــوهدت الزجاجــة اخللفيــة مــن اجلهــة اليمنــى متعــرض‬\n     ‫للكســر حيــث شــوهد بعثــرة باحملتويــات الداخليــة للســيارة‪ .‬وبضبــط‬\n     ‫أقــوال املبلــغ ‪......... :‬عــن تعــرض ســيارته التــي مــن نــوع (‪ )....‬م(‪ )....‬اللــون‬\n     ‫(‪ )....‬رقــم اللوحــة ‪ .........‬لكســر الزجاجــة اخللفيــة مــن اجلهــة اليمنــى‬\n     ‫وســرقة منهــا عــدد جوالــن (‪ )....‬أثنــاء وقوفهــا بحــي ‪. .........‬وباســتجواب‬\n     ‫املدعــى عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم‬\n     ‫البــاغ اجتــه رفــق زمالئــه‪ .........‬و‪ .........‬واحلــدث ‪ .........‬واحلــدث ‪.........‬‬\n     ‫علــى دراجاتهــم الناريــة إلــى حــي ‪ .........‬وكســر الزجاجــة اخللفيــة‬\n     ‫مــن جهــة اليمنــى وســرقة منهــا عــدد جوالــن (‪ )....‬أثنــاء وقوفهــا بحــي‬\n     ‫‪. .........‬وباســتجواب املدعــى عليــه الثانــي أقــر مبــا نســب إليــه وجــاءت‬\n     ‫أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن حيــث الوصــف والوقــت‬\n     ‫والكيفيــة‪ .‬وباســتجواب املدعــى عليــه الثالــث أقــر مبــا نســب إليــه‬\n     ‫وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران مــن حيــث الوصــف‬\n\n\n‫‪31‬‬\n\f‫والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال مــن املدعــى عليــه األول‬\n‫بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث أنكــر املذكــوران‬\n‫يف البدايــة مانســب إليهمــا مــن اتهــام وباســتمرار مواجهتهمــا بزميلهمــا‬\n‫املذكــور اعترفــا بالقضيــة‪ .‬البــاغ الرابــع عشــر ‪ :‬ـ املقيم‪.........‬أردنــي‬\n‫اجلنســية) عــن تعــرض ســيارته التــي مــن نــوع (‪ )....‬اللــون (‪)....‬م(‪)....‬‬\n‫رقــم اللوحــة‪ .........‬لكســر الزجاجــة األماميــة وبعثــرة مــا بداخلهــا أثنــاء‬\n‫وقوفهــا أمــام منزلــه بحــي ‪. .........‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى‬\n‫موقــع احلادثــة حيــث اتضــح أنهــا تقــع بحــي ‪ ، .........‬وشــوهدت الســيارة‬\n‫املذكــورة واقفــة أمــام منــزل املبلــغ ‪ ،‬وشــوهدت الزجاجــة األماميــة‬\n‫متعرضــة للكســر حيــث شــوهد بعثــره باحملتويــات الداخليــة للســيارة‬\n‫‪.‬وبضبــط أقــوال املبلــغ‪ )....( :‬عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬‬\n‫اللــون (‪)....‬م(‪ )....‬رقــم اللوحــة‪ .........‬لكســر الزجاجــة األماميــة وبعثــرة‬\n‫مــا بداخلهــا أثنــاء وقوفهــا أمــام منزلــه بحــي ‪ .........‬وباســتجواب املدعــى‬\n‫عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه‬\n‫رفــق زمالئــه‪ .........‬و‪ .........‬واحلــدث‪ .........‬واحلــدث‪ .........‬علــى دراجاتهــم‬\n‫الناريــة إلــى حــي ‪ .........‬وكســر الزجاجــة األماميــة للســيارة املذكــورة‬\n‫أثنــاء وقوفهــا بحــي ‪ .........‬وباســتجواب املدعــى عليــه الثانــي أقــر مبــا‬\n‫نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن حيــث‬\n‫الوصــف والوقــت والكيفيــة‪ .‬وباســتجواب املدعــى عليــه الثالــث أقــر‬\n‫مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران مــن‬\n‫حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال مــن‬\n‫املدعــى عليــه األول بزميليــه املذكــوران مباجــاء يف اعترافــه حيــث‬\n‫أنكــرا املذكــوران يف البدايــة مانســب إليهمــا مــن اتهــام وباســتمرار‬\n\n\n                                                                                            ‫‪32‬‬\n\f                                 ‫مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪.‬‬\n     ‫البــاغ اخلامــس عشــر ‪- :‬بــاغ املواطــن‪ ..............‬عــن تعــرض ســيارته‬\n     ‫التــي مــن نــوع (‪ )....‬اللــون (‪)....‬م(‪ )....‬رقــم اللوحــة (‪ ).........‬لكســر‬\n     ‫الزجاجــة اخللفيــة مــن اجلهــة اليمنــى وســرقة محفظتــه وبداخلهــا‬\n     ‫اإلثباتــات الشــخصية أثنــاء وقوفهــا أمــام منزلــه بحــي ‪ ..........‬املعاينـ ــة‪:‬‬\n     ‫مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح أنهــا تقــع بحــي‬\n     ‫‪ .........‬حيــث شــوهدت الســيارة املذكــورة واقفــة أمــام منــزل املبلــغ‬\n     ‫املذكــور وشــوهدت الزجاجــة اخللفيــة مــن اجلهــة اليمنــى متعرضــة‬\n     ‫للكســر حيــث شــوهد بعثــرة باحملتويــات الداخليــة للســيارة‪ .‬وبضبــط‬\n     ‫أقــوال املبلــغ ‪......... :‬عــن تعــرض ســيارته التــي مــن نــوع (‪ )....‬اللــون (‪)....‬‬\n     ‫م(‪ )....‬رقــم اللوحــة ‪ .........‬لكســر الزجاجــة اخللفيــة مــن اجلهــة اليمنــى‬\n     ‫وســرقة محفظتــه وبداخلهــا اإلثباتــات الشــخصية أثنــاء وقوفهــا أمــام‬\n     ‫منزلــه بحــي ‪ . .........‬وباســتجواب املدعــى عليــه األول أقــر أنــه يف حوالــي‬\n     ‫الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه رفــق زمالئــه‪ ........./‬و‪........./‬‬\n     ‫واحلــدث‪ ......... /‬واحلــدث ‪ ........./‬علــى دراجاتهــم الناريــة إلــى حــي ‪.........‬‬\n     ‫وكســر الزجاجــة اخللفيــة مــن اجلهــة اليمنــى للســيارة املذكــورة أثنــاء‬\n     ‫وقوفهــا بحــي ‪