أقــر مبــا نســب إليــه وجــاءت‬\n     ‫أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن حيــث الوصــف والوقــت‬\n     ‫والكيفيــة‪ .‬وباســتجواب املدعــى عليــه الثالــث أقــر مبــا نســب إليــه‬\n     ‫وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران مــن حيــث الوصــف‬\n     ‫والوقت والكيفية‪ .‬املواجهـة ‪ :‬مت مواجهة كال من بزميليه املذكوران‬\n     ‫مبــا جــاء يف اعترافــه حيــث أنكــر املذكــوران يف البدايــة مــا نســب‬\n     ‫إليهمــا مــن اتهــام وباســتمرار مواجهتهمــا بزميلهمــا املذكــور اعترفــا‬\n                                                                                      ‫بالقضيــة‪.‬‬\n     ‫البــاغ الثامــن عشــر ‪ - :‬بــاغ املواطــن‪ .............. /‬عــن تعــرض ســيارته‬\n\n\n‫‪35‬‬\n\f‫التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة ‪ .........‬لكســر‬\n‫الزجاجــة األماميــة مــن اجلهــة اليســرى وســرقة جــوال مــن نــوع (‪ )....‬أثنــاء‬\n‫وقوفهــا أمــام منزلــه بحــي ‪. .........‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ‬\n‫إلــى موقــع احلادثــة حيــث اتضــح أنهــا تقــع بحــي ‪ .........‬وشــوهدت‬\n‫الســيارة املذكــورة واقفــة أمــام منــزل املبلــغ املذكــور‪ ،‬وشــوهدت‬\n‫الزجاجــة األماميــة مــن جهــة اليســار متعرضــة للكســر حيــث شــوهد‬\n‫بعثــره باحملتويــات الداخليــة للســيارة‪ .‬وبضبــط أقــوال املبلــغ ‪ )....( :‬أفــاد‬\n‫عــن تعــرض ســيارته مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة ‪.........‬‬\n‫لكســر الزجاجــة األماميــة مــن اجلهــة اليســرى وســرقة جــوال مــن نــوع‬\n‫(‪ )....‬أثنــاء وقوفهــا بحــي ‪. .........‬وباســتجواب املدعــى عليــه األول أقــر‬\n‫أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه رفق زمالئــه‪.........‬‬\n‫و‪ .........‬واحلــدث ‪ .........‬واحلــدث‪ ........‬علــى دراجاتهــم الناريــة إلــى حــي‬\n‫‪ .........‬وكســر الزجاجــة اخللفيــة اليســار للســيارة املذكــورة وســرقة‬\n‫احملفظــة ورميهــا بعــد التأكــد مــن عــدم وجــود أي مبالــغ ماليــه فيهــا‬\n‫إثنــاء وقوفهــا بحــي ‪. .........‬وباســتجواب املدعــى عليــه الثانــي أقــر مبــا‬\n‫نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن حيــث‬\n‫الوصــف والوقــت والكيفيــة ‪.‬وباســتجواب املدعــى عليــه الثالــث أقــر‬\n‫مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران مــن‬\n‫حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال مــن‬\n‫املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث‬\n‫أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن اتهــام وباســتمرار‬\n                          ‫مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪.‬‬\n‫البالغ التاســع عشــر ‪ :‬ـ بالغ املواطن ‪........./‬عن تعرض ســيارته التي من‬\n\n\n                                                                                        ‫‪36‬‬\n\f     ‫نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة‪ .........‬لكســر الزجاجــة اخللفيــة‬\n     ‫مــن اجلهــة اليمنــى وســرقة جــوال مــن نــوع (‪ )....‬ومحفظتــه وبداخلهــا‬\n     ‫اإلثباتــات الشــخصية العائــدة لــه إثنــاء وقوفهــا أمــام منزلــه بحــي ‪..........‬‬\n     ‫املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح أنهــا‬\n     ‫تقــع بحــي ‪ .........‬و شــوهدت الســيارة املذكــورة واقفــة أمــام منــزل‬\n     ‫املبلــغ املذكــور وشــوهدت الزجاجــة اخللفيــة مــن جهــة اليمنــى متعرضــة‬\n     ‫للكســر حيــث شــوهد بعثــره باحملتويــات الداخليــة للســيارة‪ .‬وبضبــط‬\n     ‫أقــوال املبلــغ ‪......... :‬أفــاد عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪)....‬‬\n     ‫اللــون (‪ )....‬رقــم اللوحــة ‪.........‬لكســر الزجاجــة اخللفيــة مــن اجلهة اليمنى‬\n     ‫وســرقة جــوال مــن نــوع (‪ )....‬ومحفظتــه وبداخلهــا اإلثباتــات الشــخصية‬\n     ‫العائــدة لــه أثنــاء وقوفهــا أمــام منزلــه بحــي ‪. .........‬وباســتجواب املدعــى‬\n     ‫عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه‬\n     ‫رفــق زمالئــه‪ ........./‬و‪ ........./‬واحلــدث‪ ......... /‬واحلــدث‪ ......... /‬علــى‬\n     ‫دراجاتهــم الناريــة إلــى حــي ‪ .........‬وكســر الزجاجــة اخللفيــة اليمنــى‬\n     ‫للســيارة املذكــورة وســرقة جــوال مــن نــوع (‪)....‬ومحفظــة بداخلهــا‬\n     ‫اإلثباتــات الشــخصية ورميهــا بعــد التأكــد مــن عــدم وجــود أي مبالــغ‬\n     ‫ماليــة فيهــا أثنــاء وقوفهــا بحــي ‪. .........‬وباســتجواب املدعــى عليــه الثانــي‬\n     ‫أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن‬\n     ‫حيــث الوصــف والوقــت والكيفيــة‪ .‬وباســتجواب املدعــى عليــه الثالــث‬\n     ‫أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران‬\n     ‫مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال‬\n     ‫مــن املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث‬\n     ‫أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن اتهــام وباســتمرار‬\n\n\n‫‪37‬‬\n\f                             ‫مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪.‬‬\n‫البــاغ العشــرون ‪ :‬ـ بــاغ املواطنة‪........./‬عــن تعــرض ســيارتها التــي مــن‬\n‫نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة ‪ .........‬لكســر الزجاجــة اخللفيــة‬\n‫مــن اجلهــة اليمنــى أثنــاء وقوفهــا أمــام منزلــه بحــي ‪ ..........‬املعاينـ ــة ‪ :‬مت‬\n‫االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح أنهــا تقــع بحــي‬\n‫‪ .........‬وشــوهدت الســيارة املذكــورة واقفــة أمــام منــزل املبلــغ املذكــور‬\n‫وشــوهدت الزجاجــة اخللفيــة مــن اجلهــة اليمنــى متعرضــة للكســر حيــث‬\n‫شــوهد بعثــرة باحملتويــات الداخليــة للســيارة‪ .‬وبضبــط أقــوال املبلغــة‪:‬‬\n‫‪ .........‬أفــادت عــن تعــرض ســيارتها التــي مــن نــوع (‪ )....‬م(‪ )....‬اللــون‬\n‫(‪ )....‬رقــم اللوحــة ‪ .........‬لكســر الزجاجــة اخللفيــة مــن اجلهــة اليمنــى‬\n‫أثنــاء وقوفهــا أمــام منزلــه بحــي ‪ ..........‬وباســتجواب املدعــى عليــه‬\n‫األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه رفــق‬\n‫زمالئــه‪ .........‬و‪ .........‬واحلــدث ‪ .........‬واحلــدث ‪ .........‬علــى دراجاتهــم‬\n‫الناريــة إلــى 