 الزجاجــة األماميــة مــن‬\n     ‫اجلهــة اليمنــى وبعثــرة مــا بداخلهــا أثنــاء وقوفهــا ‪.‬وباســتجواب املدعــى‬\n     ‫عليــه الثانــي أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه‬\n     ‫املذكــور مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة‬\n     ‫كال مــن املدعــى عليــه بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث‬\n     ‫أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن اتهــام وباســتمرار‬\n                     ‫مواجهتهمــا بزميلهمــا املذكــور اعتــرف الثانــي بالقضيــة‪.‬‬\n     ‫البــاغ الثانــي والعشــرون ‪ :‬ـ بــاغ املواطن‪........./‬عــن تعــرض ســيارته‬\n     ‫التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة‪ .........‬لكســر‬\n     ‫الزجاجــة األماميــة مــن اجلهــة اليمنــى وســرقة جهــاز (الب تــوب) مــن نــوع‬\n     ‫(‪ )....‬اللــون (‪)....‬وعــدد ثــاث جــواالت مــن نــوع (‪ )....‬أثنــاء وقوفهــا بقريــة‬\n     ‫‪ ..........‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح‬\n\n\n‫‪39‬‬\n\f‫أنهــا تقــع بقريــة ‪.........‬شــوهدت الســيارة املذكــورة واقفــة أمــام منــزل‬\n‫املبلــغ املذكــور وشــوهدت الزجاجــة األماميــة مــن جهــة اليمــن متعرضــة‬\n‫للكســر حيــث شــوهد بعثــرة باحملتويــات الداخليــة للســيارة ‪.‬وبضبــط‬\n‫أقــوال املبلــغ ‪ ......... :‬أفــاد عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪)....‬‬\n‫اللــون (‪ )....‬رقــم اللوحــة (‪ ).........‬لكســر الزجاجــة األماميــة مــن اجلهــة‬\n‫اليمنــى وســرقة جهــاز (الب تــوب) مــن نــوع (‪ )....‬اللــون (‪ )....‬وعــدد ثــاث‬\n‫جــواالت مــن نــوع (‪ )....‬أثنــاء وقوفهــا بقريــة ‪..........‬وباســتجواب املدعــى‬\n‫عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه‬\n‫رفــق زمالئــه‪ ........./‬و‪ ........./‬واحلــدث‪ ......... /‬واحلــدث ‪ ........./‬علــى‬\n‫دراجاتهــم الناريــة إلــى قريــة ‪.........‬وكســر الزجاجــة األماميــة مــن‬\n‫اجلهــة اليمنــى وســرقة جهــاز (الب تــوب) مــن نــوع (‪ )....‬اللــون (‪ )....‬وعــدد‬\n‫ثــاث جــواالت مــن نــوع (‪ )....‬أثنــاء وقوفهــا بقريــة الشــقيق ‪.‬وباســتجواب‬\n‫املدعــى عليــه الثانــي أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال‬\n‫زميلــه املذكــور مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت‬\n‫مواجهــة كال مــن املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء يف‬\n‫اعترافــه حيــث أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن اتهام‬\n ‫وباســتمرار مواجهتهمــا بزميلهمــا املذكــور اعتــرف الثانــي بالقضيــة‪.‬‬\n‫البــاغ الثالــث والعشــرون‪ - :‬بــاغ املواطــن ‪ .........‬عــن تعــرض ســيارته‬\n‫التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقم اللوحة ‪ .........‬لكســر الزجاجة‬\n‫اخللفيــة جهــة اليمــن وبعثــرة مــا بداخلهــا أثنــاء وقوفهــا أمــام منزلــه بقريــة‬\n‫‪ ..........‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح‬\n‫أنهــا تقــع بقريــة ‪.........‬شــوهدت الســيارة املذكــورة واقفــة أمــام منــزل‬\n‫املبلــغ ‪ ،‬وشــوهدت الزجاجــة اخللفيــة مــن جهــة اليمــن متعرضــة للكســر‬\n\n\n                                                                                            ‫‪40‬‬\n\f     ‫حيــث شــوهد بعثــره باحملتويــات الداخليــة للســيارة‪ .‬وبضبــط أقــوال‬\n     ‫املبلــغ ‪ .............. :‬أفــاد عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪)....‬‬\n     ‫اللــون (‪ )....‬رقــم اللوحــة ‪ .........‬لكســر الزجاجــة اخللفيــة جهــة اليمــن‬\n     ‫وبعثــرة مــا بداخلهــا أثنــاء وقوفهــا أمــام منزلــه بقريــة ‪ ..........‬وباســتجواب‬\n     ‫املدعــى عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ‬\n     ‫اجتــه رفــق زمالئــه‪ ........./‬و‪ ........./‬واحلــدث‪ ......... /‬واحلــدث‪......... /‬‬\n     ‫علــى دراجاتهــم الناريــة إلــى قريــة ‪ .........‬وكســر الزجاجــة اخللفيــة جهــة‬\n     ‫اليمــن أثنــاء وقوفهــا بقريــة (‪.)....‬وباســتجواب املدعــى عليــه الثانــي أقــر‬\n     ‫مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن‬\n     ‫حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال مــن‬\n     ‫املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث‬\n     ‫أنكــر املذكــوران يف البدايــة مانســب إليهمــا مــن اتهــام وباســتمرار‬\n                     ‫مواجهتهمــا بزميلهمــا املذكــور اعتــرف الثانــي بالقضيــة ‪.‬‬\n     ‫البــاغ الرابــع والعشــرون ‪ :‬ـ بــاغ املواطــن ‪......... /‬عــن تعــرض ســيارته‬\n     ‫التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقم اللوحة ‪ .........‬لكســر الزجاجة‬\n     ‫األماميــة مــن اجلهــة اليســرى وســرقة جــوال مــن نــوع (‪ )....‬أثنــاء وقوفهــا‬\n     ‫أمــام منزلــه بقريــة ‪..........‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع‬\n     ‫احلادثــة حيــث اتضــح أنهــا تقــع بقريــة ‪.........‬شــوهدت الســيارة املذكــورة‬\n     ‫واقفــة أمــام منــزل املبلــغ ‪ ،‬وشــوهدت الزجاجــة األماميــة من جهة اليســار‬\n      ‫متعرضــة للكســر حيــث شــوهد بعثــره باحملتويــات الداخليــة للســيارة ‪.‬‬\n     ‫وبضبــط أقــوال املبلــغ ‪......... :‬عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬‬\n     ‫م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة ‪ .........‬لكســر الزجاجــة األماميــة مــن‬\n     ‫اجلهــة اليســرى وســرقة جــوال مــن نــوع (‪ )....‬أثنــاء وقوفهــا أمــام منزلــه‬\n\n\n‫‪41‬‬\n\f‫بقريــة ‪ ..........‬وباســتجواب املدعــى عليــه األول أقــر أنــه يف حوالــي‬\n‫الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه رفــق زمالئــه‪ .........‬و‪.........‬‬\n‫واحلــدث ‪ .........‬واحلــدث ‪ .........‬علــى دراجاتهــم الناريــة إلــى قريــة (‪)....‬‬\n‫وكســر الزجاجــة األماميــة مــن اجلهــة اليســرى وســرقة جــوال مــن نــوع‬\n‫(‪ )....‬أثنــاء وقوفهــا بقريــة ‪..........‬وباســتجواب املدعــى عليــه الثانــي أقــر‬\n‫مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن‬\n‫حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال مــن‬\n‫املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث‬\n‫أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن اتهــام وباســتمرار‬\n‫مواجهتهمــا بزميلهمــا املذكــور اعتــرف الثانــي بالقضيــة ‪.‬البــاغ‬\n‫اخلامــس والعشــرون ‪ :‬ـ بــاغ املواطن‪.........‬عــن تعــرض ســيارته التــي مــن‬\n‫نــوع (‪)....‬م(‪ )....‬رقــم اللوحة‪.........‬لكســر الزجاجــة األماميــة اليمنــى‬\n‫وســرقة شاشــة املســجل أثنــاء وقوفهــا أمــام منزلــه بقريــة ‪..........‬املعاينـ ــة‪:‬‬\n‫مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث اتضــح إنهــا تقــع بقريــة‬\n‫‪ .........‬شــوهدت الســيارة املذكــورة واقفــة أمــام منــزل املبلــغ املذكــور‬\n‫وشــوهدت الزجاجــة األماميــة مــن جهــة اليمنــى متعرضــة للكســر حيــث‬\n‫شــوهد بعثــرة باحملتويــات الداخليــة للســيارة‪ .‬وبضبــط أقــوال املبلــغ‪:‬‬\n‫‪ ..............‬عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬رقــم اللوحــة ‪.......‬‬\n‫لكســر الزجاجــة األماميــة اليمنــى وســرقة شاشــة املســجل أثنــاء وقوفها‬\n‫أمــام منزلــه بقريــة ‪ ..........‬وباســتجواب املدعــى عليــه األول أقــر أنــه يف‬\n‫حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه رفــق زمالئــه ‪.........‬‬\n‫و‪ .........‬واحلــدث ‪ .........‬واحلــدث ‪ .........‬علــى دراجاتهــم الناريــة إلــى قريــة‬\n‫‪ .........‬وكســر الزجاجــة األماميــة اليمنــى وســرقة شاشــة املســجل أثنــاء‬\n\n\n                                                                                             ‫‪42‬‬\n\f     ‫وقوفهــا بقريــة ‪..........‬وباســتجواب املدعــى عليــه الثانــي أقــر مبــا نســب‬\n     ‫إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن حيــث الوصــف‬\n     ‫والوقــت والكيفيــة‪ .‬وباســتجواب املدعــى عليــه الثانــي أقــر مبــا نســب‬\n     ‫إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن حيــث الوصــف‬\n     ‫والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال املدعــى عليــه األول‬\n     ‫بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث أنكــر املذكــوران‬\n     ‫يف البدايــة مــا نســب إليهمــا مــن اتهــام وباســتمرار مواجهتهمــا بزميلهمــا‬\n     ‫املذكــور اعتــرف الثانــي بالقضيــة ‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال مــن‬\n     ‫املدعــى عليــه األول بزميليــه املذكــوران مباجــاء يف اعترافــه حيــث‬\n     ‫أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن اتهــام وباســتمرار‬\n                     ‫مواجهتهمــا بزميلهمــا املذكــور اعتــرف الثانــي بالقضيــة‪.‬‬\n     ‫البــاغ الســادس والعشــرون ‪ :‬ـ بــاغ املواطن‪........./‬عــن تعــرض ســيارته‬\n     ‫التــي مــن نــوع (‪ )....‬اللــون (‪)....‬م(‪ )....‬رقــم اللوحــة (‪ ).........‬لكســر‬\n     ‫الزجاجــة األماميــة مــن اجلهــة اليســرى وبعثــرة مــا بداخلهــا أثنــاء وقوفهــا‬\n     ‫بقريــة ‪..........‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث‬\n     ‫اتضــح أنهــا تقــع بقريــة ‪.........‬شــوهدت الســيارة املذكــورة واقفــة أمــام‬\n     ‫منــزل املبلــغ ‪ ،‬وشــوهدت الزجاجــة األماميــة مــن جهــة اليســار متعرضــة‬\n     ‫للكســر حيــث شــوهد بعثــرة باحملتويــات الداخليــة للســيارة ‪ .‬وبضبــط‬\n     ‫أقــوال املبلــغ ‪......... :‬عــن تعــرض ســيارته التــي مــن نــوع (‪)....‬اللــون (‪)....‬‬\n     ‫م(‪ )....‬رقــم اللوحــة‪ .........‬لكســر الزجاجــة األماميــة مــن اجلهــة اليســرى‬\n     ‫وبعثــرة مــا بداخلهــا أثنــاء وقوفهــا بقريــة ‪ ..........‬وباســتجواب املدعــى‬\n     ‫عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه‬\n     ‫رفــق زمالئــه‪ ........./‬و‪ ........./‬واحلــدث‪ ......... /‬واحلــدث‪ ......... /‬علــى‬\n\n\n‫‪43‬‬\n\f‫دراجاتهــم الناريــة إلــى قريــة ‪.........‬وكســر الزجاجــة األماميــة مــن اجلهــة‬\n                                          ‫اليســرى إثنــاء وقوفهــا بقريــة (‪. )....‬‬\n‫البــاغ الســابع والعشــرون ‪ :‬ـ بــاغ املواطــن ‪......... /‬عــن تعــرض ســيارته‬\n‫التــي مــن نــوع (‪ )....‬اللــون (‪ )....‬م(‪ )....‬رقــم اللوحــة‪ .........‬لكســر‬\n‫الزجاجــة األماميــة مــن اجلهــة اليســرى وبعثــرة مــا بداخلهــا أثنــاء وقوفهــا‬\n‫بقريــة ‪ ..........‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث‬\n‫اتضــح أنهــا تقــع بقريــة ‪.........‬شــوهدت الســيارة املذكــورة واقفــة أمــام‬\n‫منــزل املبلــغ ‪ ،‬وشــوهدت الزجاجــة األماميــة مــن جهــة اليســار متعرضــة‬\n‫للكســر حيــث شــوهد بعثــره باحملتويــات الداخليــة للســيارة ‪ .‬وبضبــط‬\n‫أقــوال املبلــغ ‪ ......... :‬أفــاد عــن تعــرض ســيارته التــي مــن نــوع (‪ )....‬اللــون‬\n‫(‪)....‬م(‪ )....‬رقــم اللوحــة‪ .........‬لكســر الزجاجــة األماميــة مــن اجلهــة‬\n‫اليســرى وبعثــرة مــا بداخلهــا أثنــاء وقوفهــا بقريــة (‪.)....‬وباســتجواب‬\n‫املدعــى عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ‬\n‫اجته رفق زمالئه‪ ........./‬و‪ ........./‬واحلدث‪ ......... /‬واحلدث‪ ......... /‬على‬\n‫دراجاتهــم الناريــة إلــى قريــة ‪.........‬وكســر الزجاجــة األماميــة مــن اجلهــة‬\n‫اليســرى أثنــاء وقوفهــا بقريــة ‪..........‬وباســتجواب املدعــى عليــه الثانــي‬\n‫أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور‬\n‫مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال‬\n‫مــن املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث‬\n‫أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن اتهــام وباســتمرار‬\n                 ‫مواجهتهمــا بزميلهمــا املذكــور اعتــرف الثانــي بالقضيــة ‪.‬‬\n‫البــاغ الثامــن والعشــرون ‪ :‬ـ بــاغ املواطن‪........./‬عــن تعــرض ســيارته‬\n‫التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة ‪، ..............‬لكســر‬\n\n\n                                                                                             ‫‪44‬‬\n\f     ‫الزجاجة اخللفية من جهة اليمني وســرقة نظارة شمســية رميوت الكراج‬\n     ‫أثنــاء وقوفهــا أمــام منزلــه بحــي ‪..........‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ‬\n     ‫إلــى موقــع احلادثــة حيــث اتضــح أنهــا تقــع بحــي ‪.........‬شــوهدت الســيارة‬\n     ‫املذكــورة واقفــة أمــام منــزل املبلــغ ‪ ،‬وشــوهدت الزجاجــة اخللفيــة مــن‬\n     ‫جهــة اليمــن متعرضــة للكســر حيث شــوهد بعثــره باحملتويات الداخلية‬\n     ‫للســيارة ‪ .‬وبضبــط أقــوال املبلــغ ‪ :‬بــاغ ‪.........‬أفــاد عــن تعــرض ســيارته‬\n     ‫التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحة‪.........‬لكســر الزجاجــة‬\n     ‫اخللفيــة مــن جهــة اليمــن وســرقة نظــارة شمســية رميــوت الكــراج اثنــاء‬\n     ‫وقوفهــا أمــام منزلــه بحــي ‪ ..........‬وباســتجواب املدعى عليه األول أقر أنه‬\n     ‫يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ أجتــه رفــق زمالئــه‪........./‬‬\n     ‫و‪ ........./‬واحلــدث‪ ......... /‬واحلــدث‪ ......... /‬علــى دراجاتهــم الناريــة إلــى‬\n     ‫حــي ‪.........‬وكســر الزجاجــة اخللفيــة اليمنــى للســيارة املذكــورة وســرقة‬\n     ‫منــه نظــاره شمســيه أثنــاء وقوفهــا بحــي ‪ ..........‬وباســتجواب املدعــى‬\n     ‫عليــه الثانــي أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه‬\n     ‫املذكــور مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬وباســتجواب املدعــى‬\n     ‫عليــه الثالــث أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه‬\n     ‫املذكــوران مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت‬\n     ‫مواجهــة كال مــن املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء‬\n     ‫يف اعترافــه حيــث أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن‬\n          ‫اتهــام وباســتمرار مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪.‬‬\n     ‫البــاغ التاســع والعشــرون ‪ :‬ـ بــاغ املقيــم‪ (........./‬مينــي اجلنســية ) عــن‬\n     ‫تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪)....‬اللــون (‪ )....‬رقــم اللوحــة ‪.........‬‬\n     ‫لكســر الزجاجــة األماميــة مــن اجلهــة اليســرى وبعثــرة مــا بداخلهــا أثنــاء‬\n\n\n‫‪45‬‬\n\f‫وقوفهــا بحــي ‪ ..........‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة‬\n‫حيــث اتضــح أنهــا تقــع بحــي ‪.........‬شــوهدت الســيارة املذكــورة واقفــة‬\n‫أمــام منــزل املبلــغ املذكــور وشــوهدت الزجاجــة األماميــة مــن جهــة‬\n‫اليســرى متعرضــة للكســر حيــث شــوهد بعثــره باحملتويــات الداخليــة‬\n‫للســيارة ‪.‬وبضبــط أقــوال املبلــغ ‪......... :‬عــن تعــرض ســيارته التــي مــن نــوع‬\n‫(‪)....‬م(‪)....‬اللــون (‪ )....‬رقــم اللوحــة‪ .........‬لكســر الزجاجــة األماميــة مــن‬\n‫اجلهة اليســرى وبعثرة ما بداخلها اثناء وقوفها بحي ‪ ..........‬وباســتجواب‬\n‫املدعــى عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ‬\n‫اجتــه رفــق زمالئــه‪ ........./‬و‪ ........./‬واحلــدث‪ ......... /‬واحلــدث‪......... /‬‬\n‫علــى دراجاتهــم الناريــة إلــى حــي ‪.........‬وكســر الزجاجــة األماميــة‬\n‫اليســرى للســيارة املذكــورة أثنــاء وقوفهــا بحــي ‪ ..........‬وباســتجواب‬\n‫املدعــى عليــه الثانــي أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال‬\n‫زميلــه املذكــور مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬وباســتجواب‬\n‫املدعــى عليــه الثالــث أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال‬\n‫زميليــه املذكــوران مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪:‬‬\n‫مت مواجهــة كال مــن املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء‬\n‫يف اعترافــه حيــث أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن‬\n    ‫اتهــام وباســتمرار مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪.‬‬\n‫البــاغ الثالثــون ‪ :‬ـ بــاغ املقيــم‪ (........./‬ســوري اجلنســية ) عــن تعــرض‬\n‫ســيارته التــي (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة (‪ ).........‬لكســر‬\n‫الزجاجــة األماميــة مــن اجلهــة اليمنــى وســرقة جهــاز (‪ )...‬أثنــاء وقوفهــا‬\n‫أمــام شــقته بحــي ‪ ..........‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع‬\n‫احلادثــة حيــث اتضــح أنهــا تقــع بحــي ‪.........‬شــوهدت الســيارة املذكــورة‬\n\n\n                                                                                              ‫‪46‬‬\n\f     ‫واقفــة أمــام منــزل املبلــغ ‪ ،‬وشــوهدت الزجاجــة األماميــة مــن اجلهــة‬\n     ‫اليمنــى متعرضــة للكســر حيــث شــوهد بعثــرة باحملتويــات الداخليــة‬\n     ‫للســيارة ‪ .‬وبضبــط أقــوال املبلــغ ‪......... :‬أفــاد عــن تعــرض ســيارته التــي‬\n     ‫(‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة (‪ ).........‬لكســر الزجاجــة األماميــة‬\n     ‫مــن اجلهــة اليمنــى وســرقة جهــاز (‪ )...‬أثنــاء وقوفهــا أمــام شــقته بحــي‬\n     ‫‪ ..........‬وباســتجواب املدعــى عليــه األول أقــر أنــه يف حوالــي الســاعة‬\n     ‫الثانيــة صبــاح يــوم البــاغ اجتــه رفــق زمالئــه‪ ........./‬و‪ ........./‬واحلــدث‪/‬‬\n     ‫‪ .........‬واحلــدث‪ ......... /‬علــى دراجاتهــم الناريــة إلــى حــي ‪.........‬وكســر‬\n     ‫الزجاجــة األماميــة مــن اجلهــة اليمنــى وســرقة جهــاز (‪ )...‬أثنــاء وقوفهــا‬\n     ‫أمــام منزلــه بحــي ‪ ..........‬وباســتجواب املدعــى عليــه الثانــي أقــر مبــا‬\n     ‫نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميلــه املذكــور مــن حيــث‬\n     ‫الوصــف والوقــت والكيفيــة‪ .‬باســتجواب املدعــى عليــه الثالــث أقــر‬\n     ‫مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال زميليــه املذكــوران مــن‬\n     ‫حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪ :‬مت مواجهــة كال مــن‬\n     ‫املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء يف اعترافــه حيــث‬\n     ‫أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن اتهــام وباســتمرار‬\n                                 ‫مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪.‬‬\n     ‫البــاغ الواحــد والثالثــون ‪ :‬ـ بــاغ املقيــم‪ (........./‬مصــري اجلنســية )عــن‬\n     ‫تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوح ـ ـ ـ ـ ــة‬\n     ‫‪.........‬لكســر الزجاجــة األماميــة مــن اجلهــة اليســرى وســرقة مبلــغ وقدره‬\n     ‫أربعــة آالف وســبعمائة وواحــد عشــرين ريــا ًال أثنــاء وقوفهــا أمــام منزلــه‬\n     ‫بحــي ‪ ..........‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى موقــع احلادثــة حيــث‬\n     ‫اتضــح أنهــا تقــع بحــي ‪.........‬شــوهدت الســيارة املذكــورة واقفــة أمــام‬\n\n\n‫‪47‬‬\n\f‫منــزل املبلــغ املذكــور وشــوهدت الزجاجــة األماميــة مــن جهــة اليســرى‬\n‫متعرضــة للكســر حيــث شــوهد بعثــره باحملتويــات الداخليــة للســيارة ‪.‬‬\n‫وبضبــط أقــوال املبلــغ ‪ .............. :‬أفــاد عــن تعــرض ســيارته التــي مــن نــوع‬\n‫(‪ )....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة ‪ .........‬لكســر الزجاجــة األماميــة‬\n‫مــن اجلهــة اليســرى وســرقة مبلــغ وقــدره أربعــة آالف وســبعمائة وواحــد‬\n‫عشــرين ريــال أثنــاء وقوفهــا أمــام منزله بحي ‪ ..........‬وباســتجواب املدعى‬\n‫عليــه األول أقــر أنــه يف حوالــي الســاعة الثانيــة صبــاح يــوم البــاغ اجتــه‬\n‫رفــق زمالئــه‪ ........./‬و‪ ........./‬واحلــدث‪ ......... /‬واحلــدث‪ ......... /‬علــى‬\n‫دراجاتهــم الناريــة إلــى حــي ‪.........‬وكســر الزجاجــة األماميــة مــن اجلهــة‬\n‫اليســرى للســيارة املذكــورة وســرقة مبلــغ وقــدرة أربعــة آالف وســبعمائة‬\n‫وواحــد عشــرين ريــا ًال أثنــاء وقوفهــا أمــام منزله بحــي ‪..........‬وباســتجواب‬\n‫املدعــى عليــه الثانــي أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال‬\n‫زميلــه املذكــور مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬وباســتجواب‬\n‫املدعــى عليــه الثالــث أقــر مبــا نســب إليــه وجــاءت أقوالــه مطابقــة ألقــوال‬\n‫زميليــه املذكــوران مــن حيــث الوصــف والوقــت والكيفيــة‪ .‬املواجه ــة ‪:‬‬\n‫مت مواجهــة كال مــن املدعــى عليــه األول بزميليــه املذكــوران مبــا جــاء‬\n‫يف اعترافــه حيــث أنكــر املذكــوران يف البدايــة مــا نســب إليهمــا مــن‬\n     ‫اتهــام وباســتمرار مواجهتهمــا بزميلهمــا املذكــور اعترفــا بالقضيــة‪.‬‬\n‫البــاغ الثانــي والثالثــون ‪ :‬ـ بــاغ املقيم‪........./‬ســوري اجلنســية ) عــن‬\n‫تعــرض ســيارته التــي مــن نــوع (‪)....‬م(‪ )....‬اللــون (‪ )....‬رقــم اللوحــة‪.........‬‬\n‫لكســر الزجاجــة األماميــة مــن اجلهــة اليمنــى وبعثــرة مــا بداخلهــا أثنــاء‬\n‫وقوفهــا أمــام منزلــه بحــي ‪ ..........‬املعاينـ ــة ‪ :‬مت االنتقــال فــور البــاغ إلــى‬\n‫موقــع احلادثــة حيــث أتضــح أنهــا تقــع بحــي ‪.........‬شــوهدت الســيارة‬\n\n\n                                                                                            ‫‪48‬‬\n\f     ‫املذكــورة واقفــة أمــام منــزل املبلــغ ‪ ،‬وشــوهدت الزجاجــة األماميــة‬\n     ‫مــن جهــة اليمنــى متعرضــة للكســر حيــث شــوهد بعثــره باحملتويــات‬\n     ‫الداخليــة للســيارة ‪ .